INSERT INTO spells (id, name, school, subschool, descriptor, level, type, class_lists, casting_time, range, target, area, effect, duration, saving_throw, spell_resistance, description, material, arcane_focus, divine_focus, costly_components)
VALUES
  ('shadow_dragon_aspect', 'Shadow Dragon Aspect', 'illusion', 'shadow', 'shadow', 4, 'arcane', 'bard 4, sorcerer/wizard 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You wreathe yourself in the quasi-real form of a dragon. You gain two claw attacks (1d6 plus caster level slashing damage) and a bite attack (1d8 plus caster level piercing damage). These are primary attacks. In addition, you gain shadowy wings, granting you a fly speed equal to your base speed (good maneuverability).', NULL, NULL, false, false),
  ('shadow_enchantment', 'Shadow Enchantment', 'illusion', 'shadow', 'shadow', 3, 'arcane', 'bard 3, mesmerist 3, psychic 3, sorcerer/wizard 3', '1 standard action', 'see text', NULL, NULL, NULL, 'see text', 'Will disbelief; see text', 'yes', 'You use material from the Shadow Plane to cast a quasi-real, illusory version of a psychic, sorcerer, or wizard enchantment spell of 2nd level or lower. Spells that deal damage or have other effects work as normal unless the affected creature succeeds at a Will save. If the disbelieved enchantment spell has a damaging effect, that effect is one-fifth as strong (if applicable) or only 20% likely to occur.', NULL, NULL, false, false),
  ('shadow_endurance', 'Shadow Endurance', 'illusion', 'shadow', 'shadow', 5, 'both', 'bard 5, mesmerist 5, shaman 5, sorcerer/wizard 6, spiritualist 5', '1 standard action', 'personal', NULL, NULL, NULL, '1 hour/level until discharged, then 1 minute/level; see text', 'Will disbelief (if interacted with); varies; see text', 'see text', 'You conjure protective wisps of darkness made from shadow. If you are reduced below 0 hit points or rendered unconscious, shadow endurance immediately discharges, shunting your injured body into a hidden alcove on the Shadow Plane.', 'a fetchling’s tooth', NULL, false, false),
  ('shadow_evocation', 'Shadow Evocation', 'illusion', 'shadow', 'shadow', 5, 'arcane', 'bard 5, sorcerer/wizard 5', '1 standard action', 'see text', NULL, NULL, NULL, 'see text', 'Will disbelief (if interacted with)', 'yes', 'You tap energy from the Plane of Shadow to cast a quasi-real, illusory version of a sorcerer or wizard evocation spell of 4th level or lower. Spells that deal damage have normal effects unless an affected creature succeeds on a Will save. Each disbelieving creature takes only one-fifth damage from the attack. If the disbelieved attack has a special effect other than damage, that effect is one-fifth as strong (if applicable) or only 20% likely to occur. If recognized as a shadow evocation, a damaging spell deals only one-fifth (20%) damage. Regardless of the result of the save to disbelieve, an affected creature is also allowed any save (or spell resistance) that the spell being simulated allows, but the save DC is set according to shadow evocation’s level (5th) rather than the spell’s normal level.', NULL, NULL, false, false),
  ('shadow_invasion', 'Shadow Invasion', 'conjuration', 'summoning', NULL, 4, 'arcane', 'magus 4, sorcerer/wizard 4, summoner 4', '1 standard action', '30 ft.', NULL, '30-ft. radius emanation centered on you', NULL, '1 round/level (D); see text', 'none', 'no', 'Using a slashing motion with the spell’s focus as part of the casting of shadow invasion, you cut open a rift to the Plane of Shadow that fills a 30-foot area with shadowy energies. This area is stationary and becomes dark and gloomy, reducing the light level by one step (as darkness). Certain spells are enhanced within the area; spells of the shadow subschool that have reduced effects when disbelieved (such as shadow evocation) have their reduced effects increased by 20% (to a maximum of 90%) when determining their effects on targets within the area of shadow invasion.', NULL, 'a masterwork piercing or slashing weapon', false, false),
  ('shadow_jaunt', 'Shadow Jaunt', 'illusion', 'shadow', 'shadow', 3, 'both', 'antipaladin 3, arcanist 4, bard 4, skald 4, sorcerer/wizard 4, spiritualist 4, summoner 4, summoner (unchained) 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'you', NULL, NULL, 'instantaneous and 1 round; see text', NULL, NULL, 'You instantly travel between shadows to a point within range, though line of sight is not necessary. You leave a shadowy image of yourself in your former location and are wrapped in shadow at your destination; you can attempt a Stealth check as a free action to hide in your new location. Creatures that fail opposed Perception checks typically aren’t aware that you are no longer at your former location unless they are familiar with this spell and identify the effects. Any attack on your former location causes the shadows to disperse, allowing any creature that can see your former location to immediately notice your disappearance. In addition, for 1 round, the envelope of shadow around you grants you concealment (20% miss chance). This spell doesn’t function if there are no shadows within 5 feet of your starting location, and you can’t travel through your own shadow. If you choose a destination that has no shadows, you appear from the shadow closest to your destination that’s within the spell’s range (this could be your starting location if there are no other shadows within the spell’s range).', NULL, NULL, false, false),
  ('shadow_memory', 'Shadow Memory', 'divination', NULL, NULL, 6, 'both', 'bard 6, cleric 6, inquisitor 6, psychic 6, sorcerer/wizard 6, witch 6', '1 hour', 'personal', 'you', NULL, NULL, '1 month', 'Will negates (harmless)', 'no (harmless)', 'While casting this spell, you slowly destroy a piece of art bearing your victim’s likeness and beseech the Mantis God to grant you access to lost knowledge and lore.', 'a work of art bearing your target’s likeness worth at least 1,500 gp', NULL, false, true),
  ('shadow_of_doubt_tiefling', 'Shadow of Doubt (Tiefling)', 'enchantment', 'compulsion', 'darkness, emotion, evil, mind-affecting', 4, 'both', 'antipaladin 4, bard 4, mesmerist 4, psychic 6, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will partial (see text)', 'yes', 'You create a shadowy aura of doubt fueled by a foe’s own inner flaws.', NULL, NULL, false, false),
  ('shadow_projection', 'Shadow Projection', 'necromancy', NULL, 'evil', 4, 'arcane', 'sorcerer/wizard 4', '1 minute', 'personal', NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'With this spell, you infuse your life force and psyche into your shadow, giving it independent life and movement as if it were an undead shadow. Your physical body lies comatose while you are projecting your shadow, and your body has no shadow or reflection while the spell is in effect.', NULL, NULL, false, false),
  ('shadow_step', 'Shadow Step', 'illusion', 'shadow', 'shadow', 4, 'arcane', 'bard 4, sorcerer/ wizard 4, witch 4; Mystery shadow 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'you', NULL, NULL, 'instantaneous', 'none', 'no', 'To use this spell, you must be in an area of dim light or darkness. You enter a shadow or area of darkness, which transports you along a coiling path of shadowstuff to another dim or dark location within range.', NULL, NULL, false, false),
  ('shadow_transmutation', 'Shadow Transmutation', 'illusion', 'shadow', 'shadow', 6, 'both', 'bard 6, medium 6, shaman 6, sorcerer/wizard 6, spiritualist 6, summoner 6, witch 6', '1 standard action', 'see text', 'see text', NULL, NULL, 'see text', 'Will disbelief (if interacted with); varies; see text', 'yes; see text', 'You suffuse one subject’s body with energy from the Shadow Plane, altering its form to match a creature from the Shadow Plane.', NULL, NULL, false, false),
  ('shadow_trap', 'Shadow Trap', 'illusion', 'shadow', NULL, 1, 'both', 'antipaladin 1, bard 1, bloodrager 1, cleric 1, mesmerist 1, occultist 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./level)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You pin the target’s shadow to its current location, causing the target to become entangled and preventing it from moving farther than 5 feet from its original position, as if its shadow were anchored to the terrain. Each round on its turn, the target can attempt a new saving throw to end the effect as a full-round action. A flying creature can only hover in place or fall while entangled in this manner. This spell automatically fails when cast on a creature that doesn’t throw a shadow, and it ends if the creature is entirely in an area with no illumination.', NULL, NULL, false, false),
  ('shadow_walk', 'Shadow Walk', 'illusion', 'shadow', 'shadow', 5, 'arcane', 'alchemist 6, bard 5, sorcerer/wizard 6; Domain darkness 6; Bloodline dreamspun 6; Mystery shadow 6', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'To use the shadow walk spell, you must be in an area of dim light. You and any creature you touch are then transported along a coiling path of shadowstuff to the edge of the Material Plane where it borders the Plane of Shadow. The effect is largely illusory, but the path is quasi-real. You can take more than one creature along with you (subject to your level limit), but all must be touching each other.', NULL, NULL, false, false),
  ('shadow_weapon', 'Shadow Weapon', 'illusion', 'shadow', 'shadow', 1, 'arcane', 'bloodrager 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', '0 ft.', NULL, NULL, 'one shadow weapon', '1 minute/level', 'Will disbelief (if interacted with)', 'yes', 'Drawing upon the Plane of Shadow, you shape a quasi-real masterwork melee weapon of a type you are proficient with. You may use this weapon to make attacks as if it were a real weapon, dealing normal damage for a weapon of its type. The first time you hit a creature with the weapon, it may make a Will save to disbelieve; failure means the weapon deals damage normally, success means it only takes 1 point of damage from the weapon’s attacks. The weapon only deals 1 point of damage to objects.', NULL, NULL, false, false),
  ('shadowbard', 'Shadowbard', 'illusion', 'shadow', 'shadow', 5, 'arcane', 'bard 5', '1 standard action', 'close (25 ft. +5 ft./2 levels)', NULL, NULL, 'phantom singer', '1 round/level (D)', 'none', 'no', 'You conjure up a quasi-real phantom singer that is visible as a shifting, shadowy duplicate of yourself. The singer follows you automatically, moving as you move even if you teleport. The singer cannot be damaged, but can be dispelled. When a shadowbard comes into being, it immediately begins a bardic performance of your choice—it has access to all of the bardic performances that you do. It continues that bardic performance until you direct it as a move action to switch to a different performance. Rounds spent by a shadowbard creating a bardic performance do not decrease the number of rounds you can use your own bardic performance, nor can a shadowbard’s bardic performance be used to trigger spells that require you to begin or cease a bardic performance.', NULL, NULL, false, false),
  ('shadowfade', 'Shadowfade', 'illusion', 'shadow', NULL, 1, 'both', 'arcanist 1, bard 1, inquisitor 1, mesmerist 1, skald 1, sorcerer/wizard 1, summoner 1, summoner (unchained) 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'In areas of darkness, the target of shadowfade is invisible to creatures using darkvision to see. In areas of dim light, the target gains concealment against creatures using darkvision. This spell has no effect in areas of normal light or brighter, and is automatically dispelled if the target enters an area of bright light or takes a hostile action.', 'a blindfold', NULL, false, false),
  ('shadowform', 'Shadowform', 'illusion', 'shadow', 'shadow', 4, 'both', 'antipaladin 4, bard 4, mesmerist 4, psychic 4, sorcerer/wizard 4, spiritualist 4, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level (D)', 'Will negates (see text)', 'yes', 'You replace the target’s body with mystic shadow material drawn from the Shadow Plane, rendering the target’s physical form only quasi-real. Whenever a foe tries to directly attack the target of the spell (for instance, with a weapon or a targeted spell), that foe must attempt a Will save to disbelieve. If successful, the opponent can attack the target normally and is unaffected by shadowform for 1 round. If the foe fails, the target takes only one-fifth the normal amount of damage from the foe’s successful attack or effect, and if the attack has a special effect other than damage, that effect is one-fifth as strong as normal (if applicable) or only 20% as likely to occur. Objects automatically succeed at their Will saves against this spell.', NULL, NULL, false, false),
  ('shadowmind', 'Shadowmind', 'illusion', NULL, 'phantasm)', 2, 'both', 'antipaladin 2, cleric 3, druid 3, inquisitor 2, mesmerist 3, occultist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'up to one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You dim your targets’ perceptions of light and shadow, convincing them the space they occupy is dark. Each creature that fails its save perceives the world around it as one light level darker than its true illumination level. The spell does not change the light level outside of the targets’ perception, and does not create magical darkness.', 'a small square of black silk', NULL, false, false),
  ('shadowy_haven', 'Shadowy Haven', 'transmutation', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4', '1 standard action', 'touch', 'one 5-foot square of floor touched', NULL, NULL, '2 hours/level (D)', 'none', 'no', 'This spell functions like rope trick, except the point of entry is through a 5-foot-square instead of a rope. The space holds as many as 10 creatures of any size.', 'a small black silk bag', NULL, false, false),
  ('shambler', 'Shambler', 'conjuration', 'creation', NULL, 9, 'divine', 'druid 9, shaman 9; Domain [subdomain] Jungle 9, Plant 9', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'three or more shambling mounds, no two of which can be more than 30 ft. apart; see text', '7 days or 7 months (D); see text', 'none', 'no', 'The shambler spell creates 1d4+2 shambling mounds with the advanced template. The creatures willingly aid you in combat or battle, perform a specific mission, or serve as bodyguards. The creatures remain with you for 7 days unless you dismiss them. If the shamblers are created only for guard duty, however, the duration of the spell is 7 months. In this case, the shamblers can only be ordered to guard a specific site or location. Shamblers summoned to guard duty cannot move outside the spell’s range, which is measured from the point where each first appeared. You can only have one shambler spell in effect at one time. If you cast this spell while another casting is still in effect, the previous casting is dispelled. The shamblers have resistance to fire as normal shambling mounds do only if the terrain where they are summoned is rainy, marshy, or damp.', NULL, NULL, false, false),
  ('shamefully_overdressed', 'Shamefully Overdressed', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'bard 2, inquisitor 2, mesmerist 2, psychic 3; Mystery whimsy 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'creature touched', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'The target sees its own attire as hopelessly out of fashion, ostentatious, and embarrassing, and is filled with a compulsion to strip off all clothing. Each round, the target must spend a move action to remove a worn item that can be removed with a move action, dropping the item once it is removed. The target doesn’t distinguish between magical and non-magical items when removing them. Each round it removes an item as determined randomly from the following slots: belt, body, chest, eyes, feet, hands, head, headband, shoulders, or wrists. When determining randomly, don’t include any slots if the character has no item of that sort, and don’t include items that take more than one move action to remove. Though creatures can’t have more than one magic item in any of those slots, they can have multiple mundane items that fit each slot, in which case randomly decide which one they remove. If a target is wearing clothing that doesn’t fit in any of those slots, such as breeches or a quiver, add it to the list of possibilities at the GM’s discretion.', NULL, NULL, false, false),
  ('shapechange', 'Shapechange', 'transmutation', 'polymorph', NULL, 9, 'both', 'druid 9, shaman 9, sorcerer/wizard 9; Domain animal 9, scalykind 9; Bloodline aberrant 9; Bloodline fey 9; Mystery juju(PAP39/PZO9039) 9, juju(PZO9436) 9', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level (D)', NULL, NULL, 'This spell allows you to take the form of a wide variety of creatures. This spell can function as alter self, beast shape IV, elemental body IV, form of the dragon III, giant form II, and plant shape III depending on what form you take. You can change form once each round as a free action. The change takes place either immediately before your regular action or immediately after it, but not during the action.', NULL, 'jade circlet worth 1,500 gp', false, true),
  ('shapechanger_s_gift', 'Shapechanger’s Gift', 'transmutation', 'polymorph', NULL, 5, 'arcane', 'alchemist 5, magus 5, sorcerer/wizard 5', '1 standard action', 'touch', 'willing living creature touched', NULL, NULL, '10 minutes/level', 'Fort negates (harmless)', 'yes (harmless)', 'You change the target into an animal (as per beast shape I), humanoid (as per alter self), or monstrous humanoid (as per monstrous physique I).', 'a piece of the creature whose form you plan to grant', NULL, false, false),
  ('shaper_s_touch', 'Shaper’s Touch', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, occultist 3, sorcerer/wizard 3', '1 standard action', 'touch', 'object touched', NULL, NULL, 'concentration, up to 1 round/level', 'none', 'no', 'You create an alchemical residue on your hands that allows you to reshape any non-magical, unattended object with hardness 19 or less as though it were clay. Objects with hardness 9 or less are like soft clay, allowing you to reshape up to 1 cubic foot per round of effort. Objects with hardness 10 or higher are harder to mold, allowing you to reshape up to 1/4 cubic foot per round. The object retains its new shape for 24 hours before returning to its original shape.', NULL, NULL, false, false),
  ('shard_of_chaos', 'Shard of Chaos', 'evocation', NULL, 'chaos', 2, 'divine', 'cleric/oracle 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'dart-shaped projectile of chaotic energy', 'instantaneous (1d6 rounds)', 'Will partial (see text)', 'yes', 'You hurl a multicolored shard of congealed chaos from your holy symbol, affecting any one target in range as a ranged touch attack.', NULL, NULL, true, false),
  ('share_language', 'Share Language', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 2, druid 2, medium 1, mesmerist 1, occultist 2, psychic 1, sorcerer/wizard 2; Subdomain cooperation 2, language 2', '1 standard action', 'touch', NULL, NULL, NULL, '24 hours', 'Will negates (harmless)', 'yes (harmless)', 'You can share your facility for one particular language with another creature. For 24 hours the target can read, understand, and communicate to the best of its ability in any one language which you already know. For every 5 levels you possess, you can grant the use of another language you know, to a maximum of 5 languages at 20th level. The target must have the physical capacity to articulate sounds, make gestures, or engage in whatever other method speakers of the language use to communicate with each other in order to actually converse. If the target lacks the mental capacity to grasp an actual language, it still gains enough knowledge to respond to and carry out even extremely complex commands or suggestions coached in the language (whether written or spoken). However, since this spell does not endow the target with greater reasoning capacity, merely a temporarily enhanced vocabulary, the person offering up instructions to non-sentient creatures must take care to remove any ambiguity or guesswork.', 'a page from a dictionary', NULL, false, false),
  ('share_memory', 'Share Memory', 'divination', NULL, NULL, 2, 'arcane', 'bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, witch 2; Elemental School void 2', '1 standard action', 'touch', 'you and one creature touched', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You momentarily link your mind with the target and share a single memory of no longer than 1 minute. You can show the target one of your memories, show the target one of its own memories, or view one of the target’s memories.', NULL, NULL, false, false),
  ('share_senses', 'Share Senses', 'divination', 'scrying', NULL, 3, 'arcane', 'medium 3, psychic 3, sorcerer/wizard 4, witch 3', '1 full round', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'Spending a moment in meditation and conjuring an image of the creature to mind, you reshape your link with your familiar, causing it to functions like a scrying sensor. Upon this spell you can hear, see, or smell (any one, your choice) what your familiar is experiencing. You gain the benefits of any nonmagical special abilities your familiar has tied to the chosen sense (such as low-light vision or scent), but use your own Perception skill. You don’t need line of sight or line of effect to your familiar, but you must have an active empathic link. You may change the sense you are sharing as a standard action. Unlike other scrying spells, share senses does not allow magically or supernaturally enhanced senses to work through it, and you are unable to see in magical or natural darkness unless your familiar possesses the ability to see in such conditions.', 'a hair, scale, or feather from your familiar', NULL, false, false),
  ('share_shape', 'Share Shape', 'transmutation', 'polymorph', NULL, 3, 'both', 'ranger 3, sorcerer/wizard 4, witch 4', '1 standard action', NULL, NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'This spell functions as beast shape II, but you may only assume the form of an animal of a type identical to your animal companion or familiar. If your familiar or companion is not an animal, this spell has no effect.', NULL, NULL, false, false),
  ('share_skin', 'Share Skin', 'necromancy', NULL, NULL, 6, 'both', 'druid 6, witch 6', NULL, NULL, 'one animal touched', NULL, NULL, '1 minute/level or until you return to your body', NULL, NULL, 'You can possess an animal’s body in a manner that functions like magic jar, except as noted here. Your body vanishes while the effect lasts and you don’t require a receptacle.', NULL, NULL, false, false),
  ('shared_sacrifice', 'Shared Sacrifice', 'necromancy', NULL, 'evil', 2, 'both', 'antipaladin 3, cleric 2, shaman 2, summoner 3, witch 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You create a link to a target and can direct pain and damage through this link. You take only half damage from effects and attacks that deal hit point damage.', NULL, NULL, false, false),
  ('shared_suffering', 'Shared Suffering', 'necromancy', NULL, 'evil', 2, 'both', 'antipaladin 2, inquisitor 2, sorcerer/wizard 2, witch 2', NULL, 'long (400 ft. + 40 ft./level)', 'one living creature', NULL, NULL, 'instantaneous', 'none', 'yes', 'You infuse a dagger with necromantic energy, then plunge it into your own body.', NULL, 'a silver dagger inlaid with onyx and jade worth 100 gp', false, true),
  ('shared_training', 'Shared Training', 'divination', NULL, 'mind-affecting', 2, 'both', 'arcanist 3, bard 2, cleric 3, hunter 2, inquisitor 2, magus 2, oracle 3, paladin 2, psychic 3, ranger 2, skald 2, sorcerer 3, warpriest 3, wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level', 'none', 'no', 'Select one teamwork feat you have. You can grant this feat to allies within range for the duration of the spell. Allies do not need to meet the prerequisites of this teamwork feat. At caster level 9th, you can grant two teamwork feats you have to your allies. At caster level 13th, you can grant three teamwork feats, and at caster level 17th, you can grant up to four teamwork feats.', NULL, NULL, false, false),
  ('shared_wrath', 'Shared Wrath', 'enchantment', 'compulsion', 'emotion, mind-affecting', 4, 'divine', 'inquisitor 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions as wrath, except that you grant multiple creatures the bonuses against your designated foe. All subjects of shared wrath receive their bonuses against the same creature.', 'a thorny vine', NULL, false, false),
  ('sharesister', 'Sharesister', 'necromancy', NULL, NULL, 3, 'both', 'cleric 3, witch 3', '1 standard action', 'touch', 'you and one creature of your gender', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'While the name of this spell is sharesister, it works equally well on male or female creatures—both targets of the spell must simply be of the same gender.', 'a drop of your own blood', NULL, false, false),
  ('shatter', 'Shatter', 'evocation', NULL, 'sonic', 2, 'both', 'bard 2, bloodrager 2, cleric/oracle 2, magus 2, occultist 2, psychic 2, sorcerer/wizard 2; Domain destruction 2; Elemental School earth 2, metal 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '5-ft.-radius spread; or one solid object or one crystalline creature', 'or Target 5-ft.-radius spread; or one solid object or one crystalline creature', NULL, 'instantaneous', 'Will negates (object); Will negates (object) or Fortitude half; see text', 'yes', 'Shatter creates a loud, ringing noise that breaks brittle, non-magical objects; sunders a single solid, non-magical object; or damages a crystalline creature.', 'a chip of mica', NULL, true, false),
  ('sheet_lightning', 'Sheet Lightning', 'evocation', 'electricity', NULL, 3, 'both', 'druid 3, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', '20-ft.-radius spread', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You create a dazzling flash of electricity that fills the target area. Sheet lightning inflicts 1 point of electricity damage to all creatures within the area of effect (no save). The true power of the spell, though, lies not in the damage it inflicts but in the overwhelming pain the lightning creates. The sudden flash and jolt dazes living creatures for 1 round if they fail a saving throw. Creatures that save are instead dazzled for 1 round. Any creature wearing metal armor takes a –2 penalty to its saving throw against this spell.', NULL, NULL, false, false),
  ('shield', 'Shield', 'abjuration', NULL, 'force', 1, 'arcane', 'alchemist 1, bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1; Subdomain defense 1; Elemental School void 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'Shield creates an invisible shield of force that hovers in front of you. It negates magic missile attacks directed at you. The disk also provides a +4 shield bonus to AC. This bonus applies against incorporeal touch attacks, since it is a force effect. The shield has no armor check penalty or arcane spell failure chance.', NULL, NULL, false, false),
  ('shield_companion_aa', 'Shield Companion (AA)', 'abjuration', NULL, NULL, 1, 'both', 'antipaladin 1, druid 1, paladin 1, ranger 1, sorcerer/wizard 1, witch 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as shield other but affects only the caster’s animal companion or familiar. Spellcasters from classes that do not normally gain an animal companion, familiar, or fiendish servant but who gain one through an alternate class feature, archetype, or prestige class can prepare and cast this spell as a 1st-level spell if they are capable of casting spells.', NULL, NULL, false, false),
  ('shield_companion_acg', 'Shield Companion (ACG)', 'abjuration', NULL, NULL, 2, 'both', 'paladin 2, ranger 2, shaman 2, sorcerer/wizard 3, summoner/unchained summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'your companion creature', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell creates a special mystical connection between you and your companion creature—animal companion, bonded mount, eidolon, or familiar—which allows you to transfer its wounds to you. The creature gains a +1 deflection bonus to AC and a +1 resistance bonus on saves. As an immediate action when your companion takes damage, you can take that damage yourself to prevent your companion from being harmed (similar to shield other, except the damage is not split between you and the target). Forms of harm that do not involve the loss of hit points, such as charm effects, temporary ability damage, level drain, and death effects, are not affected. If the creature suffers a reduction of hit points from a lowered Constitution score, you cannot take that damage on behalf of your companion creature because it is not hit point damage. When the spell ends, damage directed to you by the spell is not reassigned to the subject.', NULL, NULL, false, false),
  ('shield_of_darkness', 'Shield of Darkness', 'evocation', NULL, 'darkness, shadow', 3, 'divine', 'antipaladin 3, cleric 3, inquisitor 3, shaman 3, spiritualist 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You shield yourself with darkness, reducing the illumination level in your space to magical darkness and granting you total concealment. Your opponents are automatically aware of which squares you occupy, preventing you from attempting Stealth checks using this concealment unless every square adjacent to you has an illumination level of darkness or lower. Shield of darkness does not hinder your vision, and creatures that can see in magical darkness ignore this effect.', NULL, NULL, false, false),
  ('shield_of_dawn', 'Shield of Dawn', 'evocation', NULL, 'fire, good, light', 4, 'both', 'bard 4, cleric/oracle 4, magus 4, paladin 4, ranger 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'see text', 'no', 'You create a disk of sunlight on one arm.', NULL, NULL, true, false),
  ('shield_of_faith', 'Shield of Faith', 'abjuration', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1; Domain glory 1; Subdomain agathion 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'This spell creates a shimmering, magical field around the target that averts and deflects attacks. The spell grants the subject a +2 deflection bonus to AC, with an additional +1 to the bonus for every six levels you have (maximum +5 deflection bonus at 18th level).', 'parchment with a holy text written on it', NULL, false, false),
  ('shield_of_fortification', 'Shield of Fortification', 'abjuration', NULL, NULL, 1, 'divine', 'cleric 2, inquisitor 1, paladin 1, psychic 2; Mystery succor 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'You create a magical barrier that protects a target’s vital areas. When the target is struck by a critical hit or a sneak attack, there is a 25% chance that the critical hit or sneak attack is negated and damage is instead rolled normally. This benefit does not stack with other effects that can turn critical hits or sneak attacks into normal attacks, such as the fortification armor special ability.', NULL, NULL, true, false),
  ('shield_of_law', 'Shield of Law', 'abjuration', NULL, 'lawful', 8, 'divine', 'cleric/oracle 8; Domain law 8; Mystery godclaw 8', '1 standard action', '20 ft.', NULL, NULL, NULL, '1 round/level (D)', 'see text', 'yes (harmless)', 'A dim, blue glow surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by chaotic creatures, and slowing chaotic creatures when they strike the subjects. This abjuration has four effects.', NULL, 'a reliquary worth 500 gp', false, true),
  ('shield_of_shards', 'Shield of Shards', 'transmutation', NULL, NULL, 1, 'both', 'bloodrager 1, cleric 2, inquisitor 2, magus 2, medium 2, paladin 1, shaman 2', '1 standard action', 'personal', 'one shield you wield', NULL, NULL, '1 round/level', 'none', 'no', 'This defensive spell must be cast on a shield you are currently wielding, and fractures the shield into two shards, plus one additional shard per 2 caster levels (to a maximum of 12 shards at 20th level). While shield of shards is active, you lose your shield’s bonus to AC as its broken pieces orbit you. On your turn, you can direct the shards to attack an adjacent opponent as a move action. The shards’ attack bonus is equal to your caster level + the modifier for the ability score that determines your spell save DCs. The shards deal an amount of slashing and piercing damage equal to 1d4 points + 1 point per shard beyond the first, and have a threat range of 19–20. They are considered magic weapons for the purpose of bypassing damage reduction. Additionally, if your shield is made from a special material (such as adamantine), the shards penetrate damage reduction and hardness as if they were weapons made from the same material.', NULL, 'a shield', false, false),
  ('shield_of_wings', 'Shield of Wings', 'transmutation', NULL, 'fire', 3, 'divine', 'cleric 3, inquisitor 3, paladin 3, ranger 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (see below)', 'none', 'no', 'You gain five burning wings that grant a fly speed equal to the number of wings × 10 (average maneuverability) for an initial fly speed of 50 feet. The first time in a round where you would take fire damage, a wing vanishes (reducing the fly speed granted) and you gain fire resistance 30 for the remainder of the round.', NULL, NULL, true, false),
  ('shield_other', 'Shield Other', 'abjuration', NULL, NULL, 2, 'divine', 'cleric/oracle 2, inquisitor 2, paladin 2, psychic 2; Domain community 2, protection 2; Subdomain friendship 2, martyr 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell wards the subject and creates a mystic connection between you and the subject so that some of its wounds are transferred to you. The subject gains a +1 deflection bonus to AC and a +1 resistance bonus on saves. Additionally, the subject takes only half damage from all wounds and attacks (including those dealt by special abilities) that deal hit point damage. The amount of damage not taken by the warded creature is taken by you. Forms of harm that do not involve hit points, such as charm effects, temporary ability damage, level draining, and death effects, are not affected. If the subject suffers a reduction of hit points from a lowered Constitution score, the reduction is not split with you because it is not hit point damage. When the spell ends, subsequent damage is no longer divided between the subject and you, but damage already split is not reassigned to the subject.', NULL, 'a pair of platinum rings worth 50 gp worn by both you and the target', false, true),
  ('shield_speech', 'Shield Speech', 'abjuration', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 1, druid 1, sorcerer/wizard 1', '1 standard action', '10 ft.', 'you and one other creature', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You can securely communicate with one creature within range. So long as your target remains within 10 feet of you, you and it can speak freely to each other without fear of being overheard. Communications that involve shield speech cannot be spied on, such as with a divination spell, and observers of the conversation can tell you are communicating but cannot read lips or hear the conversation unless they are the target of the spell. If you or the target speak to any other creatures, they can hear you normally (only communication between you and the target is protected).', NULL, NULL, false, false),
  ('shield_the_banner', 'Shield the Banner', 'abjuration', NULL, NULL, 1, 'divine', 'adept 1, cleric/oracle 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Will negates', 'no', 'This spell is used to protect one of a tribe’s most valuable possessions: its tribal banner. Any creature (other than a member of the tribe which the standard represents) attempting to directly attack or touch the standard must make a Will save. This spell functions as sanctuary, but only protects a standard or banner. In addition, the spell grants a +2 bonus to the standard’s hardness, and +10 to the standard’s hit points for the duration of the spell.', NULL, NULL, true, false),
  ('shifted_steps', 'Shifted Steps', 'illusion', 'glamer', 'sonic', 2, 'both', 'alchemist 2, antipaladin 2, bard 2, inquisitor 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object up to 10 feet across', NULL, NULL, 'concentration + 1 round/level (D)', 'Will negates (harmless) and Will disbelief (if interacted with); see text', 'no', 'You cause the target to sound as if it is elsewhere within range, including its movements, speech, and all other sounds. As long as you concentrate, you can cause the sound’s apparent location to change as you see fit within range from your current location.', NULL, NULL, false, false),
  ('shifting_sand', 'Shifting Sand', 'transmutation', NULL, 'earth', 3, 'both', 'druid 3, sorcerer/wizard 3; Bloodline deep earth 3; Elemental School earth 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft. spread', NULL, '1 round/level (D)', 'Reflex negates; see text', 'no', 'You cause an earthen or sandy surface to shift and churn within the area. The shifting sand obliterates tracks and is considered difficult terrain. Acrobatics checks in the area take a penalty equal to your caster level (maximum +10). Creatures entering or beginning their turn in the shifting sand must make a Reflex save each round or become entangled until the beginning of their next turn. If they attempt to move while entangled, they must make a second Reflex save or fall prone. Creatures with the stability racial trait (like dwarves) may apply it as a bonus on their saving throws.', 'a handful of sand', NULL, false, false),
  ('shifting_shadows', 'Shifting Shadows', 'evocation', NULL, 'darkness', 3, 'arcane', 'bard 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius emanation centered on a point in space', NULL, '1 round/level (D)', 'none, see text', 'no', 'Waves of shifting shadows obscure the appearance of all creatures caught within the emanation, making it harder to tell friends from foes.', 'a drop of ink', NULL, false, false),
  ('shillelagh', 'Shillelagh', 'transmutation', NULL, NULL, 1, 'arcane', 'druid 1; Mystery wood 1', '1 standard action', 'touch', 'one touched non-magical oak club or quarterstaff', NULL, NULL, '1 min./level', 'Will negates (object)', 'yes (object)', 'Your own non-magical club or quarterstaff becomes a weapon with a +1 enhancement bonus on attack and damage rolls. A quarterstaff gains this enhancement for both ends of the weapon. It deals damage as if it were two size categories larger (a Small club or quarterstaff so transmuted deals 1d8 points of damage, a Medium 2d6, and a Large 3d6), +1 for its enhancement bonus. These effects only occur when the weapon is wielded by you. If you do not wield it, the weapon behaves as if unaffected by this spell.', NULL, NULL, true, false),
  ('shining_cord', 'Shining Cord', 'evocation', NULL, 'force', 3, 'arcane', 'magus 3', '1 standard action', '30 ft.', '1 creature', NULL, NULL, '1 round/level or instantaneous (see below)', 'Fortitude partial (see below)', 'yes', 'When you cast this spell, you make a ranged touch attack against a single opponent within 30 feet. If you hit, a thin silver strand extends from your body to its, forming a connection that allows you to anticipate its actions. For the duration of the spell, you receive a +5 insight bonus on all Perception and Sense Motive checks opposed by the target. You gain a +5 insight bonus on all Spellcraft checks made to identify your opponent’s spell as part of a counterspelling attempt. Finally, you gain a +2 dodge bonus to your AC against attacks made against you by the target.', 'a small length fine of silver chain worth 100 gp', NULL, false, true),
  ('shining_scales', 'Shining Scales', 'evocation', NULL, 'draconic, good', 3, 'arcane', 'alchemist 3, bloodrager 3, medium 3, sorcerer/wizard 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a drop of mercury', NULL, false, false),
  ('shock_arrow', 'Shock Arrow', 'evocation', NULL, 'electricity', 1, 'both', 'bloodrager 1, cleric/oracle 2, druid 1, inquisitor 1, magus 1, paladin 1, ranger 1', '1 standard action', 'Medium (100 ft. + 10 ft./level) or see text', NULL, NULL, 'arrow of electricity', 'instantaneous or 1 round (see text)', 'none', 'yes', 'You create an arrow made of crackling electricity, which you may use for one of two effects.', 'one arrow', NULL, false, false),
  ('shock_shield', 'Shock Shield', 'abjuration', NULL, 'electricity, force', 1, 'arcane', 'alchemist 1, bloodrager 1, magus 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minutes/level (D)', NULL, NULL, 'This spell creates an invisible shield similar to but not as strong as the shield spell. This shield hovers in front of you and negates magic missile attacks directed at you. The disk provides a +2 shield bonus to AC. This bonus applies against incorporeal touch attacks. At any time, as a free action, you may dismiss your shield, at which point it deals 1d6 points of electrical damage to all creatures within a 5-foot burst, including you. A Reflex saving throw halves the damage.', NULL, NULL, false, false),
  ('shocking_grasp', 'Shocking Grasp', 'evocation', NULL, 'electricity', 1, 'arcane', 'bloodrager 1, magus 1, sorcerer/wizard 1; Bloodline djinni 1; Elemental School air 1, metal 1', '1 standard action', 'touch', 'creature or object touched', NULL, NULL, 'instantaneous', 'none', 'yes', 'Your successful melee touch attack deals 1d6 points of electricity damage per caster level (maximum 5d6). When delivering the jolt, you gain a +3 bonus on attack rolls if the opponent is wearing metal armor (or is carrying a metal weapon or is made of metal).', NULL, NULL, false, false),
  ('shocking_image', 'Shocking Image', 'illusion', 'figment', 'electricity', 4, 'arcane', 'bard 4, bloodrager 4, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'none', 'see text', 'This spell works like mirror image, except the illusory doubles it creates discharge an electric shock when destroyed. An opponent that uses a melee attack to destroy one of your images takes 2d6 points of electricity damage. You must overcome a target’s spell resistance the first time you deal this electricity damage to it. Failure renders the target immune to damage from this spell.', NULL, NULL, false, false),
  ('shout', 'Shout', 'evocation', NULL, 'sonic', 4, 'arcane', 'bard 4, bloodrager 4, magus 4, sorcerer/wizard 4; Domain destruction 5; Elemental School air 4, metal 4', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Fortitude partial or Reflex negates (object); see text', 'yes (object)', 'You emit an ear-splitting yell that deafens and damages creatures in its path. Any creature within the area is deafened for 2d6 rounds and takes 5d6 points of sonic damage. A successful save negates the deafness and reduces the damage by half. Any exposed brittle or crystalline object or crystalline creature takes 1d6 points of sonic damage per caster level (maximum 15d6). An affected creature is allowed a Fortitude save to reduce the damage by half, and a creature holding fragile objects can negate damage to them with a successful Reflex save. A shout spell cannot penetrate a silence spell.', NULL, NULL, false, false),
  ('shrink_item', 'Shrink Item', 'transmutation', NULL, NULL, 3, 'arcane', 'occultist 3, psychic 3, sorcerer/wizard 3', '1 standard action', 'touch', 'one touched object of up to 2 cu. ft./level', NULL, NULL, '1 day/level; see text', 'Will negates (object)', 'yes (object)', 'You are able to shrink one non-magical item (if it is within the size limit) to 1/16 of its normal size in each dimension (to about 1/4,000 the original volume and mass). This change effectively reduces the object’s size by four categories. Optionally, you can also change its now shrunken composition to a cloth-like one. Objects changed by a shrink item spell can be returned to normal composition and size merely by tossing them onto any solid surface or by a word of command from the original caster. Even a burning fire and its fuel can be shrunk by this spell. Restoring the shrunken object to its normal size and composition ends the spell.', NULL, NULL, false, false),
  ('shroud_of_darkness', 'Shroud of Darkness', 'evocation', NULL, 'darkness', 4, 'both', 'antipaladin 4, bard 5, cleric 5, inquisitor 5, mesmerist 4, shaman 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'With a dark incantation and a gesture of your hand over your eyes, you cause a shroud of darkness to descend upon the targets of this spell. The subjects treat the light level as two steps lower than normal for the duration of this spell. Bright light becomes dim light, normal light becomes darkness, and areas of dim light and darkness become supernaturally dark (as darkness, but even creatures with darkvision cannot see).', 'a pinch of black sand', NULL, true, false),
  ('shroud_of_innocuity', 'Shroud of Innocuity', 'illusion', 'glamer', NULL, 3, 'both', 'bard 3, medium 3, mesmerist 3, psychic 3, shaman 3, sorcerer/wizard 3, witch 3', '1 minute', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level (D)', 'none (harmless); see text', 'no', 'All affected creatures are veiled with a commonplace appearance.', NULL, NULL, false, false),
  ('sickening_entanglement', 'Sickening Entanglement', 'transmutation', NULL, 'poison', 2, 'divine', 'druid 2, ranger 2, shaman 2 Saving Throw Reflex partial and Fort negates (see text); Spell Resistance no', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as entangle, except the plants are coated with an irritating sap that creates a painful, itching rash on creatures that touch them. Any creature that enters the area or ends its turn there must succeed at a Fortitude save or be sickened as long as it remains in the area and for 1d4 rounds afterward. This is a poison effect.', NULL, NULL, false, false),
  ('sickening_strikes', 'Sickening Strikes', 'transmutation', NULL, 'disease', 2, 'both', 'alchemist 2, antipaladin 2, druid 2, magus 3, ranger 4, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'Fort negates; see text', 'yes', 'You are imbued with disease, and any creature you strike with a melee attack must make a Fortitude save or be sickened for 1 minute. Creatures that are immune to disease are immune to this sickened effect.', NULL, NULL, false, false),
  ('siege_of_trees', 'Siege of Trees', 'transmutation', NULL, NULL, 7, 'divine', 'druid 7', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You imbue inanimate plants with limited mobility and a semblance of life. Each plant targeted acts as a light catapult until the end of the spell’s duration, though you must spend a standard action to aim each of these tree catapults before the first time they fire, and anytime thereafter when you want the trees to fire at a new target. The catapult uses your caster level as its targeting bonus. With a free action, you can command one or all of the trees under your command to stop firing. You do not need to supply ammunition to these tree catapults; they will automatically load themselves with rocks and boulders in the area, digging them deep from the ground if need be. You can supply the trees ammunition if you desire. The tree will not load flaming ammunition, and these catapult trees cannot be affected by energy siege shot if the energy selected is fire.', NULL, NULL, true, false),
  ('siege_scatter_dwarf', 'Siege Scatter (Dwarf)', 'evocation', NULL, 'earth', 4, 'divine', 'druid 5, ranger 4, shaman 5', '1 round', 'long (400 ft. + 40 ft./level)', NULL, '50-ft.-radius spread', NULL, 'instantaneous', 'Reflex partial (see text)', 'yes (harmless)', 'A roiling blast of rough rock and dirt scatters along the ground in the area, dealing 1d6 points of slashing damage per 2 caster levels (maximum 5d6) to all creatures on the ground in the area, even on a successful saving throw. Creatures in the area that fail the Reflex save fall prone and are knocked to the nearest edge of the area, taking 1d6 points of bludgeoning damage for every 10 feet they travel this way. Creatures that did not move during the past round and those with the stability racial trait gain a +4 bonus on the saving throw.', NULL, NULL, false, false),
  ('sift', 'Sift', 'divination', NULL, NULL, 0, 'both', 'bard 0, inquisitor 0, psychic 0', '1 standard action', '30 ft.', NULL, 'one 10-ft. cube', NULL, 'instantaneous', 'none', 'no', 'You examine an area at range as if you were searching for fine details with the Perception skill. Make a Perception check with a -5 penalty, modified as normal for conditions. No penalty is applied for distance. Apply the result against the DC for any hidden features, such as secret doors, traps, or hidden treasure. You must be able to see the area you are attempting to search, and you only find details that can be perceived with sight or touch. Sift detects only objects and features, not actual creatures.', NULL, NULL, false, false),
  ('sign_of_the_faithful', 'Sign of the Faithful', 'transmutation', NULL, NULL, 0, 'divine', 'cleric/oracle 0, druid 0, paladin 1, ranger 1', '1 standard action', 'medium (100 f. + 10 f./level)', 'one creature/level', NULL, NULL, '1 hour/level', 'none', 'no', 'As message, except the only information you can transmit is that you are a worshiper of the designated deity. Once notified, the target can reply that he understands your sign. The spell transmits meaning, not sound, and transcends language barriers.', NULL, 'holy symbol', false, false),
  ('sign_of_wrath', 'Sign of Wrath', 'evocation', 'force', NULL, 6, 'both', 'cleric 6, sorcerer/wizard 6', '1 standard action', 'personal', NULL, '25-ft.-radius burst centered on you', NULL, 'instantaneous', 'Reflex half', 'yes', 'A giant, glowing symbol of wrath appears below you, forcibly repulsing all nearby creatures.', NULL, 'a gem worth 1,000 gp inscribed with the runic symbol of wrath', false, true),
  ('signifer_s_rally', 'Signifer’s Rally', 'conjuration', 'teleportation', 'evil', 7, 'both', 'cleric/oracle 7, sorcerer/wizard 7', '1 standard action', 'medium (100 f. + 10 f./level)', 'one willing ally/5 levels', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You teleport up to one ally per five caster levels to your location. You determine which allies you want to teleport at the time of casting; these allies have 1 round to decide to allow or refuse your spell, and they teleport immediately upon accepting. Allies are teleported as if you had cast teleport on them (your current location is at least “studied carefully” for this purpose), appearing in a puff of brimstone in a space adjacent to you. If you are in combat and your allies were not, your allies may roll initiative upon arrival but are not considered fat-footed even though they have not taken any actions. The spell does not function in areas warded against intrusion by evil creatures (such as a magic circle against evil effect).', '100 gp worth of bloodstone for every ally teleported', NULL, false, true),
  ('signs_of_the_land', 'Signs of the Land', 'divination', NULL, NULL, 3, 'divine', 'druid 3, ranger 3, shaman 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as commune with nature except it reveals up to three details about the territory you currently occupy from the following list: bodies of water, features, minerals, or plants. For each feature you learn about, you automatically know the skills you can use to discover that feature and you gain 1d6 Discovery Points toward finding it.', NULL, NULL, false, false),
  ('silence', 'Silence', 'illusion', 'glamer', NULL, 2, 'both', 'antipaladin 2, bard 2, cleric/oracle 2, inquisitor 2, mesmerist 2, psychic 2; Subdomain solitude 2', '1 round', 'long (400 ft. + 40 ft./level)', NULL, '20-ft.-radius emanation centered on a creature, object, or point in space', NULL, '1 round/level (D)', 'Will negates; see text or none (object)', 'yes; see text or no (object)', 'Upon the casting of this spell, complete silence prevails in the affected area. All sound is stopped: Conversation is impossible, spells with verbal components cannot be cast, and no noise whatsoever issues from, enters, or passes through the area. The spell can be cast on a point in space, but the effect is stationary unless cast on a mobile object. The spell can be centered on a creature, and the effect then radiates from the creature and moves as it moves. An unwilling creature can attempt a Will save to negate the spell and can use Spell Resistance, if any. Items in a creature’s possession or magic items that emit sound receive the benefits of saves and Spell Resistance, but unattended objects and points in space do not. Creatures in an area of a silence spell are immune to sonic or language-based attacks, spells, and effects.', NULL, NULL, false, false),
  ('silent_image', 'Silent Image', 'illusion', 'figment', NULL, 1, 'arcane', 'bard 1, magus 1, psychic 1, sorcerer/wizard 1; Subdomain imagination 1', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'visual figment that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)', 'concentration', 'Will disbelief (if interacted with)', 'no', 'This spell creates the visual illusion of an object, creature, or force, as visualized by you. The illusion does not create sound, smell, texture, or temperature. You can move the image within the limits of the size of the effect.', NULL, 'a bit of fleece', false, false),
  ('silent_table', 'Silent Table', 'illusion', 'glamer', NULL, 2, 'both', 'bard 2, cleric 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, '5-ft.-diameter emanation centered on an object or a point in space', NULL, '1 minute/level (D)', 'none (object)', 'no (object)', 'You protect an area against casual eavesdropping. Sounds and sonic effects that originate inside the area are muffled for anyone outside the area; Perception DCs to hear or understand sounds leaving the area increase by 20, and any saving throw DCs of these effects decrease by 2. The spell does not affect sounds that enter the area or the Perception checks of creatures inside it.', NULL, NULL, false, false),
  ('silk_to_steel', 'Silk to Steel', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 2, witch 2; Elemental School metal 2', '1 standard action', 'touch', 'one scarf', NULL, NULL, '1 round/level', 'none', 'no', 'You imbue an ordinary scarf (or similar piece of clothing) with the strength of steel without altering its weight or flexibility. Each round on your turn, you can decide to use the scarf to defend yourself (gaining a +2 shield bonus to your Armor Class) or to attack as if the scarf were a whip.', NULL, NULL, false, false),
  ('silt_sphere', 'Silt Sphere', 'illusion', 'glamer', NULL, 3, 'arcane', 'bard 3, sorcerer/wizard 3', '1 standard action', '20 ft.', NULL, NULL, '20-ft.-radius sphere centered on you', '1 minute/level (D)', 'none', 'no', 'This spell generates an illusory silt cloud that drifts around you and moves with you. The cloud provides total concealment to creatures within it (including you) when the spell is cast.', 'a smooth stone', NULL, false, false),
  ('silver_darts', 'Silver Darts', 'conjuration', 'creation', NULL, 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3, witch 3', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Reflex half', 'yes', 'A cone of silver darts springs from your hand. These darts act as a silver weapon that deals 1d6 points of piercing damage per caster level (maximum 10d6). Any creature with an armor bonus greater than +4 or a natural armor bonus greater than +4 takes 50% less damage.', 'a silver needle', NULL, false, false),
  ('silverlight', 'Silverlight', 'evocation', NULL, 'light', 3, 'both', 'bard 3, cleric/oracle 3, druid 3, paladin 3, sorcerer/wizard 3', '1 standard action', 'touch', 'object touched', NULL, NULL, '1 minute/level', 'Fortitude partial (see text)', 'No', 'As daylight, except the object touched sheds bright silvery light in a 20-foot radius. In addition to providing illumination, the area of bright light is painful to creatures that are susceptible to alchemical silver. A creature with DR/silver that begins its turn within the light of this spell is automatically dazzled and becomes sickened unless it succeeds on a Fortitude save. These effects disappear 1 round after the target leaves the silverlight. A creature that leaves the area and then returns must make a new saving throw. This spell provides dim light up to 40 feet away, but only creatures within 20 feet are subject to the above effects.', '1 sp', NULL, false, false),
  ('simulacrum', 'Simulacrum', 'illusion', 'shadow', NULL, 7, 'arcane', 'sorcerer/wizard 7, summoner 5; Elemental School void 7', '12 hours', '0 ft.', NULL, NULL, 'one duplicate creature', 'instantaneous', 'none', 'no', 'Simulacrum creates an illusory duplicate of any creature. The duplicate creature is partially real and formed from ice or snow. It appears to be the same as the original, but it has only half of the real creature’s levels or HD (and the appropriate hit points, feats, skill ranks, and special abilities for a creature of that level or HD). You can’t create a simulacrum of a creature whose HD or levels exceed twice your caster level. You must make a Disguise check when you cast the spell to determine how good the likeness is. A creature familiar with the original might detect the ruse with a successful Perception check (opposed by the caster’s Disguise check) or a DC 20 Sense Motive check.', 'ice sculpture of the target plus powdered rubies worth 500 gp per HD of the simulacrum', NULL, false, true),
  ('siphon_magic', 'Siphon Magic', 'abjuration', NULL, NULL, 5, 'both', 'cleric 5, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'none', 'no', 'This spell attempts to transfer a magical effect from a creature you touch to yourself. When you touch the creature, siphon magic attempts to end one ongoing spell that has been cast on that creature, as if via a targeted dispel magic. If you know the specific spell effect you wish to target, you can name that spell effect to target that specific spell; otherwise siphon magic begins with the highest-level spell in effect and works its way down through all spells affecting the target until it dispels one or runs out of effects, as per dispel magic.', 'a coiled length of copper wire wrapped around the palm', NULL, false, false),
  ('siphon_might', 'Siphon Might', 'necromancy', NULL, NULL, 3, 'both', 'druid 3, magus 3, sorcerer/wizard 3, summoner 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Fortitude half', 'yes', 'You drain the might of the target and transfer that power to another creature. The subject takes a penalty to Strength equal to 1d6 + 1 per 2 caster levels (maximum 1d6 + 5). This effect can’t cause the subject’s Strength score to drop below 1.', NULL, NULL, false, false),
  ('sirocco', 'Sirocco', 'evocation', NULL, 'air, fire', 6, 'both', 'druid 6, magus 6, sorcerer/wizard 6; Subdomain storms 6; Elemental School air 6, fire 6; Mystery solar 6, wind 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'cylinder (20-ft. radius, 60 ft. high)', NULL, '1 round/level (D)', 'Fortitude partial, see text', 'yes', 'A blast of furnace-hot wind blasts downward, inflicting 4d6 fire damage +1 point per caster level to all creatures in the area and knocking them prone. A successful Fortitude save halves the fire damage and negates being knocked prone. Flying creatures forced into the ground by the powerful downdraft take damage as if they fell unless they make a DC 15 Fly check, in which case they remain at their original altitude.', 'handful of fine sand cast into the air', NULL, true, false),
  ('skeleton_crew', 'Skeleton Crew', 'necromancy', NULL, NULL, 3, 'both', 'cleric 3, sorcerer/wizard 4, summoner 4, witch 4', '1 standard action', 'touch', NULL, NULL, NULL, '1 day/level', 'none', 'no', 'This spell turns corpses into skeletons that act as crew and obey your commands to the extent of their abilities.', NULL, NULL, false, false),
  ('skim', 'Skim', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, arcanist 1, bard 1, cleric 1, inquisitor 1, investigator 1, magus 1, occultist 1, oracle 1, psychic 1, shaman 1, skald 1, sorcerer 1, warpriest 1, witch 1, wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', NULL, NULL, 'This spell allows you to read written material in a quarter of the time it would normally take to read it. If you use this spell in conjunction with comprehend languages, you can read otherwise incomprehensible text four times faster than the spell indicates. If the text is fragmented, is particularly difficult to understand, or otherwise requires an ability check or skill check (such as a Linguistics check) to read quickly or at all, this spell doesn’t directly increase your reading speed, but instead grants you a +8 bonus on the check. This bonus also applies to Research checks when you research a particular topic within a library.', 'a dog-eared page', NULL, true, false),
  ('skin_tag', 'Skin Tag', 'necromancy', 'haunted', 'emotion, fear, mind-affecting', 1, 'both', 'alchemist 1, medium 1, occultist 1, shaman 1, sorcerer/wizard 1, witch 1', '1 minute', 'touch (object); 1 mile (remote effects)', '1 beverage or piece of food touched', NULL, NULL, '1 day plus 1 day/level (D)', 'none (object), Fort negates; see text', 'no (object), yes (creature)', 'You mix a malign spirit into a piece of food, a drink, or some other item to be consumed (including alchemical items, potions, elixirs, or similar items). The skin tag spell discharges when the item is consumed, affecting the creature that used the item unless it succeeds at a Fortitude save. The spirit embeds itself somewhere in the affected creature’s skin, forming a painless set of wrinkles and tags of skin that looks vaguely like a face when the haunt activates. You are considered to have a body part from the affected creature for the purpose of scrying and similar divination spells. Once per day as a standard action, you can remotely cause the spirit to make the affected creature’s skin crawl, causing the creature to become sickened for 1d4 rounds + 1 round per 2 caster levels you have (to a maximum of 5 extra rounds at 10th level) unless it succeeds at a Fortitude save. Alternatively, once per day you can remotely use a hex, a mind-affecting spell, or a necromancy spell that causes disease or possession on the affected creature. Each time you use the remote sickening or spell or hex effect, the spell’s haunt-like manifestation occurs during that round.', 'beverage or food item, plus special reagents worth 25 gp', NULL, false, true),
  ('skinsend', 'Skinsend', 'necromancy', NULL, NULL, 2, 'arcane', 'alchemist 2, occultist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 minute', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'You cause your own skin to peel off your body and animate as a magical creature you control. You may project your consciousness to your animated skin or return it to your actual body as a standard action. When your consciousness is in your body, you are helpless (except for transferring your will to your skin, or dismissing the spell).', NULL, NULL, false, false),
  ('sky_steed', 'Sky Steed', 'transmutation', 'polymorph', NULL, 3, 'divine', 'paladin 3', '1 standard action', 'touch', 'a creature you are mounted upon', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The target sprouts angelic wings and gains a fly speed equal to its base speed with average maneuverability. It also gains a bonus on Fly checks equal to your caster level.', NULL, NULL, true, false),
  ('sky_swim', 'Sky Swim', 'transmutation', NULL, 'air', 3, 'both', 'cleric/oracle 3, druid 3, shaman 3, witch 3', '1 standard action', 'touch', 'Large or smaller creature touched', NULL, NULL, '1 minute/level', 'none (harmless)', 'yes (harmless)', 'This spell grants the target the ability to swim through the air.', NULL, NULL, true, false),
  ('skyshroud', 'Skyshroud', 'divination', 'scrying', NULL, 3, 'both', 'arcanist 3, bard 3, cleric/oracle 3, skald 3, sorcerer/wizard 3, warpriest 3', '1 minute', 'long (400 ft. + 40 ft./level); see text', NULL, NULL, 'hemisphere that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)', '1 hour/level', 'none', 'no', 'The caster designates the area of a hemisphere within the spell’s range. If a solid object would block the creation of the hemisphere (such as a ceiling or wall), the spell instead conforms to the geometry of the location up to the maximum area of effect for the spell. The hemisphere displays an image of the sky as it appears directly above where the spell was cast. This effect bypasses natural impediments, such as rock or stone, that would obstruct the targeted location from the sky.', NULL, 'a jar of earth from the surface', false, false),
  ('slave_to_sin', 'Slave to Sin', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'both', 'bard 2, cleric 3, inquisitor 3, mesmerist 2, paladin 2, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round/level', 'Will negates (see below)', 'yes', 'This spell allows you to reach into an evil creature’s mind to expose and exploit its susceptibility to whichever of the seven so-called deadly sins it is most susceptible to.', 'a scrap of paper inscribed with a sin rune', NULL, true, false),
  ('slay_living', 'Slay Living', 'necromancy', NULL, 'death', 4, 'divine', 'antipaladin 4, cleric/oracle 5, shaman 6, witch 6; Domain death 5, repose 5; Mystery bones 5, reaper 5', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You can attempt to slay any one living creature. When you cast this spell, your hand seethes with eerie dark fire. You must succeed on a melee touch attack to touch the target. The target takes 12d6 points of damage + 1 point per caster level. If the target’s Fortitude saving throw succeeds, it instead takes 3d6 points of damage + 1 point per caster level. The subject might die from damage even if it succeeds on its saving throw.', NULL, NULL, false, false),
  ('sleep', 'Sleep', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'bard 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1; Subdomain night 1; Bloodline dreamspun 1', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, 'one or more living creatures within a 10-ft.-radius burst', NULL, '1 min./level', 'Will negates', 'yes', 'A sleep spell causes a magical slumber to come upon 4 HD of creatures. Creatures with the fewest HD are affected first. Among creatures with equal HD, those who are closest to the spell’s point of origin are affected first. HD that are not sufficient to affect a creature are wasted. Sleeping creatures are helpless. Slapping or wounding awakens an affected creature, but normal noise does not. Awakening a creature is a standard action (an application of the aid another action). Sleep does not target unconscious creatures, constructs, or undead creatures.', 'fine sand, rose petals, or a live cricket', NULL, false, false),
  ('sleepwalk', 'Sleepwalk', 'enchantment', 'compulsion', 'mind-affecting', 4, 'both', 'inquisitor 4, witch 4', '1 round', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'Will negates; see text', 'yes', 'You compel an unconscious or sleeping creature to rise and move in a half-awake state. The target creature staggers about if led or guided, but remains helpless for all other purposes.', 'a sprig of belladonna worth 100 gp', NULL, false, true),
  ('sleepwalking_suggestion', 'Sleepwalking Suggestion', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'bard 4, medium 3, mesmerist 4, psychic 5, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '24 hours', 'Will negates or none (see text)', 'yes', 'You compel the target creature to rise from its sleep as if sleepwalking and perform a course of activity (limited to a sentence or two). The spell takes effect immediately if the target is already asleep, or as soon as the target falls asleep if it is conscious. You can specify that the creature should wait before taking action when you give your instructions if you so choose.', 'two doses of oil of taggit worth 180 gp total', NULL, false, true),
  ('sleet_storm', 'Sleet Storm', 'conjuration', 'creation', 'cold', 3, 'both', 'bloodrager 3, druid 3, magus 3, shaman 3, sorcerer/wizard 3, witch 3; Domain weather 4; Elemental School water 3; Mystery winter 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cylinder (40-ft. radius, 20 ft. high)', NULL, '1 round/level', 'none', 'no', 'Driving sleet blocks all sight (even darkvision) within it and causes the ground in the area to be icy. A creature can walk within or through the area of sleet at half normal speed with a DC 10 Acrobatics check. Failure means it can’t move in that round, while failure by 5 or more means it falls (see the Acrobatics skill for details).', 'dust and water', NULL, true, false),
  ('slick_walls', 'Slick Walls', 'conjuration', 'creation', NULL, 2, 'arcane', 'arcanist 2, bard 2, magus 2, skald 2, sorcerer/wizard 2, summoner 2, summoner (unchained) 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft.-radius emanation centered on a point in space', NULL, '1 minute/level (D)', 'none', 'no', 'You coat all walls and ceilings within the spell’s area with a slick substance.', 'drop of oil', NULL, false, false),
  ('slipstream', 'Slipstream', 'conjuration', 'creation', 'water', 2, 'both', 'bloodrager 2, druid 2, ranger 2, sorcerer/wizard 2; Subdomain oceans 2, rivers 2; Bloodline aquatic 2; Elemental School water 2; Mystery waves 2', '1 standard action', 'touch', NULL, NULL, NULL, '10 minutes/level (D)', 'Reflex negates (harmless)', 'no', 'You create a low-cresting wave of water that carries the target along the surface of water or the ground. When moving across level ground, the target’s speed increases by 10 feet.', 'a few drops of oil and water', NULL, true, false),
  ('slough', 'Slough', 'transmutation', NULL, 'evil', 4, 'both', 'cleric 5, occultist 4, psychic 5, sorcerer/wizard 5, spiritualist 4, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'The target takes 1d4 points of Constitution damage each round as its skin loosens and splits. Once it has taken 5 or more points of Constitution damage in this way, its skin falls off to reveal its musculature. The creature ceases taking Constitution damage, but takes a –4 penalty on saving throws against disease, pain effects, or poison, and on Charisma-based skill checks with the exception of Intimidate and Use Magic Device. The creature’s skin regrows rapidly—once its Constitution damage is fully healed, its skin becomes intact once again and the penalties end.', 'a pinch of dried skin flakes', NULL, true, false),
  ('slow', 'Slow', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 3, bloodrager 4, magus 3, medium 2, occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, summoner 2, unchained summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'An affected creature moves and attacks at a drastically slowed rate. Creatures affected by this spell are staggered and can take only a single move action or standard action each turn, but not both (nor may it take full-round actions). Additionally, it takes a -1 penalty on attack rolls, AC, and Reflex saves. A slowed creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature’s jumping distance as normal for decreased speed.', 'a drop of molasses', NULL, false, false),
  ('slow_suffocation', 'Slow Suffocation', 'necromancy', NULL, 'death', 9, 'arcane', NULL, '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 minute/level', 'Fortitude negates', 'yes', 'The target is unable to breathe and is treated as if she is holding her breath (see suffocation).', NULL, NULL, false, false),
  ('slowing_mud', 'Slowing Mud', 'conjuration', 'creation', NULL, 4, 'divine', 'druid 4, shaman 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (see text)', 'Fort negates', 'yes', 'You coat the targets in thick, sticky mud. The mud acts as a slow spell and also blinds the targets. A creature can use a standard action to remove the mud from its eyes or the eyes of an adjacent creature, ending the blinded condition for that individual. Removing enough mud to end the slow effect is a full-round action. Jumping into a lake or being subject to an effect that creates a lot of water (such as create water or hydraulic push) removes all the mud in 1 round.', 'earth and water', NULL, false, false),
  ('smite_abomination', 'Smite Abomination', 'evocation', NULL, NULL, 4, 'divine', 'cleric/oracle 5, inquisitor 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level Get this book AND support this site!', NULL, NULL, 'Drawing upon positive energy, you emulate some of a paladin’s power to smite undead. Choose one undead creature as your target. Your melee attacks against that target gain a bonus equal to your Charisma or Wisdom modifier, whichever is higher, on your attack rolls, and a bonus equal to your caster level on damage rolls. Your melee attacks also bypass the target’s damage reduction. These bonuses do not stack with the bonuses from a paladin’s smite.', NULL, NULL, true, false),
  ('smug_narcissism', 'Smug Narcissism', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous* Duration 10 minute/level (D)', 'Will negates', 'yes', 'You cause your target to become overwhelmed by its own importance, talents, and attractiveness. The target cannot help but look at itself in every reflective surface at every possible opportunity. In social situations, the target always tries to comment about how attractive it is or how ugly someone else is by comparison. The target remains constantly distracted, always looking for a reflective surface to gaze upon (such as a mirror, pool of water, a polished shield, and so on). The distraction gives the target a –2 penalty on all skill checks. In combat, the target worries about enemies damaging its appearance, and focuses on defense rather than offense (casting defensive spells rather than offensive spells, using the fight defensively or total defense action, and so on).', 'a tiny shard of a mirror', NULL, false, false),
  ('snake_staff', 'Snake Staff', 'transmutation', NULL, NULL, 5, 'divine', 'cleric/oracle 5, druid 5, shaman 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates (object)', 'yes (object)', 'With a long hissing whisper, you transform ordinary pieces of wood into various sorts of snakes that immediately attack your foes.', 'a knife suitable for whittling', NULL, false, false),
  ('snapdragon_fireworks', 'Snapdragon Fireworks', 'transmutation', NULL, 'fire, light', 1, 'arcane', 'bard 2, sorcerer/ wizard 1', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'dragon-shaped fireworks', '1 round/level', 'Reflex negates', 'yes', 'A favorite display at halfling midsummer festivals, this spell lets you create fireworks in the shape of tiny dragons. Once per round, as a move action, you may designate a target 5-foot-square within range and launch a pyrotechnic in that direction. The pyrotechnic takes a zigzag path from you to that square, always missing creatures and objects in its path, and detonates in that square with a bang and a colorful burst of fire and light. Creatures in the target square take 1d4 points of fire damage and are dazzled for 1 round (Reflex half, a successful save negates the dazzled condition). Normally when this spell is used as part of a festival, the chosen target is high in the sky to increase visibility and protect observers.', 'a bundle of sulfur wrapped in cloth', NULL, false, false),
  ('snare', 'Snare', 'transmutation', NULL, NULL, 2, 'divine', 'druid 3, ranger 2; Subdomain trap 2', '3 rounds', 'touch', 'touched nonmagical circle of vine, rope, or thong with a 2ft. diameter + 2ft./level', NULL, NULL, 'Until triggered or broken', 'none', 'no', 'This spell enables you to make a snare that functions as a magic trap. The snare can be made from any supple vine, a thong, or a rope. When you cast snare upon it, the cord-like object blends with its surroundings (DC 23 Perception check for a character with the trapfinding ability to locate). One end of the snare is tied in a loop that contracts around one or more of the limbs of any creature stepping inside the circle. If a strong and supple tree is nearby, the snare can be fastened to it. The spell causes the tree to bend, straightening when the loop is triggered, dealing 1d6 points of damage to the creature trapped and lifting it off the ground by the trapped limb or limbs. If no such tree is available, the cord-like object tightens around the creature, dealing no damage but causing it to be entangled.', NULL, NULL, true, false),
  ('snow_shape', 'Snow Shape', 'transmutation', NULL, 'water', 1, 'both', 'cleric 2, druid 1, sorcerer/wizard 2', '1 standard action', 'touch', 'snow or snow-sculpted object touched, up to 5 cubic ft. + 1 cubic ft./level', NULL, NULL, 'instantaneous', 'none', 'no', 'In frozen northern lands, where the earth may be hidden beneath heavy drifts of snow, druids have developed a variation of stone shape that other spellcasters have since learned.', 'a miniature shovel', NULL, true, false),
  ('snowball', 'Snowball', 'conjuration', 'creation', 'cold, water', 1, 'both', 'druid 1, magus 1, sorcerer/wizard 1, summoner 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one ball of ice and snow', 'instantaneous', 'Fortitude partial (see text)', 'no', 'You conjure a ball of packed ice and snow that you can throw at a single target as a ranged touch attack. The snowball deals 1d6 points of cold damage per caster level (maximum 5d6) on a successful hit, and the target must make a successful Fortitude saving throw or be staggered for 1 round.', NULL, NULL, false, false),
  ('soften_earth_and_stone', 'Soften Earth and Stone', 'transmutation', NULL, 'earth', 2, 'arcane', 'druid 2; Domain earth 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '10-ft. square/level; see text', NULL, 'instantaneous', 'none', 'no', 'When this spell is cast, all natural, undressed earth or stone in the spell’s area is softened. Wet earth becomes thick mud, dry earth becomes loose sand or dirt, and stone becomes soft clay that is easily molded or chopped. You affect a 10-foot square area to a depth of 1 to 4 feet, depending on the toughness or resilience of the ground at that spot. Magical, enchanted, dressed, or worked stone cannot be affected. Earth or stone creatures are not affected.', NULL, NULL, true, false),
  ('solid_fog', 'Solid Fog', 'conjuration', 'creation', NULL, 4, 'both', 'magus 4, shaman 4, sorcerer/wizard 4, unchained summoner 4, witch 4; Subdomain cloud 4; Elemental School water 4', NULL, NULL, NULL, NULL, NULL, '1 min./level', NULL, 'no', 'This spell functions like fog cloud, but in addition to obscuring sight, the solid fog is so thick that it impedes movement. Creatures moving through a solid fog move at half their normal speed and take a -2 penalty on all melee attack and melee damage rolls. The vapors prevent effective ranged weapon attacks (except for magic rays and the like). A creature or object that falls into solid fog is slowed so that each 10 feet of vapor that it passes through reduces the falling damage by 1d6. A creature cannot take a 5-foot-step while in solid fog. Solid fog, and effects that work like solid fog, do not stack with each other in terms of slowed movement and attack penalties.', NULL, NULL, false, false),
  ('solid_note', 'Solid Note', 'conjuration', 'creation', NULL, 1, 'arcane', 'bard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one solidified musical note', 'concentration + 1 round/level', 'none', 'no', 'You give temporary physical form to a single musical note and can hang it, suspended, wherever you wish within range, allowing you to use it as hook, pulley, door blocker, or anything else your imagination desires. The exact appearance of the solid note depends on your melody. You can make it spiked or smooth, simple or convoluted, and with any color pattern you wish, however, it always has a size approximately equal to that of your outstretched hand. Once created, the solid note resists all attempts to move it but instantly disappears if enough force or weight is brought to bear against it. The note has an effective Strength equal to 10 + your caster level. It cannot hold more weight than the equivalent of a heavy load for its Strength without disappearing. Any creature that wins an opposed Strength check against the note (by pushing open a door which the note is holding shut for example) also causes it to disappear. The note can never deal actual harm to a creature and disappears if successfully attacked (AC 10 + your Charisma modifier) or overcome with a combat maneuver such as bull rush (CMD 2 + your base attack bonus + your Charisma modifier). Any creature obstructed by the solid note simply fails to budge it and loses that action for the round.', NULL, NULL, false, false),
  ('solidify_earth', 'Solidify Earth', 'transmutation', NULL, 'earth', 2, 'both', 'arcanist 2, cleric/oracle 2, druid 2, hunter 2, shaman 2, sorcerer/wizard 2, warpriest 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'up to two 10-foot cubes per level (S)', NULL, '1 minute/level', 'Reflex negates (see text)', 'no', 'Stone, dirt, and other types of earth within the area become more tightly packed.', NULL, NULL, true, false),
  ('song_of_discord', 'Song of Discord', 'enchantment', 'compulsion', 'mind-affecting, sonic', 5, 'arcane', 'bard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'creatures within a 20-ft.-radius spread', NULL, '1 round/level', 'Will negates', 'yes', 'This spell causes those within the area to turn on each other rather than attack their foes. Each affected creature has a 50% chance to attack the nearest target each round. (Roll to determine each creature’s behavior every round at the beginning of its turn.) A creature that does not attack its nearest neighbor is free to act normally for that round. Creatures forced by a song of discord to attack their fellows employ all methods at their disposal, choosing their deadliest spells and most advantageous combat tactics. They do not, however, harm targets that have fallen unconscious.', NULL, NULL, false, false),
  ('song_of_healing', 'Song of Healing', 'conjuration', 'healing', NULL, 4, 'arcane', 'bard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level or until performance ends or changes (see text)', NULL, NULL, 'You must have a bardic performance in effect to cast this spell (although this spell is called song of healing, the bardic performance need not be singing). As long as that performance continues, up to 3 creatures affected by the performance gain fast healing 2. When this bardic performance ends or you change to a different bardic performance, the fast healing granted by this spell ends as well, but all creatures affected by this spell heal 1d8 points of damage + 1 point per caster level (maximum +15) and are cured of any of the following conditions: exhausted, fatigued, nauseated, paralyzed, sickened, or stunned.', NULL, NULL, false, false),
  ('songbird', 'Songbird', 'conjuration', 'good', NULL, 1, 'both', 'bard 1, cleric 1, mesmerist 1, paladin 1, psychic 1, sorcerer/wizard 1', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'You conjure uplifting music from the wilds of Elysium, Heaven, or Nirvana to bolster other musical activities.', NULL, NULL, false, false),
  ('sonic_form', 'Sonic Form', 'transmutation', 'polymorph', 'sonic', 6, 'arcane', 'alchemist 6, bard 6, sorcerer/wizard 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon casting this spell, you keep your relative shape, but you and your equipment are transformed into semisolid sound. While in this sonic form, you take no penalties for squeezing, and you can move through spaces without penalty as if you were a creature three size categories smaller. You can make a melee touch attack once per round that deals 1d6 points of sonic damage + 1 point per caster level. You are considered incorporeal (although you cannot move through solid objects). Any non-magical attacks you make deal half damage. Magical attacks are unaffected, and you can use your magic items and other equipment as normal.', 'a pinch of dust gathered from a gravestone or a sacred shrine', NULL, false, false),
  ('sonic_scream', 'Sonic Scream', 'evocation', NULL, 'sonic', 2, 'arcane', 'bard 2, bloodrager 2, magus 2, psychic 2, sorcerer/wizard 2', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, '1 round/level or until discharged (see text)', 'Reflex half (see text)', 'yes', 'Up to three times during this spell’s duration, you can emit a cone of powerful sound as a standard action. The first cone deals 4d4 points of sonic damage to every creature in the area. The second deals 2d4 points of sonic damage to every creature in the area. The third deals 1d4 points of sonic damage to every creature in the area. A successful Reflex save against a cone halves that cone’s damage. After the third cone of sound, the spell ends. Until you use all three cones, you cannot use your voice for any magic-related purpose (bardic performance, verbal spellcasting, and so on), and cannot speak at any volume lower than a shout.', NULL, NULL, false, false),
  ('sonic_thrust', 'Sonic Thrust', 'evocation', NULL, 'sonic', 4, 'arcane', 'bard 4, sorcerer/wizard 5', '1 standard action', 'long (400 ft. + 40 ft./level)', 'see text', NULL, NULL, 'instantaneous', 'Will negates (object) or none (see text)', 'yes (object) (see text)', 'You produce a sweeping rush of sound that can hurl creatures or objects away from you, like the violent thrust version of telekinesis. You can hurl one object or creature per caster level (maximum 15) that is within range; it flies in a straight line away from you. Any objects of creatures thrown must be within 10 feet of each other. You can hurl a total weight of up to 25 pounds per caster level (maximum 375 pounds at 15th level).', NULL, NULL, false, false),
  ('soothe_construct', 'Soothe Construct', 'abjuration', NULL, NULL, 4, 'both', 'cleric/oracle 4, sorcerer/wizard 5; Elemental School metal 5', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one construct', NULL, NULL, 'instantaneous', 'none', 'no', 'You soothe the elemental spirit of a targeted construct, reducing its chance of going berserk by 1d4% per four caster levels (maximum 5d4%). If cast on a construct that has already gone berserk and you are its master, you may immediately roll d% to end the construct’s berserk state, it returns to normal functioning, and its berserk chance returns to 0%.', NULL, NULL, false, false),
  ('soothing_mud', 'Soothing Mud', 'conjuration', 'healing', 'earth, water', 3, 'divine', 'druid 3, ranger 3, shaman 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'dust, earth, sand, or water in one 5-ft. square/level', NULL, '1 round/level (D)', 'none', 'no', 'You create an area of healing mud. Water, earth, sand, and dust thicken into a wet mud. The mud functions as difficult terrain and does not sink if created in water unless weighed down by more than 100 pounds per caster level you have. Each round a creature begins its turn in or on the mud, the mud restores 1 hit point to it; this healing is unaffected by effects that increase a creature’s healing. A creature that rests partially or completely submerged in this mud for 1 full minute is also healed of 1d4 points of ability damage to an ability score of its choice. A creature can be healed of ability damage this way only once per day.', NULL, NULL, true, false),
  ('soothing_word', 'Soothing Word', 'conjuration', 'healing', NULL, 2, 'both', 'cleric/oracle 2, druid 2, inquisitor 2, paladin 2, ranger 3, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'The target of this spell causes several conditions that he suffers from to be lessened in severity one step. If he is nauseated, he is instead sickened. If he is stunned, he is instead dazed. If he is exhausted, he is fatigued. If he is frightened, he is shaken. If he is paralyzed, he is staggered. The duration of the effect is unchanged; the effect is simply reduced to the lesser version. This spell has no effect on conditions not listed above.', NULL, NULL, false, false),
  ('sotto_voce', 'Sotto Voce', 'necromancy', NULL, 'fear, mind-affecting, sonic', 0, 'both', 'bard 1, cleric/oracle 0, sorcerer/wizard 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature of 4 HD or less', NULL, NULL, '1 round', 'Will negates', 'yes', 'Your dry, rasping whisper fills a living creature of 4 or fewer Hit Dice with unnatural dread. The affected creature must make a Will save or be shaken for 1 round.', NULL, NULL, false, false),
  ('soul_bind', 'Soul Bind', 'necromancy', NULL, NULL, 9, 'both', 'cleric/oracle 9, shaman 9, sorcerer/wizard 9, witch 9; Bloodline daemon 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'corpse', NULL, NULL, 'permanent', 'Will negates', 'no', 'You draw the soul from a newly dead body and imprison it in a black sapphire gem. The subject must have been dead no more than 1 round per caster level. The soul, once trapped in the gem, cannot be returned through clone, raise dead, reincarnation, resurrection, true resurrection, or even a miracle or a wish. Only by destroying the gem or dispelling the spell on the gem can one free the soul (which is then still dead).', NULL, 'see text', false, false),
  ('soul_transfer', 'Soul Transfer', 'conjuration', 'summoning', NULL, 6, 'both', 'cleric 7, psychic 7, shaman 7, sorcerer/wizard 7, spiritualist 6, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one petitioner, incorporeal soul, or similar creature', NULL, NULL, 'permanent; see text', 'Will negates', 'yes (see text)', 'This spell functions like the spell completion option of trap the soul, except it works only on bodiless souls (such as incorporeal undead or a soul trapped in a gem) and creatures whose substance is a physical incarnation of a soul (such as a petitioner). It does not work on creatures formed from souls or planar material (such as most outsiders). Soul transfer is mainly used to transfer souls from one receptacle to another, but it can also be used to capture vulnerable souls that aren’t bound to mortal flesh (such as incorporeal creatures and petitioners). When used to capture a petitioner, the petitioner’s physical body vanishes, reappearing only when its soul is released from the receptacle.', 'a gem worth 1,000 gp per HD of the targeted creature or soul', NULL, false, true),
  ('soul_vault', 'Soul Vault', 'abjuration', NULL, NULL, 2, 'both', 'cleric 3, druid 4, inquisitor 3, psychic 5, shaman 3, sorcerer/wizard 4, spiritualist 2, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes', 'Note This item is associated with a particular deity that can not be named here.', NULL, NULL, true, false),
  ('soulseeker', 'Soulseeker', 'divination', NULL, NULL, 4, 'both', 'cleric 8, medium 4, occultist 6, shaman 8, spiritualist 6, witch 8', '1 hour', 'unlimited', 'one soul', NULL, NULL, 'instantaneous or 1 hour/level', 'Will negates (see text)', 'no', 'You identify the stage of a given soul’s judgment, or determine its fate post-judgment. You must either unambiguously identify the soul you seek or use the skull of the body the soul vacated as a focus. If the subject does not share your alignment, the soul can attempt a Will save to resist this spell’s effects as if it were still alive. If the subject is still alive or its soul has been destroyed, this spell fails without providing any information.', 'incense worth 250 gp', 'see text', false, true),
  ('soulswitch', 'Soulswitch', 'necromancy', NULL, NULL, 5, 'both', 'bard 5, cleric 5, druid 5, inquisitor 5, magus 5, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', NULL, NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'You may only cast this spell if you currently have a familiar. You place your soul into the body of your familiar, and your familiar’s soul is placed in your body. This functions as if you possessed your familiar using magic jar; your familiar simultaneously possesses your body in the same manner. You can’t freely transfer your soul between your body and your familiar’s—if you choose to return to your body as a standard action, the spell ends. If either body is killed, both spirits return to their original bodies, the spell ends, and the original owner of the slain body dies.', NULL, 'two brass collars worth 50 gp each', false, true),
  ('sound_burst', 'Sound Burst', 'evocation', NULL, 'sonic', 2, 'both', 'bard 2, cleric/oracle 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '10-ft.-radius spread', NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You blast an area with a tremendous cacophony. Every creature in the area takes 1d8 points of sonic damage and must succeed on a Fortitude save to avoid being stunned for 1 round. Creatures that cannot hear are not stunned but are still damaged.', NULL, NULL, true, false),
  ('source_severance', 'Source Severance', 'abjuration', NULL, NULL, 6, 'both', 'cleric 6, druid 6, witch 6', '1 standard action', '5 feet', NULL, '5-ft.-radius emanation, centered on you', NULL, '10 minutes/level (D)', 'none', 'see text', 'You create an invisible barrier that surrounds you and moves with you, inhibiting one category of magic. When you cast this spell, choose either arcane or divine magic. This spell functions like antimagic field, but it suppresses only spells of the chosen type and supernatural and spell-like class abilities from classes that grant spellcasting of the selected type. Magic items, other spell-like abilities, and other supernatural abilities are unaffected.', 'an unworked lodestone', NULL, false, false),
  ('sow_thought', 'Sow Thought', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, witch 1; Subdomain innuendo 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You plant an idea, concept, or suspicion in the mind of the subject. The target genuinely believes that the idea is his own, but is not required to act upon it. If the idea is contrary to the target’s normal thoughts (such as making a paladin think, “I should murder my friends”) the target may suspect mind-altering magic is at play. The idea must be fairly clear, enough so that it can be conveyed in one or two sentences. You do not need to share a common language for the spell to succeed, but without a common language you can only sow the most basic rudimentary ideas.', NULL, NULL, false, false),
  ('spark', 'Spark', 'evocation', NULL, 'fire', 0, 'both', 'bard 0, cleric/oracle 0, druid 0, magus 0, sorcerer/wizard 0, witch 0; Elemental School fire 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Fortitude negates (object)', 'yes (object)', 'You can make an unattended Fine flammable object catch on fire. This works as if you were using flint and steel except that you can use spark in any sort of weather and it takes much less time to actually ignite an object.', NULL, NULL, false, false),
  ('spawn_ward', 'Spawn Ward', 'necromancy', NULL, NULL, 5, 'divine', 'cleric 5, inquisitor 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Fort negates (harmless)', 'yes (harmless)', 'The target becomes resistant to the effects of energy drain and blood drain attacks made by undead creatures, and cannot be made into undead spawn if killed while the spell is in effect.', NULL, NULL, false, false),
  ('speak_local_language', 'Speak Local Language', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, ranger 1, sorcerer/wizard 1, witch 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as tongues, except the creature touched gains only the ability to speak and understand a regional human language and the language granted must be one you know. You must select the language at the time of casting.', NULL, NULL, false, false),
  ('speak_with_animals', 'Speak with Animals', 'divination', NULL, NULL, 1, 'both', 'bard 3, druid 1, psychic 2, ranger 1; Mystery juju(PAP39/PZO9039) 1, juju(PZO9436) 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level', NULL, NULL, 'You can ask questions of and receive answers from animals, but the spell doesn’t make them any more friendly than normal. Wary and cunning animals are likely to be terse and evasive, while the more stupid ones make inane comments. If an animal is friendly toward you, it may do some favor or service for you.', NULL, NULL, false, false),
  ('speak_with_dead', 'Speak with Dead', 'necromancy', NULL, 'language-dependent', 2, 'both', 'cleric/oracle 3, inquisitor 3, medium 2, psychic 3, shaman 3, spiritualist 3, witch 3; Domain knowledge 3, repose 3', '10 minutes', '10 ft.', 'one dead creature', NULL, NULL, '1 min./level', 'Will negates; see text', 'no', 'You grant the semblance of life to a corpse, allowing it to answer questions. You may ask one question per two caster levels. The corpse’s knowledge is limited to what it knew during life, including the languages it spoke. Answers are brief, cryptic, or repetitive, especially if the creature would have opposed you in life.', NULL, NULL, true, false),
  ('speak_with_haunt', 'Speak With Haunt', 'necromancy', NULL, 'language-dependent', 3, 'both', 'cleric 4, shaman 3, witch 4', '10 minutes', '10 ft. (see text)', 'one haunt', NULL, NULL, '1 minute/level', 'Will negates (see text)', 'no', 'You stir a haunt to a limited sense of awareness and consciousness, allowing it to answer questions. The spell’s range must reach any square within 10 feet of the haunt’s area. You must be aware of the haunt prior to casting the spell, and casting the spell does not trigger the haunt. You can ask one question per 2 caster levels. The haunt’s knowledge is limited to what its original creature knew during life, including the languages it spoke. A haunt often remembers the circumstance that led to its existence (though this recollection might be from the original victim’s perspective and therefore not objective), what triggers it, and how it can be laid to rest (destroyed). Answers are brief, cryptic, or repetitive, especially if the haunt is angry and vindictive.', NULL, NULL, true, false),
  ('speak_with_plane', 'Speak with Plane', 'divination', NULL, NULL, 3, 'both', 'cleric 4, medium 3, shaman 4, sorcerer/wizard 4, summoner 3, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one plane with a sentient structure', NULL, NULL, '1 minute/level', 'Will negates (see text)', 'yes', 'You tap into the awareness and consciousness of a plane with a sentient structure, allowing it to answer questions. A tangible manifestation of the plane (such as the ground) must be within the spell’s range upon casting.', NULL, NULL, true, false),
  ('speak_with_plants', 'Speak with Plants', 'divination', NULL, NULL, 3, 'both', 'bard 4, druid 3, ranger 2; Mystery nature 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level', NULL, NULL, 'You can communicate with normal plants and plant creatures, and can ask questions of and receive answers from them. A normal plant’s sense of its surroundings is limited, so it won’t be able to give (or recognize) detailed descriptions of creatures or answer questions about events outside its immediate vicinity. The spell doesn’t make plant creatures any more friendly or cooperative than normal. Furthermore, wary and cunning plant creatures are likely to be terse and evasive, while the more stupid ones may make inane comments. If a plant creature is friendly, it may do some favor or service for you.', NULL, NULL, false, false),
  ('speak_with_soul', 'Speak with Soul', 'necromancy', NULL, NULL, 4, 'divine', 'antipaladin 4, cleric 6, medium 4, paladin 4, shaman 6, spiritualist 6', '1 minute', '10 ft.', 'see text', NULL, NULL, '1 minute/level (D)', 'Will negates; see text', 'no', 'You commune with the soul of a dead creature.', 'a drop of candle wax', NULL, false, false),
  ('speak_with_waves', 'Speak With Waves', 'divination', NULL, 'water', 6, 'divine', 'druid 6, shaman 7', '10 minutes', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell functions as stone tell but allows conversations only with a body of standing or flowing fresh water at least as large as you are. Flowing water can generally speak about events happening upstream but not events happening downstream.', NULL, NULL, true, false),
  ('spear_of_purity', 'Spear of Purity', 'evocation', NULL, 'good', 2, 'divine', 'cleric/oracle 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'spear-shaped projectile of good energy', 'instantaneous (1 round)', 'Will partial (see text)', 'yes', 'You hurl a pure white or golden spear of light from your holy symbol, affecting any one target within range as a ranged touch attack.', NULL, NULL, true, false),
  ('spectral_hand', 'Spectral Hand', 'necromancy', NULL, NULL, 2, 'arcane', 'medium 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2; Mystery occult 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one spectral hand', '1 min./level (D)', 'none', 'no', 'A ghostly hand shaped from your life force materializes and moves as you desire, allowing you to deliver low-level, touch range spells at a distance. On casting the spell, you lose 1d4 hit points that return when the spell ends (even if it is dispelled), but not if the hand is destroyed. (The hit points can be healed as normal.) For as long as the spell lasts, any touch range spell of 4th level or lower that you cast can be delivered by the spectral hand. The spell gives you a +2 bonus on your melee touch attack roll, and attacking with the hand counts normally as an attack. The hand always strikes from your direction. The hand cannot flank targets like a creature can. After it delivers a spell, or if it goes beyond the spell range or goes out of your sight, the hand returns to you and hovers.', NULL, NULL, false, false),
  ('spectral_saluqi', 'Spectral Saluqi', 'necromancy', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6, witch 6', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one spectral dog', '10 minutes/level (D)', 'none', 'no', 'This spell creates a spectral saluqi, an undead canine resembling an over-sized hound with black fur, a gray ruff and tail, and milky gray eyes. The hound shares your alignment and can converse with you telepathically. It can see and attack ethereal creatures, and otherwise has the same statistics as a yeth hound. It usually leaves no tracks because it prefers to fly an inch above the ground. You are immune to the hound’s bay ability. The hound’s bite is considered aligned to any single alignment you possess for the purposes of overcoming damage reduction.', NULL, 'a precious metal canine statue worth 100 gp', false, true),
  ('spectral_scout', 'Spectral Scout', 'conjuration', 'creation', NULL, 3, 'both', 'bard 3, druid 3, ranger 3, shaman 3, sorcerer/wizard 3', '1 minute', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You summon a spectral creature in the shape of the Tiny or smaller animal of your choice, which always appears in your square. The creature emits a faint glow of a color you choose at the time of the spell’s casting, providing the illumination of a candle. It has the same statistics as the creature after which it is modeled (including ability scores, Armor Class, feats, senses, skills, and speed), but is incorporeal and has only 1 hit point. A spectral scout cannot attack, but can otherwise follow any basic instructions that could be given to a pet or animal companion of similar intelligence but without the need to make Handle Animal skill checks.', NULL, NULL, false, false),
  ('speechreader_s_sight', 'Speechreader’s Sight', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, cleric 1, inquisitor 1, medium 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'If a creature within 100 feet that you can see is speaking a language you understand, you can read its lips with perfect accuracy. Reading lips in this manner gives the exact wording of conversation and does not assist in deciphering any obfuscated ideas such as secret messages or slang. Reading lips requires moderate concentration, and you take a –4 penalty on other Perception checks while doing so.', NULL, NULL, false, false),
  ('spell_absorption', 'Spell Absorption', 'abjuration', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5', '1 round', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'If you successfully counterspell a 3rd-level or lower level spell (through either dispel magic or normal means) while spell absorption is in effect, you absorb the countered spell and use it to regain spells you have already cast. If you’re a wizard, you regain the use of any single spell that you have cast since the last time you prepared spells. If you’re a sorcerer, you regain a single spell slot. The spell recovered or spell slot regained must be of an equal level or lower than the spell you counterspelled.', 'a prism', NULL, false, false),
  ('spell_gauge', 'Spell Gauge', 'divination', NULL, 'mind-affecting', 2, 'both', 'bard 2, cleric/oracle 2, inquisitor 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You immediately discover some of the spells that the target knows or has prepared. The number of spells revealed to you is equal to your caster level. The target’s lowest-level spells are revealed first—ignoring 0-level spells—in a random order. Once all of the target’s 1st-level spells are revealed, the spell begins revealing 2nd-level spells, then 3rd-level spells. This spell does not reveal spells of 4th level or higher, nor does it reveal spell-like abilities or other special abilities. If cast on a creature that is not a spellcaster, that has only 0-level spells or spells of 4th level or higher prepared, that has expended all of its spells, or that has not prepared any spells that day, the spell has no effect.', NULL, 'a silver piece', false, false),
  ('spell_immunity', 'Spell Immunity', 'abjuration', NULL, NULL, 4, 'both', 'alchemist 4, cleric/oracle 4, inquisitor 4; Domain protection 4, strength 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level', 'Will negates (harmless)', 'yes (harmless)', 'The warded creature is immune to the effects of one specified spell for every four levels you have. The spells must be of 4th level or lower. The warded creature effectively has unbeatable spell resistance regarding the specified spell or spells. Naturally, that immunity doesn’t protect a creature from spells for which spell resistance doesn’t apply. Spell immunity protects against spells, spell-like effects of magic items, and innate spell-like abilities of creatures. It does not protect against supernatural or extraordinary abilities, such as breath weapons or gaze attacks.', NULL, NULL, true, false),
  ('spell_resistance', 'Spell Resistance', 'abjuration', NULL, NULL, 5, 'both', 'alchemist 5, cleric/oracle 5, inquisitor 5; Domain magic 5, protection 5; Bloodline draconic 5; Mystery dragon 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'The target gains spell resistance equal to 12 + your caster level.', NULL, NULL, true, false),
  ('spell_scourge', 'Spell Scourge', 'abjuration', NULL, NULL, 7, 'both', 'cleric/oracle 7, sorcerer/wizard 7, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous or 1d4 rounds; see text', 'Will negates', 'yes', 'A whip of cracking magical might appears in your hand, allowing you lash spells from the mind of enemy spellcasters. With a lash of bluish-purple energy, you strip many protective spells and effects from a single creature. If the target of this spell is currently under the effects of any harmless spells or effects, it must succeed at a Will save or all of those spells and effects end, stripping the target of the benefit of those spells. If the target is not currently under the effect of least one harmless spell, the target is instead confused for 1d4 rounds.', NULL, NULL, false, false),
  ('spell_turning', 'Spell Turning', 'abjuration', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 7, summoner 5, unchained summoner 6; Domain luck 7, magic 7; Bloodline destined 7; Mystery spellscar 7', '1 standard action', 'personal', 'you', NULL, NULL, 'until expended or 10 min./level', NULL, NULL, 'Spells and spell-like effects targeted on you are turned back upon the original caster. The abjuration turns only spells that have you as a target. Effect and area spells are not affected. Spell turning also fails to stop touch range spells. From seven to ten (1d4+6) spell levels are affected by the turning. The exact number is rolled secretly.', 'a small silver mirror worth 100 gp', NULL, true, true),
  ('spellbane', 'Spellbane', 'abjuration', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9', '1 standard action', '10 ft.', NULL, '10-ft.-radius emanation, centered on you', NULL, '1 hour/level (D)', 'none', 'see text', 'This spell creates an area within which spells selected by you simply do not function.', NULL, 'cold iron scepter worth at least 1,000 gp', false, true),
  ('spellblight_jinx', 'Spellblight Jinx', 'evocation', NULL, 'curse', 4, 'both', 'antipaladin 4, bard 4, cleric 6, inquisitor 5, occultist 5, psychic 6, shaman 5, sorcerer/wizard 6, witch 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You inflict a curse similar to the spell burn spellblight on a creature. Each time a spellcaster who is afflicted with this curse casts a spell or uses a spell-like ability, her skin seems to burn as though she were on fire. With a successful concentration check (DC = 15 + double the spell level of the spell cast or spell-like ability used), the spellcaster can ignore the pain of the effect, but if she fails, she loses the spell or spell slot and is staggered for a round.', NULL, NULL, false, false),
  ('spellcasting_contract', 'Spellcasting Contract', 'evocation', NULL, NULL, 9, 'arcane', 'cleric/oracle 7 (must worship the associated deity)', NULL, NULL, 'willing creature touched', NULL, NULL, 'permanent until contractually terminated', NULL, NULL, 'This spell functions like lesser spellcasting contract, except if the target has 9 HD or more, you can imbue him with one or two 2nd- level spells and one 3rd-level spell.', NULL, 'a written contract', false, false),
  ('spellcrash_lesser', 'Spellcrash, Lesser', 'abjuration', NULL, NULL, 4, 'both', 'cleric 4, sorcerer/wizard 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level', 'Will negates; see text', 'yes', 'You create a discordant blast of energy that disrupts the target’s available magic. If the target prepares spells, it must choose one of its prepared 3rd-level spells, which is immediately lost; if the target has no 3rd-level spells prepared, it must lose a 2nd-level spell it has prepared (progressing down to 1st-level spell if it has no 2nd-level spells prepared) each round at the start of its turn.', NULL, NULL, false, false),
  ('spellcurse', 'Spellcurse', 'necromancy', NULL, 'curse', 2, 'both', 'antipaladin 2, cleric 3, inquisitor 2, occultist 4, psychic 3, shaman 4, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'Will half', 'yes', 'You disrupt any spell energy affecting your target, causing that energy to crackle with power and harm the target. The target takes 1d6 points of damage for each spell with a duration of 1 round or greater currently affecting it. The spells themselves are not dispelled or modified.', 'a fragment of a destroyed magical item', NULL, false, false),
  ('spellscar', 'Spellscar', 'abjuration', NULL, NULL, 8, 'both', 'cleric 8, sorcerer/wizard 8; Mystery spellscar 8', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'two 10-ft. cubes per level (S)', NULL, '10 minutes/level (D)', NULL, NULL, 'This potent spell invokes devastation on a localized (and thankfully temporary) scale.', 'a pinch of sand', NULL, false, false),
  ('spellstaff', 'Spellstaff', 'transmutation', NULL, NULL, 6, 'divine', 'druid 6', '10 minutes', 'touch', 'wooden quarterstaff touched', NULL, NULL, 'permanent until discharged (D)', 'Will negates (object)', 'yes (object)', 'You store one spell that you can normally cast in a wooden quarterstaff. Only one such spell can be stored in a staff at a given time, and you cannot have more than one spellstaff at any given time. You can cast a spell stored within a staff just as though it were among those you had prepared, but it does not count against your normal allotment for a given day. You use up any applicable material components required to cast the spell when you store it in the spellstaff.', NULL, 'the staff that stores the spell', false, false),
  ('spellsteal', 'Spellsteal', 'abjuration', NULL, NULL, 5, 'both', 'cleric 5, sorcerer/wizard 5, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous and see text', 'Will negates', 'yes', 'You create a discordant blast of energy that disrupts the target’s available magic and transfers knowledge of that magic to you.', NULL, NULL, false, false),
  ('spellsword', 'Spellsword', 'transmutation', NULL, NULL, 3, 'arcane', 'bard 4, bloodrager 4, magus 3, occultist 4, sorcerer/wizard 3, witch 4', '1 round', 'touch', NULL, NULL, 'one melee weapon sized appropriately for you', '10 minutes/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'When you cast this spell on a weapon, you cause an extradimensional space to open within the weapon. As part of the casting, you can insert a single magic rod or magic staff into the weapon’s extradimensional space, after which the space closes.', NULL, 'a magic rod or staff', false, false),
  ('sphere_of_warding', 'Sphere of Warding', 'abjuration', NULL, NULL, 4, 'both', 'cleric 5, inquisitor 4, witch 5', '1 standard action', 'touch', NULL, NULL, '10-ft.-radius sphere emanating from point touched', '1 hour/level', 'Will negates (see text)', 'yes', 'You create a luminescent sphere of orbiting energy that harms incorporeal creatures and dispossesses them of any stolen bodies. An incorporeal creature must succeed at a Will save to enter a space overlapping with the sphere; failure means the creature cannot pass through the sphere, as though it were a wall of force. If the incorporeal creature succeeds, it may pass through the sphere at will, though if it ends its turn within the sphere, it takes a number of points of force damage equal to 1d6 + 1 per caster level (maximum +10).', NULL, NULL, true, false),
  ('spherescry', 'Spherescry', 'divination', 'scrying', NULL, 3, 'arcane', 'sorcerer/wizard 3', '1 hour', 'see text', NULL, NULL, NULL, '1 minute/level', 'none', 'no', 'This spell allows remote viewing through spheres that have previously consumed some portion of the spellcaster’s body: a single digit of a finger or toe at a minimum. The caster can view and listen to events within a 20-foot radius of the associated sphere; this radius follows the sphere if the sphere moves. Unlike a true scrying spell, no other spells operate through the associated sphere, but spherescry produces no indication of its activity on the target and cannot be discovered by normal methods of magical detection.', NULL, NULL, false, true),
  ('spider_climb', 'Spider Climb', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, bloodrager 2, druid 2, magus 2, medium 2, occultist 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level', 'Will negates (harmless)', 'yes (harmless)', 'The subject can climb and travel on vertical surfaces or even traverse ceilings as well as a spider does. The affected creature must have its hands free to climb in this manner. The subject gains a climb speed of 20 feet and a +8 racial bonus on Climb skill checks; furthermore, it need not make Climb checks to traverse a vertical or horizontal surface (even upside down). A spider climbing creature retains its Dexterity bonus to Armor Class (if any) while climbing, and opponents get no special bonus to their attacks against it. It cannot, however, use the run action while climbing.', 'a live spider', NULL, false, false),
  ('spike_growth', 'Spike Growth', 'transmutation', NULL, NULL, 2, 'divine', 'druid 3, ranger 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'one 20-ft. square/level', NULL, '1 hour/level (D)', 'Reflex partial', 'yes', 'Any ground-covering vegetation in the spell’s area becomes very hard and sharply pointed without changing its appearance.', NULL, NULL, true, false),
  ('spike_stones', 'Spike Stones', 'transmutation', NULL, 'earth', 4, 'divine', 'druid 4, shaman 4; Domain earth 4; Bloodline deep earth 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'one 20-ft. square/level', NULL, '1 hour/level (D)', 'Reflex partial', 'yes', 'Rocky ground, stone floors, and similar surfaces shape themselves into long, sharp points that blend into the background.', NULL, NULL, true, false),
  ('spiked_armor', 'Spiked Armor', 'transmutation', NULL, NULL, 1, 'both', 'bloodrager 1, cleric/oracle 1, inquisitor 1, magus 1, shaman 1', '1 standard action', 'touch', '1 suit of metal armor or 1 metal shield', NULL, NULL, '10 minutes/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'The targeted suit of armor or shield sprouts thousands of tiny iron spikes like porcupine quills. These do not harm the armor’s wearer (though donning or removing armor under the effects of this spell takes twice as long), but they act as armor spikes or shield spikes (as appropriate). Any creature attacking the wearer with natural weapons takes 1 point of piercing damage for each attack that hits.', '1 iron spike', NULL, false, false),
  ('spiked_pit', 'Spiked Pit', 'conjuration', 'creation', NULL, 3, 'arcane', 'sorcerer/wizard 3, summoner/unchained summoner 3; Subdomain caves 3; Elemental School earth 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-by-10-ft. hole, 10 ft. deep/2 levels', '1 round + 1 round/level', 'Reflex negates', 'no', 'This spell functions as create pit, except that the pit is lined with wickedly sharp spikes along its bottom and walls and has a maximum depth of 50 feet. Creatures who fall into the pit take falling damage as normal, plus 2d6 points of piercing damage from the spikes. Any creature or object coming into contact with the spikes along the walls, such as a creature trying to climb out, or rope or other typical aids to climbing, takes 1d6 points of piercing damage each round they are in contact with the walls. For those willing to accept the damage incurred while climbing, the pit’s walls have a Climb DC of 20.', NULL, 'miniature shovel costing 10 gp', false, true),
  ('spindrift_spritz', 'Spindrift Spritz', 'conjuration', 'healing', 'water', 1, 'divine', 'cleric 2, druid 2, inquisitor 2, paladin 1, ranger 1, shaman 2, spiritualist 2', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You can cast this spell only as a response to a target attempting a saving throw against an effect that would cause the fatigued, shaken, sickened, or staggered conditions. The target can roll its saving throw twice and take the higher result.', NULL, NULL, false, false),
  ('spiral_ascent', 'Spiral Ascent', 'conjuration', 'teleportation', NULL, 3, 'divine', 'cleric 3, inquisitor 3', '1 standard action', 'long (400 ft. + 40 ft./level)', 'you and touched objects', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You transform yourself into a helical beam of divine energy that instantly transports you upward to a spot within range.', NULL, NULL, false, false),
  ('spiral_descent', 'Spiral Descent', 'conjuration', 'teleportation', NULL, 2, 'divine', 'cleric 2, inquisitor 2', '1 standard action', 'long (400 ft. + 40 ft./level)', 'you and touched objects', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'This spell functions as spiral ascent, except the destination and direction of travel is downward from your current location.', NULL, NULL, false, false),
  ('spirit_bonds', 'Spirit Bonds', 'divination', NULL, 'meditative', 3, 'both', 'cleric 3, shaman 3, witch 3, wizard 3', '1 hour', 'personal', 'you; see text', NULL, NULL, '24 hours or until discharged', NULL, NULL, 'You heighten your awareness of up to one willing creature or object per 3 caster levels, each of which must be within 30 feet of you during the entire hour you spend preparing spells and casting spirit bonds. By concentrating on one of these creatures or objects as a full-round action, you can learn its direction and relative distance from your location, provided that it is on the same plane. In the case of a creature, you can also learn the state of its emotion or health aura as a full-round action. In the case of an object, you can also get a sense of how damaged it is, similar to reading the health aura of a creature, or, in the case of a magic item that must be activated, you can learn when it was last activated (a full-round action in either case).', 'soothing incense worth 300 gp', NULL, false, true),
  ('spirit_call', 'Spirit Call', 'enchantment', NULL, NULL, 1, 'divine', 'druid 1, shaman 1', '1 full round', '100 ft.', NULL, NULL, '100-ft.-radius spread centered on you', '1 minute/level', NULL, NULL, 'You call out to nature spirits associated with your spirit (not your wandering spirit) if you are a shaman, or your domain if you are a druid, beckoning them forth to pay attention to your current location. For the duration of the spell, all spells from your spirit magic list or domain list that are cast within the affected area have their caster level increased by 1, and all spellcasters casting such spells receive a +4 insight bonus on their concentration checks for those spells only.', NULL, NULL, true, false),
  ('spirit_share', 'Spirit Share', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, cleric 1, druid 1, occultist 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'For the duration of the spell, as a standard action you can touch a willing target to deliver 1 dose of a potable liquid (including alcoholic drinks and potions and elixirs, but not poisons or other liquids that are primarily harmful when drunk) in your possession (though not necessarily held in hand) into her.', NULL, 'liquid to be shared', false, false),
  ('spirit_bound_blade', 'Spirit-Bound Blade', 'evocation', NULL, NULL, 4, 'divine', 'medium 4, occultist 4, shaman 4, spiritualist 3; Bloodline ectoplasm 4', '1 standard action', 'touch', 'weapon touched', NULL, NULL, '1 minute/level', 'Will negates (harmless, object)', 'no', 'You focus emotional energy and weave it into a shroud of hardened ectoplasm around the weapon you touch, infusing it with a ghostly glow and great power. The weapon becomes a ghost touch weapon, and gains one of the following additional benefits, depending on the type of emotion you infuse into the weapon. If a special ability wouldn’t apply to the chosen weapon (such as vicious on a ranged weapon), the weapon doesn’t gain that benefit.', NULL, NULL, false, false),
  ('spiritual_ally', 'Spiritual Ally', 'evocation', NULL, 'force', 4, 'divine', 'cleric/oracle 4, medium 4, spiritualist 4, warpriest 4; Mystery ancestor 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'spiritual ally of force', '1 round/level (D)', 'none', 'yes', 'An ally made of pure force appears in a single 5-foot square within range. The ally takes the form of a servant of your god.', NULL, NULL, true, false),
  ('spiritual_squire', 'Spiritual Squire', 'evocation', NULL, 'force', 2, 'divine', 'antipaladin 2, cleric 2, inquisitor 2, paladin 2, shaman 2, spiritualist 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 minute/level (D)', 'none', 'no', 'This spell causes an ally made of pure force to appear in a single 5-foot square within range. The ally takes the form of a servant of your god (if any) or an ancestor. The spiritual squire occupies its space, though you and your allies can move through it, since it is your ally. While the spiritual squire appears to wear armor and carry a weapon, it cannot make attacks and does not threaten any spaces. On your turn, the spiritual squire can do one of the following: retrieve one stowed item from your possessions, carry an object weighing no more than 10 pounds per caster level, hand you an object it is carrying, perform the aid another action on your behalf or for one of your allies, or help one creature of your choice don armor (which then takes half the normal time). When the spiritual squire attempts the aid another action in combat, its attack bonus is equal to your base attack bonus + your Wisdom modifier.', NULL, NULL, true, false),
  ('spiritual_weapon', 'Spiritual Weapon', 'evocation', NULL, 'force', 2, 'divine', 'cleric/oracle 2, inquisitor 2, shaman 2; Domain war 2; Mystery ancestor 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'magic weapon of force', '1 round/level (D)', 'none', 'yes', 'A weapon made of force appears and attacks foes at a distance, as you direct it, dealing 1d8 force damage per hit, + 1 point per three caster levels (maximum +5 at 15th level). The weapon takes the shape of a weapon favored by your deity or a weapon with some spiritual significance or symbolism to you (see below) and has the same threat range and critical multipliers as a real weapon of its form. It strikes the opponent you designate, starting with one attack in the round the spell is cast and continuing each round thereafter on your turn. It uses your base attack bonus (possibly allowing it multiple attacks per round in subsequent rounds) plus your Wisdom modifier as its attack bonus. It strikes as a spell, not as a weapon, so for example, it can damage creatures that have damage reduction. As a force effect, it can strike incorporeal creatures without the reduction in damage associated with incorporeality. The weapon always strikes from your direction. It does not get a flanking bonus or help a combatant get one. Your feats or combat actions do not affect the weapon. If the weapon goes beyond the spell range, if it goes out of your sight, or if you are not directing it, the weapon returns to you and hovers.', NULL, NULL, true, false),
  ('spit_venom', 'Spit Venom', 'transmutation', NULL, 'poison', 3, 'both', 'cleric/oracle 4, druid 3, shaman 4, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one stream of venom', 'instantaneous; see text', 'Fortitude partial', 'no', 'You spit a stream of venom at a target using a ranged touch attack. If the venom hits, it causes blindness for 1 round. The target must also save or be poisoned by black adder venom; the DC in successive rounds of the poison is equal to the spell’s DC.', NULL, NULL, false, false),
  ('spite', 'Spite', 'abjuration', NULL, NULL, 4, 'arcane', 'witch 4', '1 round', 'personal', NULL, NULL, NULL, '1 hour/level (D) or until discharged', NULL, NULL, 'Choose a single touch range spell of 4th level or lower with a casting time of 1 standard action or less. As part of the action of casting spite, you cast the associated spell and bind it into a defensive ward in the form of a tattoo, birthmark, or wart somewhere upon your body. The next time you are hit by a melee attack or a combat maneuver is used successfully against you, the stored spell is triggered against your foe. You do not need to succeed on a touch attack to affect the target, but in all other respects the spell is treated as though you had cast it normally. If the attacking creature is not a valid target for the spell, the stored spell is lost with no effect.', 'rare inks worth 250 gp', NULL, false, true),
  ('splinter_spell_resistance', 'Splinter Spell Resistance', 'transmutation', NULL, NULL, 2, 'both', 'bloodrager 2, magus 2, occultist 2, psychic 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Fort negates', 'no', 'You create an aura around the target weapon that weakens a foe’s magical defenses. The first time each round the weapon damages a creature with spell resistance, that creature’s spell resistance is reduced by 5 for 1 round. This reduction is not cumulative for multiple attacks within the same round, even if the target is struck by different weapons, each affected by a different casting of splinter spell resistance. However, the same creature’s spell resistance can be reduced on multiple rounds by subsequent hits.', NULL, NULL, false, false),
  ('spontaneous_immolation', 'Spontaneous Immolation', 'evocation', NULL, 'fire', 2, 'arcane', 'psychic 2, sorcerer/wizard 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'instantaneous', 'Fortitude half and Reflex (see description)', 'yes', 'You point your finger at a creature, causing it to spontaneously burst into flame. The target takes 3d6 points of fire damage and catches on fire. A successful Fortitude save reduces this damage by half and prevents the target from catching on fire. Each round on your turn, a burning target can attempt a new save to extinguish the flames (DC equal to the DC of the spell); otherwise it takes another 1d6 fire damage.', 'pinch of saltpeter', NULL, false, false),
  ('spore_burst', 'Spore Burst', 'conjuration', NULL, 'poison', 2, 'both', 'druid 2, ranger 3, shaman 2, witch 2', '1 standard action', 'touch', 'one plant creature; see text', NULL, NULL, 'see text', 'special; see text', 'no', 'You cause a willing plant creature’s body to sprout small, puffy mushrooms that remain for 1 round per caster level or until the creature uses them. As a standard action, the target can cause these mushrooms to burst open, releasing a cloud of toxic spores that affect all creatures in a 20-foot-radius spread. Those in the area must succeed at Fortitude saves or be sickened for 1d6 rounds as they are overcome by sneezing and coughing.', 'a tiny puffball mushroom', NULL, false, false),
  ('spotlight', 'Spotlight', 'evocation', NULL, 'darkness, light', 3, 'both', 'bard 3, cleric 3, druid 3, inquisitor 3, magus 3, occultist 3, paladin 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '1 minute/level (D)', 'Reflex partial', 'yes', 'You create a mobile area of bright light centered on one target while simultaneously suppressing other light sources surrounding it. The light level in the target’s space increases to bright light, causing the target to take any penalties that it would normally take in bright light. In addition, all mundane light sources (and magic light sources of 3rd spell level or lower) within 20 feet of the target’s space are suppressed, shedding no light as long as they remain within this spell’s affected area and reverting the area normally affected by those light sources to their unmodified illumination levels.', NULL, NULL, false, false),
  ('squeeze', 'Squeeze', 'transmutation', 'polymorph', NULL, 2, 'arcane', 'alchemist 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'The target becomes flexible regardless of its actual size and mass. It can move through areas at least half its size with no penalty for squeezing. It can move through a space at least one-quarter its width using the penalties for squeezing through a space at least half its width.', NULL, NULL, false, false),
  ('stabilize', 'Stabilize', 'conjuration', 'healing', NULL, 0, 'both', 'cleric/oracle 0, druid 0, inquisitor 0, psychic 0, witch 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'Upon casting this spell, you target a living creature that has –1 or fewer hit points. That creature is automatically stabilized and does not lose any further hit points. If the creature later takes damage, it continues dying normally.', NULL, NULL, false, false),
  ('stabilize_powder', 'Stabilize Powder', 'transmutation', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 loaded firearm', NULL, NULL, 'instantaneous', 'Will negates (harmless, object)', 'yes (harmless, object)', 'Ammunition currently loaded in the target firearm is less prone to misfire. Decrease the misfire range by 1 + 1 per five caster levels (maximum +5, minimum misfire 0) for the ammunition currently loaded into that firearm.', 'a few drops of liquor', NULL, false, false),
  ('stabilize_pressure', 'Stabilize Pressure', 'abjuration', NULL, NULL, 2, 'both', 'alchemist 2, bloodrager 2, cleric 2, druid 2, hunter 2, investigator 2, oracle 2, psychic 2, ranger 2, shaman 2, summoner 2, unchained summoner 2, warpriest 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Fort negates (harmless)', 'yes (harmless)', 'You instantly stabilize the target’s pressure, causing it to adjust to its current pressure all at once. This doesn’t help it readjust to future pressure changes.', 'a piece of shell', NULL, false, false),
  ('stage_fright', 'Stage Fright', 'enchantment', 'compulsion', 'emotion, fear, mind-affecting', 3, 'both', 'antipaladin 3, bard 3, inquisitor 3, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', '1 creature/level, no two of which may be more than 30 ft. apart', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You fill your targets with the sudden fear of failure. A creature that fails its saving throw takes a –4 penalty on ability checks, skill checks, and any checks that require concentration (such as casting a spell in difficult circumstances or operating a complex device).', NULL, NULL, false, false),
  ('staggering_fall', 'Staggering Fall', 'transmutation', NULL, NULL, 2, 'both', 'cleric/oracle 2, sorcerer/wizard 2, witch 2', '1 immediate action', 'medium (100 ft. + 10 ft./level)', 'one falling creature', NULL, NULL, '1 round/level (see below)', 'Will partial (see below)', 'yes', 'This spell must be cast on a creature as it falls, either from a height or after being knocked prone or tripped. The magic of this spell causes the creature to hit the ground particularly hard, knocking the wind from it. The creature takes an additional 1d6 points of damage from the fall. In addition, the creature becomes staggered for the duration of the spell unless it makes a Will save. Each round the spell’s effects persist, the creature may attempt a new Will save as a free action to end the staggered effect early. A creature under the effects of this spell must take a standard action to stand up.', NULL, NULL, false, false),
  ('stalwart_resolve', 'Stalwart Resolve', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'alchemist 2, cleric 2, inquisitor 1, paladin 1, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'Stalwart resolve was originally created to temporarily aid those suffering from certain afflictions. The recipient of stalwart resolve ignores the effects of ability damage and penalties to a single ability score of your choice, except that damage equal to or greater than the ability score still causes unconsciousness or death. This applies whether or not the ability damage or penalty happened before or during the spell’s duration, and whether or not multiple sources are involved. This spell has no effect on ability drain.', NULL, NULL, true, false),
  ('starsight', 'Starsight', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, cleric 1, druid 1, ranger 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'You can observe the night sky and all of its celestial bodies as if it were a clear night, regardless of weather conditions that would otherwise block your view. Your vision penetrates any light pollution from non-magical sources, though this spell doesn’t function in daylight, indoors, or underground. You see through forest canopies and similar natural obstructions, but only for the purpose of stargazing. For the spell’s duration, you gain a +2 insight bonus on Knowledge (geography) checks relating to the stars and planets and Survival checks to avoid getting lost.', NULL, NULL, false, false),
  ('statue', 'Statue', 'transmutation', NULL, NULL, 6, 'arcane', 'alchemist 6, sorcerer/wizard 7; Domain artifice 8; Elemental School earth 7, metal 7; Mystery metal 7, stone 7', '1 round', 'touch', 'creature touched', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'A statue spell turns the subject to solid stone, along with any garments and equipment worn or carried. In statue form, the subject gains hardness 8. The subject retains its own hit points. The subject can see, hear, and smell normally, but it does not need to eat or breathe. Feeling is limited to those sensations that can affect the granite-hard substance of the individual’s body. Chipping is equal to a mere scratch, but breaking off one of the statue’s arms constitutes serious damage. The subject of a statue spell can return to its normal state, act, and then return instantly to the statue state (a free action) if it so desires as long as the spell duration is in effect.', 'lime, sand, and a drop of water stirred by an iron spike', NULL, false, false),
  ('status', 'Status', 'divination', NULL, NULL, 2, 'both', 'cleric/oracle 2, medium 2, occultist 2, psychic 2, spiritualist 2, witch 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'When you need to keep track of comrades who may get separated, status allows you to mentally monitor their relative positions and general condition. You are aware of direction and distance to the creatures and any conditions affecting them: unharmed, wounded, disabled, staggered, unconscious, dying, nauseated, panicked, stunned, poisoned, diseased, confused, or the like. Once the spell has been cast upon the subjects, the distance between them and the caster does not affect the spell as long as they are on the same plane of existence. If a subject leaves the plane, or if it dies, the spell ceases to function for it.', NULL, NULL, false, false),
  ('stave_off_corruption', 'Stave Off Corruption', 'abjuration', NULL, NULL, 2, 'divine', 'cleric 2, paladin 2', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 day/2 caster levels', 'Will negates (harmless)', 'yes (harmless)', 'You ward the target to slow the advancement of its corruption.', 'see text', NULL, false, false),
  ('stay_the_hand', 'Stay the Hand', 'enchantment', 'compulsion', 'mind-affecting', 4, 'divine', 'paladin 4', '1 immediate action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1/round per level and special; see text', 'Will partial', 'yes', 'You cause a creature’s arm to waver and prevent it from striking another creature. You can cast this spell when the target is about to make a melee attack against another creature. On a failed Saving Throw, the target does not follow through with its attack, and its entire action is wasted for the round. On a successful Saving Throw, the target can make its attack, forcing its strike though the compulsion but losing both accuracy and power, taking a -5 penalty on its attack and damage rolls. Whether or not the target makes its initial save or not, it is subject to a -2 penalty on attack and damage rolls against the creature it originally targeted for the duration of the spell.', NULL, NULL, true, false),
  ('steal_breath', 'Steal Breath', 'transmutation', NULL, 'air', 2, 'both', 'bard 2, bloodrager 2, druid 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round (see text)', 'Fort negates; see text', 'yes', 'You pull the breath from a creature’s lungs, dealing damage and leaving it unable to speak, use breath weapons, or cast spells with verbal components. If the target fails its saving throw, it takes 2d6 points of damage, and it cannot speak, use breath weapons, or anything else requiring breathing, and a visible line of swirling air leaves the target’s mouth and enters your mouth.', NULL, NULL, false, false),
  ('steal_size', 'Steal Size', 'transmutation', NULL, NULL, 2, 'both', 'bloodrager 2, druid 3, magus 3, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level (D)', 'Fort negates', 'yes', 'This spell reduces the target’s size by one size category, as if it were affected by reduce person. You grow in size by one category, as if affected by enlarge person (if you can be targeted by that spell). If the spell is dispelled or otherwise ends for either you or the target, both you and the target return to your normal sizes.', 'a piece of iron shaped like a scale tray', NULL, false, false),
  ('steal_voice', 'Steal Voice', 'necromancy', NULL, NULL, 2, 'arcane', 'bard 2, medium 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, 'permanent (D)', 'Fortitude negates', 'yes', 'The target’s throat constricts, giving it the caster croak spellblight.', NULL, NULL, false, false),
  ('steal_years', 'Steal Years', 'transmutation', NULL, NULL, 3, 'both', 'cleric/oracle 3, druid 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '24 hours', 'Fortitude negates', 'yes', 'You temporarily drain youth and vitality from the target and channel it into yourself. If the target fails its Fortitude save, it physically ages 1d4 years per two caster levels (maximum 5d4), and you decrease your age by the same number of years. If this changes the age category of you or the target, only adjust physical ability scores. This effect cannot bring your age to lower than the minimum age of adulthood for your race. This stolen youth does not actually change your age or prolong your life; you will still die at your allotted time, no matter how youthful you appear. Likewise, the spell does not add to the target’s true age, and cannot make the target die of old age.', 'a handful of ash', NULL, false, false),
  ('steam_ray_fusillade', 'Steam Ray Fusillade', 'evocation', NULL, 'fire, water', 7, 'arcane', 'arcanist 7, sorcerer 7, wizard 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'For the duration of the spell, you can fire three rays of steam once per round as a standard action (and you also fire three such rays as part of casting the spell). These rays function similarly to the rays from scorching ray (you can fire them at close range, they’re ranged touch attacks, they deal 4d6 points of fire damage each, and spell resistance negates them) except that they work both underwater and above water without a caster level check for being a fire spell.', 'a scraping from a hydrothermal vent', NULL, false, false),
  ('stench_of_prey', 'Stench of Prey', 'transmutation', NULL, NULL, 3, 'divine', 'druid 3, ranger 3, shaman 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature (see text)', NULL, NULL, '1 minute/level', 'Fort negates (see text)', 'yes', 'The target exudes a strong odor that most predators recognize as the scent of helpless prey. The closest 1d4+1 predatory creatures within 30 feet must succeed at a Will save or start attacking the target (animals with the scent ability are affected if within 60 feet). If the predator is an animal, it can be called away from the target by a handler using the “down” trick or any effect that suspends or dispels emotion or rage effects.', NULL, NULL, true, false),
  ('stinking_cloud', 'Stinking Cloud', 'conjuration', 'creation', 'poison', 3, 'both', 'bloodrager 3, magus 3, shaman 3, sorcerer/wizard 3, unchained summoner 3, witch 3; Subdomain smoke 3; Elemental School earth 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 round/level', 'Fortitude negates; see text', 'no', 'Stinking cloud creates a bank of fog like that created by fog cloud, except that the vapors are nauseating. Living creatures in the cloud become nauseated. This condition lasts as long as the creature is in the cloud and for 1d4+1 rounds after it leaves. (Roll separately for each nauseated character.) Any creature that succeeds on its save but remains in the cloud must continue to save each round on your turn. This is a poison effect.', 'a rotten egg or cabbage leaves', NULL, false, false),
  ('stoke_the_inner_fire', 'Stoke the Inner Fire', 'transmutation', NULL, 'fire', 2, 'divine', 'cleric 2, inquisitor 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You increase the natural heat within your body, transferring it to your weapons and armor. As a swift action, you may grant one of your natural or manufactured weapons the flaming special ability for 1 round. If you have the fire subtype, your weapon instead gains the flaming burst special ability. If the weapon leaves your hand for any reason, it loses the flaming (or flaming burst) special ability until you spend a swift action to activate it again. You can only have stoke the inner fire active on one weapon at a time, and spending a swift action to imbue a second weapon with the spell’s power immediately ends its effect on the first weapon.', NULL, NULL, false, false),
  ('stolen_light', 'Stolen Light', 'illusion', 'figment', NULL, 3, 'arcane', 'bard 3, sorcerer/wizard 3', '1 full round', 'touch', 'transparent gem touched', NULL, NULL, 'permanent or 1 minute/level (see text)', 'Will negates (object)', 'yes (object)', 'Stolen light stores images within a gem. To store an image, as part of casting you must touch a gem worth not less than 500 gp. You trap within the gem an image of everything visible within a 30-foot cone measured from the gem, in a direction of your choice. Alternatively, you can capture a less detailed image of a single object within sight. Once the casting is complete, the gem turns opaque, and the image inside cannot be seen. The stolen image remains within the gem until released or dispelled.', NULL, 'a gem worth at least 500 gp', false, true),
  ('stone_call', 'Stone Call', 'conjuration', 'creation', 'earth', 2, 'both', 'bloodrager 2, druid 2, magus 2, ranger 2, sorcerer/wizard 2; Elemental School earth 2; Mystery stone 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'cylinder (40-ft. radius, 20 ft. high)', NULL, '1 round/level', 'none', 'no', 'A rain of dirt, gravel, and small pebbles fills the area, dealing 2d6 points of bludgeoning damage to every creature in the area. This damage only occurs once, when the spell is cast.', NULL, NULL, true, false),
  ('stone_discus', 'Stone Discus', 'conjuration', 'creation', 'earth', 2, 'both', 'bloodrager 2, druid 2, magus 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one or more stone discuses', 'Instantaneous', 'none', 'no', 'You create a stone discus, which flies at an enemy. You can create one discus, plus one additional discus at 7th and 11th caster levels. For each discus you create, you decide whether its edge is blunt (and deals bludgeoning damage) or sharp (and deals slashing damage). Each discus requires a ranged attack to hit and deals 4d6 points of damage. The discuses can be launched at more than one target, but all must be aimed at targets within 30 feet of each other and launched simultaneously.', 'a pinch of earth or metal', NULL, false, false),
  ('stone_fist', 'Stone Fist', 'transmutation', NULL, 'earth', 1, 'both', 'alchemist 1, bloodrager 1, druid 1, magus 1, sorcerer/wizard 1; Elemental School earth 1; Mystery ascetic 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level (D)', NULL, NULL, 'This spell transforms your hands into living stone. While this spell is in effect, your unarmed strikes do not provoke attacks of opportunity and deal 1d6 points of lethal bludgeoning damage (1d4 if you are Small). In addition, your unarmed strikes ignore the hardness of any object with a hardness less than 8.', 'a chip of granite', NULL, false, false),
  ('stone_shape', 'Stone Shape', 'transmutation', NULL, 'earth', 3, 'both', 'cleric/oracle 3, druid 3, shaman 3, sorcerer/wizard 4; Domain artifice 3, earth 3; Elemental School earth 4', '1 standard action', 'touch', 'stone or stone object touched, up to 10 cu. ft. + 1 cu. ft./level', NULL, NULL, 'instantaneous', 'none', 'no', 'You can form an existing piece of stone into any shape that suits your purpose. While it’s possible to make crude coffers, doors, and so forth with stone shape, fine detail isn’t possible. There is a 30% chance that any shape including moving parts simply doesn’t work.', 'soft clay', NULL, true, false),
  ('stone_shield', 'Stone Shield', 'conjuration', 'creation', 'earth', 1, 'both', 'bloodrager 1, cleric 1, druid 1, magus 2, shaman 1, sorcerer/wizard 1, summoner 1', '1 immediate action', '0 ft.', NULL, NULL, 'stone wall whose area is one 5-ft. square', '1 round', 'none', 'no', 'A 1-inch-thick slab of stone springs up from the ground, interposing itself between you and an opponent of your choice. The stone shield provides you with cover from that enemy until the beginning of your next turn, granting you a +4 bonus to Armor Class and a +2 bonus on Reflex saving throws. If the opponent’s attack misses you by 4 or less, the attack strikes the shield instead. The stone shield has hardness 8 and 15 hit points. If the shield is destroyed, the spell ends and the shield crumbles away into nothingness. Spells and effects that damage an area deal damage to the shield.', NULL, NULL, true, false),
  ('stone_tell', 'Stone Tell', 'divination', NULL, NULL, 6, 'divine', 'druid 6, shaman 7; Bloodline deep earth 6; Mystery nature 6, stone 6', '10 minutes', 'personal', 'you', NULL, NULL, '1 min./level', NULL, NULL, 'You gain the ability to speak with stones, which relate to you who or what has touched them as well as revealing what is covered or concealed behind or under them. The stones relate complete descriptions if asked. A stone’s perspective, perception, and knowledge may prevent the stone from providing the details you are looking for. You can speak with natural or worked stone.', NULL, NULL, true, false),
  ('stone_throwing', 'Stone Throwing', 'transmutation', NULL, NULL, 1, 'both', 'bloodrager 1, cleric 2, druid 2, magus 2, ranger 1, sorcerer/wizard 2', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The subject gains the rock throwing and rock catching abilities. It can use these abilities with any solid, mostly inflexible object with a hardness of at least 5.', 'powdered stone', NULL, false, false),
  ('stone_to_flesh', 'Stone to Flesh', 'transmutation', NULL, NULL, 6, 'both', 'magus 6, shaman 6, sorcerer/wizard 6, witch 6; Elemental School earth 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one petrified creature or a cylinder of stone from 1 ft. to 3 ft. in diameter and up to 10 ft. long', NULL, NULL, 'instantaneous', 'Fortitude negates (object); see text', 'yes', 'This spell restores a petrified creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any petrified creature, regardless of size, can be restored. The spell also can convert a mass of stone into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. For example, this spell would turn an animated stone statue into an animated flesh statue, but an ordinary statue would become a mass of inert flesh in the shape of the statue. You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of stone.', 'a drop of blood mixed with earth', NULL, false, false),
  ('stoneskin', 'Stoneskin', 'abjuration', NULL, NULL, 3, 'both', 'alchemist 4, bloodrager 4, druid 5, inquisitor 4, magus 4, shaman 5, sorcerer/wizard 4, summoner 3, unchained summoner 4; Domain earth 6, strength 6; Bloodline abyssal 4, deep earth 4; Elemental School earth 4, metal 4; Mystery stone 5, succor 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains DR 10/adamantine. It ignores the first 10 points of damage each time it takes damage from a weapon, though an adamantine weapon bypasses the reduction. Once the spell has prevented a total of 10 points of damage per caster level (maximum 150 points), it is discharged.', 'granite and diamond dust worth 250 gp', NULL, false, true),
  ('storm_of_blades', 'Storm of Blades', 'conjuration', 'creation', NULL, 2, 'both', 'cleric 3, magus 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'none', 'no', 'You create floating swords of the type used as the material component for this spell (such as a rapier or scimitar) and magically propel them at your target. You can create one sword for every 2 caster levels that you possess, up to a maximum of five swords at 10th level. You must have line of effect between you and the target, and the target must be within the spell’s range. You make a ranged attack roll for each sword (with no penalties for range increments or using melee weapons as ranged weapons); each attack has the same threat range and critical modifier and deals the same damage as a standard sword of the type expended. Swords created by this spell disappear after striking (or missing) their targets.', 'a sword', NULL, false, false),
  ('storm_of_vengeance', 'Storm of Vengeance', 'conjuration', 'summoning', NULL, 9, 'divine', 'cleric/oracle 9, druid 9, shaman 9, witch 9; Domain nobility 9, weather 9; Subdomain cloud 9; Mystery battle 9', '1 round', 'long (400 ft. + 40 ft./level)', NULL, NULL, '360-ft.-radius storm cloud', 'concentration (maximum 10 rounds) (D)', 'see text', 'yes', 'You create a huge black storm cloud in the air. Each creature under the cloud must succeed on a Fortitude save or be deafened for 1d4 x 10 minutes. Each round you continue to concentrate, the spell generates additional effects as noted below. Each effect occurs on your turn.', NULL, NULL, false, false),
  ('storm_sight', 'Storm Sight', 'divination', 'scrying', NULL, 2, 'both', 'cleric 2, druid 2, shaman 2, sorcerer/wizard 2, witch 2', '1 round', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You step into any magical or naturally occurring storm and commune directly with the power of the wind and rain.', NULL, 'a storm, either natural or magical', false, false),
  ('storm_step', 'Storm Step', 'conjuration', 'teleportation', 'electricity', 3, 'arcane', 'magus 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'you Range close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'instantaneous', 'Reflex halves', 'yes', 'You are able to harness the power of the storm to transport yourself a short distance, by taking the form of a furious, sizzling bolt of elemental electricity.', NULL, NULL, false, false),
  ('stormbolts', 'Stormbolts', 'evocation', NULL, 'electricity', 8, 'both', 'cleric/oracle 8, druid 8, shaman 8, sorcerer/wizard 8, witch 8; Elemental School air 8, metal 8', '1 standard action', '30 ft.', NULL, 'a 30-ft.-radius spread, centered on you', NULL, 'instantaneous', 'Fortitude partial', 'yes', 'When you cast this spell, lightning spills forth from your body in all directions. The bolts do not harm natural vegetation or creatures in the area you wish to exclude from damage. Any other creatures within the area take 1d8 points of electricity damage per caster level (maximum 20d8) and are stunned for 1 round. A successful Saving Throw halves the damage and negates the stun effect.', 'a copper rod', NULL, true, false),
  ('straitjacket', 'Straitjacket', 'conjuration', 'creation', NULL, 4, 'both', 'inquisitor 4, occultist 4, sorcerer/wizard 5, summoner 5', '1 standard action', 'close (25 ft. + 5 ft./2 caster levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'none', 'yes', 'You cause a straitjacket to spring into existence to restrain the target creature. You attempt a combat maneuver against the target’s CMD. Your CMB for this check is equal to your caster level + 5 due to the straightjacket’s Strength. This combat maneuver doesn’t provoke an attack of opportunity, and if it succeeds, the target is restrained. This is similar to the grappled condition, except the target is able to move at its normal speed, the restraint doesn’t cause the target to require concentration checks to use abilities that require concentration, and the target can’t take actions that require one or more hands or arms to perform (including casting spells that require a somatic or material component).', 'leather strap', NULL, false, false),
  ('strand_of_the_tangled_knot', 'Strand of the Tangled Knot', 'abjuration', NULL, NULL, 1, 'both', 'cleric/oracle 1, inquisitor 1, shaman 1, warpriest 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'The next single attack made against you takes a –10 penalty. If that attack is a critical hit, it is instead treated as a normal hit.', 'a small knot of twin', NULL, true, false),
  ('strangling_hair', 'Strangling Hair', 'transmutation', NULL, NULL, 3, 'arcane', 'psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'concentration, up to 1 round/level', 'none', 'yes', 'Your hair animates and extends to grapple and constrict an opponent. Make a grapple check against the target using your caster level as the base attack bonus plus a bonus equal to your Intelligence bonus (if a witch or wizard) or Charisma bonus (if a sorcerer). This grapple check does not provoke attacks of opportunity. If your hair succeeds in grappling a foe, that creature takes 1d6 points of damage or your unarmed strike damage, whichever is greater, and gains the grappled condition. Your hair receives a +5 bonus on grapple checks made against opponents it is already grappling, but cannot move foes or pin foes. Each round that your hair succeeds on a grapple check, it deals an additional 1d6 points of damage. The CMD of your hair, for the purposes of escaping the grapple, is equal to 10 + its CMB.', NULL, NULL, false, false),
  ('stricken_heart', 'Stricken Heart', 'necromancy', NULL, 'death', 2, 'both', 'inquisitor 2, mesmerist 2, psychic 2, shaman 3, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'none', 'yes', 'This spell covers your hand with a writhing black aura. As part of casting the spell, you can make a melee touch attack that deals 2d6 points of negative energy damage and causes the target to be staggered for 1 round. If the attack is a critical hit, the target is staggered for 1 minute instead. Creatures immune to precision damage are immune to the staggered effect.', NULL, NULL, false, false),
  ('strip_scales', 'Strip Scales', 'transmutation', NULL, NULL, 4, 'both', 'druid 4, sorcerer/wizard 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 minute/level', 'Fortitude', 'yes', 'You reduce the target’s racial natural armor bonus by 1 point per 3 caster levels.', 'a single reptile scale', NULL, true, false),
  ('strong_jaw', 'Strong Jaw', 'transmutation', NULL, NULL, 3, 'divine', 'druid 4, ranger 3', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'Laying a hand upon an allied creature’s jaw, claws, tentacles, or other natural weapons, you enhance the power of that creature’s natural attacks. Each natural attack that creature makes deals damage as if the creature were two sizes larger than it actually is. If the creature is already Gargantuan or Colossal-sized, double the amount of damage dealt by each of its natural attacks instead. This spell does not actually change the creature’s size; all of its statistics except the amount of damage dealt by its natural attacks remain unchanged.', NULL, NULL, false, false),
  ('strong_wings', 'Strong Wings', 'transmutation', NULL, NULL, 1, 'both', 'bloodrager 1, druid 1, ranger 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'The target’s wings grow more powerful, causing its fly speed to increase by +10 feet and its maneuverability to improve by one category (to a maximum of good). This increase counts as an enhancement bonus. This spell has no effect on wingless creatures or winged creatures that cannot fly.', NULL, NULL, false, false),
  ('stumble_gap', 'Stumble Gap', 'conjuration', 'creation', NULL, 1, 'arcane', 'sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'see text', '1 round + 1 round/level', 'Reflex partial', 'no', 'You create a shallow extra-dimensional hole perfectly sized to trip anyone who steps within it. This hole occupies a single 5-foot square with a depth of six inches. Any creature occupying the square when you first create the hole, or who later steps into the square containing the hole, must make a Reflex saving throw to avoid falling prone in an adjacent square and taking 1d6 points of damage. A creature that makes its saving throw still stumbles ever so slightly and takes a -1 penalty on all rolls and checks for 1 round. The spell has no effect on creatures adjacent to the square containing the hole.', NULL, 'miniature shovel costing 10 gp', false, true),
  ('stunning_barrier', 'Stunning Barrier', 'abjuration', NULL, NULL, 1, 'both', 'cleric 1, inquisitor 1, paladin 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level or until discharged', 'none and Will negates (see text)', 'no and yes (see text)', 'You are closely surrounded by a barely visible magical field. The field provides a +1 deflection bonus to AC and a +1 resistance bonus on saves. Any creature that strikes you with a melee attack is stunned for 1 round (Will negates). Once the field has stunned an opponent, the spell is discharged.', NULL, NULL, false, false),
  ('stunning_finale', 'Stunning Finale', 'enchantment', 'compulsion', 'mind-affecting', 5, 'arcane', 'bard 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round', 'Fortitude partial; see text', 'yes', 'You must have a bardic performance in effect to cast this spell.', NULL, NULL, false, false),
  ('sturdy_tree_fort', 'Sturdy Tree Fort', 'transmutation', NULL, NULL, 4, 'divine', 'druid 5, ranger 4', '1 minute', 'touch Effects one large tree and a sturdy wooden house', NULL, NULL, NULL, '1 hour/level (D)', 'none', 'no', 'You cause a large tree to grow in the 5-foot square you touch. The tree has 1 foot of thickness for every 4 caster levels you have, and it can grow to any height you designate, up to 5 feet high per caster level you have. If there is a ceiling or other barrier overhead, the maximum height of the tree cannot exceed the space available. At any point along the tree’s height, you can create a sturdy wooden building that fills one 10-foot cube for every 4 caster levels you have. All portions of the structure must be adjacent to the trunk of the tree (or can have the tree trunk extend up through their spaces), but otherwise these cubes need not be contiguous. If you place the cubes so that they are contiguous, the buildings merge together, complete with ladders connecting different vertical levels. The fort is magically supported, but if the tree it is attached to is destroyed, the structure is destroyed as well (the tree has hardness 5 and 20 hp per caster level you have).', NULL, 'a nail, a rope, and a short wooden plank', false, false),
  ('subjective_reality', 'Subjective Reality', 'illusion', 'phantasm', 'mind-affecting', 5, 'arcane', 'bard 6, medium 5, mesmerist 5, psychic 6, sorcerer/wizard 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', 'none', 'none', 'Choose one object, creature, or force you can see within long range (400 ft. + 40 ft./level). You alter your perceptions to become convinced the target is an illusion.', NULL, NULL, false, false),
  ('submerge_ship', 'Submerge Ship', 'transmutation', NULL, NULL, 7, 'both', 'cleric 7, sorcerer/wizard 7', '1 minute', 'touch', '1 sailing vessel', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'no', 'When this spell is cast upon a vessel, the ship is surrounded by a protective bubble of constantly replenishing, breathable air and sinks beneath the waves. For the duration of the spell, the ship can travel beneath the water as easily as it did above. While under the effects of this spell, the ship has magical propulsion that gives it a maximum speed of 120 feet and an acceleration of 30 feet. The ship’s pilot uses the normal sailing skill to control the ship while under this spell’s effects, and can command it to dive and ascend as part of the vessel’s normal movement.', 'a glass marble or piece of soap', NULL, true, false),
  ('substitute_trail', 'Substitute Trail', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4, ranger 4', '1 standard action', NULL, '1 creature/level; see text', NULL, NULL, '1 day/level (D)', 'none', 'no', 'This spell can affect any creatures with which you interacted in the last 24 hours. You alter the trails left by the chosen creatures, making it appear that another creature with which you are familiar left the trail instead (you must have met the creature with which you are familiar). If a tracker exceeds the DC of the skill check to follow the trail by an amount equal to your caster level, the tracker recognizes that the trail has been manipulated by this spell, although it cannot see the trail’s true nature unless it uses magical means, such as true seeing.', NULL, NULL, false, false),
  ('suffocation', 'Suffocation', 'necromancy', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5, witch 5; Subdomain murder 5; Elemental School air 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '3 rounds', 'Fortitude partial', 'yes', 'This spell extracts the air from the target’s lungs, causing swift suffocation.', 'a vial containing a bit of the caster’s breath', NULL, false, false),
  ('suggestion', 'Suggestion', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 2, 'arcane', 'bard 2, medium 2, mesmerist 2, occultist 3, psychic 2, sorcerer/wizard 3, witch 3; Domain charm 3; Subdomain corruption 2, devil (evil, law) 3, innuendo 3; Mystery intrigue 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 hour/level or until completed', 'Will negates', 'yes', 'You influence the actions of the target creature by suggesting a course of activity (limited to a sentence or two). The suggestion must be worded in such a manner as to make the activity sound reasonable. Asking the creature to do some obviously harmful act automatically negates the effect of the spell.', 'a snake’s tongue and a honeycomb', NULL, false, false),
  ('summon_accuser', 'Summon Accuser', 'conjuration', 'summoning', 'evil, lawful', 4, 'both', 'bard 4, cleric/oracle 4, sorcerer/wizard 4, summoner 4, witch 4', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one accuser devil', '10 minutes/level', 'none', 'no', 'This spell summons a single accuser devil from Hell to do the spellcaster’s bidding, similar to how summon monster spells function. Accuser devils, known to diabolists as zebubs, are hideous flying creatures with the torso of a plump human infant and the body and wings of an enormous fly. They make excellent spies, for they have the ability to grant visions of what they have witnessed to others—the Queen’s Hands sometimes use summoned zebubs to observe suspects from afar.', NULL, NULL, true, false),
  ('summon_ancestral_guardian', 'Summon Ancestral Guardian', 'conjuration', 'summoning', NULL, 3, 'both', 'bard 3, cleric/oracle 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'two summoned ancestor spirits', '1 round/level (D)', 'none', 'yes', 'You call the spirits of two ancestors to manifest in the mortal world and attack your enemies. Each appears as a transparent image of a powerful, wise dwarf armed with a traditional dwarven weapon of your choice. These spirits move and attack at your direction, each having the abilities of a spiritual weapon, except they can attack different targets and deal physical damage (bludgeoning, piercing, or slashing, according to the weapon the spirit wields) instead of force damage. Like creatures conjured with a summon monster spell, your ancestors are not harmed if these manifestations are destroyed.', NULL, NULL, true, false),
  ('summon_cacodaemon', 'Summon Cacodaemon', 'conjuration', 'summoning', 'evil', 2, 'both', 'cleric 2, sorcerer/wizard 2, summoner 2, witch 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like summon monster, except it summons a single cacodaemon.', NULL, 'a silver hook', false, false),
  ('summon_ceustodaemon', 'Summon Ceustodaemon', 'conjuration', 'summoning', 'evil', 4, 'both', 'cleric 5, sorcerer/wizard 5, summoner 4, witch 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like summon monster, except it summons a single ceustodaemon.', NULL, 'ashes of a dead animal', false, false),
  ('summon_derghodaemon', 'Summon Derghodaemon', 'conjuration', 'summoning', 'evil', 9, 'both', 'cleric 9, sorcerer/wizard 9, witch 9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like summon monster, except it summons a single derghodaemon.', NULL, 'a handful of bug carapaces', false, false),
  ('summon_eidolon', 'Summon Eidolon', 'conjuration', 'summoning', NULL, 2, 'arcane', 'summoner/unchained summoner 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level (D)', 'none', 'no', 'You open a rift between dimensions that summons your eidolon.', 'a silver coin', NULL, false, false),
  ('summon_elder_worm', 'Summon Elder Worm', 'conjuration', 'summoning', NULL, 9, 'divine', 'druid 9', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned creature', '1 round/level (D)', 'none', 'no', 'This spell functions as summon nature’s ally VIII, except you summon a purple worm with the giant creature simple template.', NULL, NULL, false, false),
  ('summon_erodaemon', 'Summon Erodaemon', 'conjuration', 'summoning', 'evil', 6, 'both', 'cleric 8, sorcerer/wizard 8, summoner 6, witch 8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like summon monster, except it summons a single erodaemon.', NULL, 'a bent or tarnished wedding band', false, false),
  ('summon_flight_of_eagles', 'Summon Flight of Eagles', 'conjuration', 'summoning', NULL, 4, 'both', 'bloodrager 4, druid 6, ranger 4, shaman 6, sorcerer/wizard 6, summoner 6, witch 6', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1d4+1 summoned creatures', '10 minutes/level', 'none', 'no', 'You summon 1d4+1 giant eagles to serve as you designate. The summoned birds can fight if you wish, but can also serve as mounts.', NULL, 'a gold feather worth 100 gp', false, true),
  ('summon_froghemoth', 'Summon Froghemoth', 'conjuration', 'summoning', NULL, 9, 'divine', 'druid 9', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned creature', '1 round/level (D)', 'none', 'no', 'This spell functions as summon nature’s ally IX, except you summon a froghemoth.', NULL, NULL, false, false),
  ('summon_genie', 'Summon Genie', 'conjuration', 'summoning', NULL, 3, 'both', 'cleric 4, sorcerer/wizard 4, summoner 3, witch 4', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned genie', '1 round/level (D)', 'none', 'no', 'This spell functions like summon monster I, except you can summon one janni.', NULL, NULL, true, true),
  ('summon_giant_ally', 'Summon Giant Ally', 'conjuration', 'summoning', 'see text', 6, 'divine', 'druid 6', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as summon nature’s ally VI, except its casting time is shorter and you can summon one cave, hill, marsh, river, slag, stone, or wood giant.', NULL, NULL, true, false),
  ('summon_infernal_host', 'Summon Infernal Host', 'conjuration', 'summoning', 'evil, lawful', 5, 'both', 'bard 5, cleric/oracle 5, sorcerer/wizard 5, summoner 5, witch 5', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1d4+1 lesser host devils or 1 greater host devil', '1 round/level', 'none', 'no', 'This spell functions as summon monster V, save that it can only be used to summon host devils. These noxious flying devils are also known as gaavs and magaavs.', NULL, NULL, true, false),
  ('summon_instrument', 'Summon Instrument', 'conjuration', 'summoning', NULL, 0, 'arcane', 'bard 0', '1 round', '0 ft.', NULL, NULL, 'one summoned handheld musical instrument', '1 min./level (D)', 'none', 'no', 'This spell summons one handheld musical instrument of your choice. This instrument appears in your hands or at your feet (your choice). The instrument is typical for its type. Only one instrument appears per casting, and it will play only for you. You can’t summon an instrument too large to be held in two hands. The summoned instrument disappears at the end of this spell.', NULL, NULL, false, false),
  ('summon_kami', 'Summon Kami', 'conjuration', NULL, NULL, 5, 'divine', 'druid 5, shaman 5 Effect one or more kami', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as summon nature’s ally V, except you can summon one kodama, 1d3 fukujin, or 1d4+1 shikigami.', NULL, NULL, false, false),
  ('summon_laborers', 'Summon Laborers', 'conjuration', 'summoning', NULL, 6, 'both', 'cleric 6, shaman 6, summoner 6, witch 6', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned petitioner/caster level', '8 hours (D)', 'none', 'no', 'This spell summons one humanoid petitioner per caster level. These petitioners hail from one plane of your choice and perform tasks at your direction. The petitioners cannot fight or travel to dangerous lands, but do assist your downtime activities within a settlement, increasing the effect of Influence or Labor you spend by 50%, to a maximum of 1 additional point of Influence or Labor for every 2 caster levels you possess. This stacks with any increase to the effect of Influence or Labor that you receive from your followers within the settlement where the downtime activity takes place (if any). Summon laborers is a spell of the same alignment type as the plane from which the summoned petitioners hail (chaotic and evil for the Abyss, lawful and good for Heaven, and so on). Effects that increase the number of creatures summoned by a spell (such as Superior Summoning) do not affect summon laborers.', NULL, NULL, true, false),
  ('summon_lesser_psychopomp', 'Summon Lesser Psychopomp', 'conjuration', 'summoning', NULL, 4, 'both', 'cleric/oracle 5, sorcerer/wizard 5, summoner 4, witch 5', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one or more summoned psychopomps (see text)', '1 round/level (D)', 'none', 'no', 'This spell functions like summon monster, except that it summons 1d3 esobok psychopomps or 1d4+1 nosoi psychopomps.', NULL, NULL, true, false),
  ('summon_meladaemon', 'Summon Meladaemon', 'conjuration', 'summoning', 'evil', 6, 'both', 'cleric 8, sorcerer/wizard 8, summoner 6, witch 8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like summon monster, except it summons a single meladaemon.', NULL, 'an empty wooden bowl', false, false),
  ('summon_minor_ally', 'Summon Minor Ally', 'conjuration', 'summoning', NULL, 1, 'divine', 'druid 1, ranger 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1d3 summoned creatures', '1 round/level (D)', 'none', 'no', 'This spell functions as summon nature’s ally I, except you can summon 1d3 Tiny or smaller animals, such as bats, lizards, monkeys, rats, ravens, toads, or weasels. The summoned animals must all be the same type of creature.', NULL, NULL, true, false),
  ('summon_minor_monster', 'Summon Minor Monster', 'conjuration', 'summoning', NULL, 1, 'both', 'antipaladin 1, bard 1, cleric/oracle 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1d3 summoned creatures', '1 round/level (D)', 'none', 'no', 'This spell functions as summon monster I, except you can summon 1d3 Tiny or smaller animals, such as bats, lizards, monkeys, rats, ravens, toads, or weasels. The summoned animals must all be the same type of creature. As with animals summoned with summon monster I, you may apply one alignment-appropriate template to these animals.', NULL, NULL, true, false),
  ('summon_monster', 'Summon Monster', 'conjuration', 'summoning', 'see text', 1, 'both', 'antipaladin 1, bard 1, cleric/oracle 1, medium 1, psychic 1, sorcerer/wizard 1, spiritualist 1, summoner/unchained summoner 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned creature', '1 round/level (D)', 'none', 'no', 'This spell summons an extraplanar creature (typically an outsider, elemental, or magical beast native to another plane). It appears where you designate and acts immediately, on your turn. It attacks your opponents to the best of its ability. If you can communicate with the creature, you can direct it not to attack, to attack particular enemies, or to perform other actions. The spell conjures one of the creatures from the 1st Level list on Table: Summon Monster. You choose which kind of creature to summon, and you can choose a different one each time you cast the spell.', NULL, NULL, true, false),
  ('summon_nature_s_ally', 'Summon Nature’s Ally', 'conjuration', 'summoning', NULL, 1, 'divine', 'druid 1, ranger 1, shaman 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned creature', '1 round/level (D)', 'none', 'no', 'This spell summons to your side a natural creature (typically an animal, fey, magical beast, outsider with the elemental subtype, or a giant). The summoned ally appears where you designate and acts immediately, on your turn. It attacks your opponents to the best of its ability. If you can communicate with the creature, you can direct it not to attack, to attack particular enemies, or to perform other actions as you command.', NULL, NULL, true, false),
  ('summon_ship', 'Summon Ship', 'conjuration', 'creation', NULL, 3, 'both', 'arcanist 4, bard 4, cleric 4, occultist 3, oracle 4, psychic 4, skald 4, sorcerer 4, summoner 3, unchained summoner 3, warpriest 4, wizard 4', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'One conjured ship', '1 day/level', 'none', 'no', 'When you cast this spell, you must hold out a miniature model of the ship you intend to create. The spell assembles a ship from raw materials conjured from other planes, taking a shape similar to the miniature ship in your hand. The miniature ship must be elaborately carved and worth 10% of the price of the type of ship it represents. The ship comes with all equipment necessary for sailing or rowing the ship but provides no crew or cargo. If you attempt to conjure the ship into a location where there isn’t a sufficient amount of water to keep the ship afloat, the spell fails. The ship displaces all water and Medium or smaller aquatic animals within its space when it appears, but the location must be otherwise unoccupied at the time of casting the spell. You can cast this spell again to extend the duration of the conjured ship, replacing the remaining duration with the new spell’s duration. When the spell’s duration ends or the spell is dismissed, the ship instantly stops moving and then falls apart over the course of a minute.', NULL, 'a miniature ship; see text', false, false),
  ('summon_stampede', 'Summon Stampede', 'conjuration', 'summoning', NULL, 4, 'both', 'cleric/oracle 6, druid 6, summoner 4', '1 round', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '20-ft.-radius herd of animals', '1 round/level', 'Reflex halves (see text)', 'no', 'You conjure a herd of aurochs or similar herd animal that immediately stampedes in the direction you indicate. The herd takes up a 20-foot-radius space and moves at a rate of 120 feet per round in a straight line. Any creatures caught in the herd’s path take 4d6+9 points of damage that round as they are trampled beneath dozens of animals’ hooves. A successful Reflex save halves this damage.', 'piece of fur from a herd animal', NULL, false, false),
  ('summon_swarm', 'Summon Swarm', 'conjuration', 'summoning', NULL, 2, 'both', 'bard 2, druid 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2; Mystery apocalypse 2', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one swarm of bats, rats, or spiders', 'concentration + 2 rounds', 'none', 'no', 'You summon a swarm of bats, rats, or spiders (your choice), which attacks all other creatures within its area. (You may summon the swarm so that it shares the area of other creatures.) If no living creatures are within its area, the swarm attacks or pursues the nearest creature as best it can. The caster has no control over its target or direction of travel.', 'a square of red cloth', NULL, true, false),
  ('summon_thanadaemon', 'Summon Thanadaemon', 'conjuration', 'summoning', 'evil', 9, 'both', 'cleric 9, sorcerer/wizard 9, witch 9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like summon monster, except it summons a single thanadaemon. You can only use this spell in an area with enough open water to accommodate the daemon’s skiff, or when on the Astral Plane or Ethereal Plane.', NULL, 'two silver coins', false, false),
  ('summon_totem_creature', 'Summon Totem Creature', 'conjuration', 'summoning', NULL, 3, 'both', 'cleric 3, druid 3, ranger 3, sorcerer/wizard 3, summoner 3', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned creature', '1 hour (D)', 'none', 'no', 'Some people revere more than the deities of distant planes, but also the animals and natural forces of the rugged lands they call home. These spellcasters have learned ways to call upon the might of their totem creatures in times of need.', 'a piece of bone from any one of your totem animals', NULL, true, false),
  ('summon_vanth', 'Summon Vanth', 'conjuration', 'summoning', NULL, 5, 'both', 'cleric/oracle 6, sorcerer/wizard 6, summoner 5, witch 6', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one summoned vanth psychopomp', '1 round/level (D)', 'none', 'no', 'This spell functions like summon monster, except that it summons a single vanth psychopomp.', NULL, NULL, true, false),
  ('summoner_conduit', 'Summoner Conduit', 'necromancy', NULL, NULL, 4, 'both', 'cleric 4, sorcerer/wizard 5, summoner/unchained summoner 4, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one summoned creature or eidolon', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You exploit the invisible, mystic connection between the target creature and its summoner to harm that summoner. Whenever the target’s summoned creature is the target of a spell that deals damage, the target’s summoner is also considered to be a target of that spell. Such a summoner gains his normal defenses against the spell, such as a saving throw and spell resistance, and cannot be affected if he is on another plane of existence.', 'two flies', NULL, false, false),
  ('sun_metal', 'Sun Metal', 'transmutation', NULL, 'fire', 1, 'divine', 'cleric/oracle 1, paladin 1, ranger 1', '1 standard action', 'touch', 'one melee weapon', NULL, NULL, '1 round/level (see text)', 'Fort negates (object)', 'yes (object)', 'The target weapon ignites into flame that does not hurt the weapon or the wielder, but damages those hit by the weapon. When the weapon’s wielder hits with this weapon, it deals an additional 1d4 points of fire damage. This damage is not multiplied in the case of a critical hit. This effect immediately ends if the weapon is submerged in water. This effect does not stack with the flaming or flaming burst weapon special ability or any other effect that grants the weapon extra fire damage. It does not function on weapons with the frost or icy burst weapon special ability or any other effect that grants a weapon extra cold damage.', NULL, NULL, false, false),
  ('sun_s_disdain', 'Sun’s Disdain', 'transmutation', NULL, 'curse', 2, 'both', 'bloodrager 2, cleric/oracle 2, inquisitor 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You alter a creature so the touch of the sun is hostile to it.', 'a piece of glass', NULL, true, false),
  ('sunbeam', 'Sunbeam', 'evocation', NULL, 'light', 7, 'divine', 'druid 7, shaman 7; Domain sun 7; Subdomain stars 7; Mystery solar 7', '1 standard action', '60 ft.', NULL, 'line from your hand', NULL, '1 round/level or until all beams are exhausted*', 'Reflex negates and Reflex half; see text', 'yes', 'For the duration of this spell, you can use a standard action to evoke a dazzling beam of intense light each round. You can call forth one beam per three caster levels (maximum six beams at 18th level). The spell ends when its duration runs out or your allotment of beams is exhausted.', NULL, NULL, true, false),
  ('sunburst', 'Sunburst', 'evocation', NULL, 'light', 8, 'both', 'druid 8, shaman 8, sorcerer/wizard 8; Domain sun 8; Subdomain seasons 8; Bloodline celestial 8; Mystery heavens 8, solar 8', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '80-ft.-radius burst', NULL, 'instantaneous', 'Reflex partial; see text', 'yes', 'Sunburst causes a globe of searing radiance to explode silently from a point you select. All creatures in the globe are blinded and take 6d6 points of damage. A creature to which sunlight is harmful or unnatural takes double damage. A successful Reflex save negates the blindness and reduces the damage by half.', 'sunstone and fire source', NULL, true, false),
  ('sunder_breaker', 'Sunder Breaker', 'abjuration', NULL, 'force', 1, 'arcane', 'magus 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level (D) or until discharged', 'Will negates (harmless) and see text', 'yes (harmless) and see text', 'You place an invisible ward upon the target. The next time a creature succeeds at a sunder combat maneuver against the target, the attacker’s weapon takes 1d6 points of damage per caster level (maximum 10d6). If the attacker used a natural weapon for the sunder, the attacker takes half this damage. Spell resistance applies to this damage. The attacker can attempt a Fortitude save to halve this damage.', NULL, NULL, false, false),
  ('sundered_serpent_coil', 'Sundered Serpent Coil', 'conjuration', 'creation', NULL, 3, 'arcane', 'magus 3, sorcerer/wizard 3, summoner 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'one 5-foot square', NULL, '1 round/level (D)', 'none', 'no', 'This spell functions like black tentacles, except it creates a Large decapitated snake, which erupts from the ground and grapples a creature you specify within its 5-foot reach. As a standard action, you can command the snake to release its grappled target and direct it to attack a different creature.---', 'a snake scale', NULL, false, false),
  ('sundering_shards', 'Sundering Shards', 'transmutation', NULL, NULL, 1, 'arcane', 'bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'melee weapon touched', NULL, NULL, '1 hour/level or until discharged', 'Reflex negates (see text)', 'yes', 'You channel power into a melee weapon. If the weapon’s wielder destroys an item with a successful sunder combat maneuver, she can release the extra power in the weapon, shattering the sundered item into jagged shards that deal 1d6 points of piercing and slashing damage to the creature that was wearing, carrying, or wielding the now-shattered item. Any creature (other than the wielder of the weapon targeted by this spell) adjacent to that creature must succeed at a Reflex saving throw or take 1d6 points of piercing and slashing damage from flying shards. The shards also count as whatever special materials the sundered item was made of (for example, the shards from a shattered cold iron weapon are cold iron). Once the weapon’s extra power is unleashed, the spell is discharged.', NULL, NULL, false, false),
  ('sunstalker', 'Sunstalker', 'illusion', 'glamer', NULL, 3, 'both', 'bard 3, ranger 3, sorcerer/wizard 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes', 'A touched creature becomes invisible (as per invisibility) as long as it is in direct sunlight (or bright light shed by a daylight spell). If an action the target creature takes causes the invisible creature to become visible but does not end the sunstalker spell’s duration, the creature can use this spell’s magic to become invisible again as a standard action as long as it stands in an area of sunlight (as defined above). The creature gains only concealment (20% miss chance) in normal light.', NULL, NULL, true, false),
  ('suppress_charms_and_compulsions', 'Suppress Charms and Compulsions', 'abjuration', NULL, NULL, 2, 'both', 'bard 2, cleric 2, mesmerist 2, paladin 2, psychic 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature plus one additional creature per 4 levels, no two of which can be more than 30 ft. apart', NULL, NULL, '10 minutes or concentration (up to 1 round/level); see text', 'Will negates (harmless)', 'yes (harmless)', 'You bolster the subject’s sense of willpower and self-worth when you cast this spell.', NULL, NULL, false, false),
  ('suppress_primal_magic', 'Suppress Primal Magic', 'abjuration', NULL, NULL, 4, 'both', 'cleric 4, sorcerer/wizard 4', '1 standard action', '10 ft.', NULL, '10-ft.-radius emanation centered on you', NULL, '1 round/level', NULL, NULL, 'Primal magic events cannot be triggered within the area of effect of this spell.', 'a pinch of sand', NULL, false, false),
  ('suppressing_stone', 'Suppressing Stone', 'evocation', NULL, NULL, 3, 'arcane', 'occultist 3, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level or until discharged (D)', NULL, NULL, 'You infuse arcane power into the focus ioun stone, which must be currently floating around your head. If the ioun stone ever ceases floating around you, the spell ends immediately, and the spell fails if the ioun stone in question is cracked, burned, flawed, or otherwise of lesser value (such as a dull gray stone stone). While the spell is active, you gain a +1 resistance bonus on saving throws against mind-affecting effects for every 4 caster levels (maximum +5 at caster level 20). Whenever you fail a saving throw against a mind-affecting spell or effect, you can burn out the focus, transforming it irrevocably into a dull gray stone stone and ending this spell, but suppressing the mind-affecting effect for 1 round per 2,500 gp of value of the focus (minimum 1 round). Rounds during which the effect is suppressed still count against its duration, and the effect can still be dispelled or disrupted during this time.', NULL, 'one ioun stone worth at least 1,000 gp', false, true),
  ('sure_casting', 'Sure Casting', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, sorcerer/ wizard 1, witch 1', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You gain temporary insight into your enemies’ magical defenses. When you next cast a spell before the end of the next round, treat your caster level as 5 higher than normal for the purpose of overcoming spell resistance. This bonus doesn’t increase any other effects that depend on caster level, such as the spell’s damage or range, and affects only the first spell cast after sure casting.', NULL, 'a square of cloth and a needle', false, false),
  ('surefoot_boots', 'Surefoot Boots', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, occultist 2, ranger 2, shaman 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'none', 'no', 'You touch your boots, shoes, or other footwear and imbue them with the ability to find purchase on even the most treacherous ground. While the spell is in effect, the footwear’s wearer treats any Acrobatics skill check to balance as though the wearer had rolled a 20.', NULL, 'footwear', false, false),
  ('surface_excursion', 'Surface Excursion', 'conjuration', 'teleportation', NULL, 4, 'both', 'arcanist 5, magus 5, occultist 4, psychic 5, shaman 5, sorcerer/wizard 5, spiritualist 4, summoner 4, summoner (unchained) 4, witch 5', '3 rounds', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'no', 'You instantly transport yourself and touched allies onto the nearest sky-facing surface directly above you. The destination surface may be solid ground or the surface of a body of water (or other liquid), depending on your position. If reaching the surface would require crossing planar boundaries or no sky-facing surface exists directly above your position, the spell fails and has no effect.', 'a handful of soil that has been in the sun for at least 6 hours', NULL, false, false),
  ('surmount_affliction', 'Surmount Affliction', 'abjuration', NULL, NULL, 2, 'divine', 'cleric/oracle 2, inquisitor 2', '1 standard action', 'you', 'personal', NULL, NULL, '1 round/level', NULL, NULL, 'You temporarily overcome one harmful condition. This does not end the effect causing the condition; it just suspends that condition’s effect for the duration of the spell. You can surmount any one of the following conditions: blinded, confused, dazed, dazzled, deafened, fatigued, frightened, paralyzed, shaken, or sickened.', NULL, NULL, false, false),
  ('suspend_drowning', 'Suspend Drowning', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, cleric 1, druid 1, ranger 1', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The affected creatures immediately—though temporarily—stop drowning and cannot suffocate or drown while this spell is in effect. A target that had been reduced to below 1 hit point from drowning immediately returns to 1 hit point. The magic of this spell allows the targets to breathe, drink, and talk normally for the duration of the spell, but targets cannot inhale to increase the amount of air remaining in their lungs. When the spell effect ends, the target resumes drowning unless it is in an environment that allows it to breathe normally (such as an air-breathing creature returning to the surface) or has obtained a method of breathing normally (such as by consuming a potion of water breathing).', NULL, NULL, false, false),
  ('swallow_poison', 'Swallow Poison', 'transmutation', NULL, NULL, 5, 'both', 'alchemist 5, druid 5, shaman 5, witch 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level or until discharged', NULL, NULL, 'A special gland grows on the inside of your throat, which absorbs any poisons that you ingest, and can be used to expel them in a toxic spray. Any time you consume ingested poison during the spell’s duration, you can roll a caster level check against the poison’s save DC in order to harmlessly absorb the poison, ignoring its effects. The spell can absorb up to 1 dose of poison per 3 caster levels, after which the gland is unable to process any more poison, and any further doses of ingested poison affect you normally.', NULL, NULL, true, false),
  ('swallow_your_fear', 'Swallow Your Fear', 'enchantment', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes; see text', 'Will negates (harmless)', 'yes (harmless)', 'You make the affected subjects ready for battle despite their fear. If a target is suffering from a fear effect of any kind, he gains a +2 morale bonus to Strength and Constitution, a +1 morale bonus on Will saves, and a -2 penalty to AC.', NULL, NULL, false, false),
  ('swarm_of_fangs', 'Swarm of Fangs', 'conjuration', 'summoning', NULL, 3, 'both', 'druid 3, psychic 3, sorcerer/ wizard 3, summoner 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one swarm of animate teeth', '1 round/level', 'none', 'no', 'You summon a swarm consisting of thousands of animate, flying teeth in a 10-foot-by-10-foot cube. These fangs attack all creatures within the swarm’s area. You can summon the swarm so that it shares an area with other creatures, and you can move the swarm up to 40 feet each round as a move action. If you choose not to move the swarm, it automatically moves up to 40 feet to envelop the nearest creature (including you) if it has not already done so.', 'a lizard’s tooth', NULL, false, false),
  ('swarm_skin', 'Swarm Skin', 'transmutation', NULL, NULL, 6, 'both', 'druid 6, witch 6', '1 standard action', 'personal', NULL, NULL, NULL, 'see text', NULL, NULL, 'You convert all of your soft tissue into swarms of insects or other creatures and send them off to do your bidding, leaving nothing but your bones and gear behind. These swarms have all their normal qualities and abilities but also bear a tiny portion of your consciousness that allows you to perceive what they do and to control their actions. While in this form, you cannot use any of your own abilities or take any actions other than controlling the swarms.', 'a crushed insect hive', NULL, true, false),
  ('sweat_poison', 'Sweat Poison', 'necromancy', 'poison', NULL, 2, 'both', 'alchemist 2, druid 3, inquisitor 3, ranger 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'none', 'no', 'Glands along your neck, back, or wrists swell and exude a viscous injury poison (save Fort DC 14; frequency 1/round for 4 rounds; effect 1d2 Str; cure 1 save). You are not immune to this poison, and unless you have the poison use class feature or a similar ability, you are at risk of poisoning yourself. You can apply this poison to a weapon as a move action, and each dose you apply reduces the remaining duration of this spell by 1 minute. If doing so would reduce the remaining duration to 0 minutes or less, the spell ends, and any applied poisons retain their potency only until the end of your turn.', NULL, NULL, false, false),
  ('swift_girding', 'Swift Girding', 'transmutation', NULL, NULL, 1, 'both', 'magus 1, paladin 1, sorcerer/ wizard 1', '1 standard action', 'close (25 feet + 5 feet/level)', 'one willing creature/level', NULL, NULL, 'instantaneous', 'none', 'yes (harmless)', 'With a sweep of your hand, you select a number of targets and the same number of suits of armor.', 'the armor to be worn', NULL, false, false),
  ('swipe', 'Swipe', 'conjuration', 'teleportation', NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one held item', NULL, NULL, 'instant', 'none', 'no', 'By flicking a finger in the appropriate direction and proclaiming ownership, you attempt to magically wrest an item from the target’s grip and summon it to your hand. To claim an object held by an opponent, you must make a CMB check—this check has a bonus equal to your caster level + your Intelligence, Wisdom, or Charisma modifier (whichever is highest). If you fail this check, the target retains the item and the spell fails. If you succeed, the item teleports into one of your free hands or comes to rest at your feet.', NULL, NULL, false, false),
  ('sword_to_snake', 'Sword to Snake', 'transmutation', NULL, 'poison', 4, 'both', 'cleric 4, druid 4, shaman 4, sorcerer/wizard 4, summoner 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one Medium or smaller item', NULL, NULL, '1 round/level (D)', 'Will negates (object)', 'yes (object)', 'When you make an undulating gesture using your hand, the target item changes slightly in shape and appearance to resemble a cross between its original form and that of a venomous animal.', 'a hair from a spider', NULL, true, false),
  ('sylvan_hideaway', 'Sylvan Hideaway', 'conjuration', 'creation', NULL, 3, 'divine', 'druid 3, ranger 3, shaman 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'When this spell is cast on a  natural, unworked surface, it creates an extradimensional underground space large enough to comfortably hold two creatures of any size per caster level (maximum 12). The room is sealed by a 5-foot-square camouflaged trap door that can be locked from within. (This trap door has hardness 10 and 20 hit points per caster level; the Perception DC to see the hidden trap door equals the spell’s save DC.) The door and room are made of the same material of the material component used to cast the spell. You can choose the shape and configuration of the room when you create it; however, any furnishings (tables, beds, etc.) in the room are made of the same material as the room and cannot be moved once created. When the spell ends, anything inside the space is ejected to the surface in the nearest available square.', 'one pound of unworked stone or wood', NULL, false, false),
  ('symbol_of_death', 'Symbol of Death', 'necromancy', NULL, 'death', 8, 'both', 'cleric/oracle 8, sorcerer/wizard 8, witch 8; Domain rune 8', '10 minutes', '0 ft.; see text', NULL, NULL, 'one symbol', 'see text', 'Fortitude negates', 'yes', 'This spell allows you to scribe a potent rune of power upon a surface. When triggered, a symbol of death kills one or more creatures within 60 feet of the symbol (treat as a burst) whose combined total current hit points do not exceed 150. The symbol of death affects the closest creatures first, skipping creatures with too many hit points to affect. Once triggered, the symbol becomes active and glows, lasting for 10 minutes per caster level or until it has affected 150 hit points’ worth of creatures, whichever comes first. A creature that enters the area while the symbol of death is active is subject to its effect, whether or not that creature was in the area when it was triggered. A creature need save against the symbol only once as long as it remains within the area, though if it leaves the area and returns while the symbol is still active, it must save again.', 'mercury and phosphorus, plus powdered diamond and opal worth 5,000 gp each', NULL, false, true),
  ('symbol_of_debauchery', 'Symbol of Debauchery', 'enchantment', 'compulsion', 'emotion, mind-affecting', 6, 'both', 'bard 6, cleric/oracle 8, sorcerer/wizard 8, witch 8', '10 minutes', '0 ft.; see text', NULL, NULL, 'one symbol', 'see text', 'Will negates', 'yes', 'You conjure a sizable symbol into being, a rune suggestive of bloated bodies, flung food, and flowing wine. This spell functions as symbol of death, except that all creatures within 60 feet of the symbol of debauchery are instead filled with lust for the nearest conscious creature. This effect lasts for 1 round per caster level, even after creatures leave the symbol’s area of effect. Affected creatures are compelled to rush to the nearest creature in order to caress and kiss it, and may take no other actions. Each creature receives a single Will save when the symbol of debauchery is triggered to negate the effect. If no other creatures are visible, an affected creature may act normally.', 'a set of bull genitals and powdered ruby worth 5,000 gp', NULL, false, true),
  ('symbol_of_dispelling', 'Symbol of Dispelling', 'abjuration', NULL, NULL, 8, 'both', 'cleric/oracle 8, shaman 8, sorcerer/wizard 8, witch 8', '10 minutes', '0 ft.; see text', NULL, NULL, 'one symbol', 'instantaneous', 'none', 'no', 'This spell functions as symbol of death, except that all creatures within 40 feet of the symbol of dispelling are instead affected as if by the area dispel function of greater dispel magic. Attempt a dispel check when casting symbol of dispelling. Once the symbol is triggered, apply the result of that check to each creature in the area, as well as each object that is the target of one or more spells. Unlike symbol of death, symbol of dispelling grants no saving throws, and it is not subject to spell resistance.', 'pure grain alcohol and powdered diamond worth 5,000 gp', NULL, false, true),
  ('symbol_of_distraction', 'Symbol of Distraction', 'enchantment', 'compulsion', 'mind-affecting', 4, 'both', 'bard 6, cleric 6, mesmerist 6, occultist 4, psychic 6, sorcerer/wizard 6, witch 6', '10 minutes', '0 feet; see text', NULL, NULL, 'one symbol', 'see text', 'Will negates', 'yes', 'This spell functions like symbol of death, except that all creatures within the radius of a symbol of distraction instead become fascinated by the symbol for 10 minutes per caster level. Unlike symbol of death, symbol of distraction has no hit point limit; once triggered, a symbol of distraction simply remains active for a duration of 10 minutes × your caster level.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 5,000 gp', NULL, false, true),
  ('symbol_of_exsanguination', 'Symbol of Exsanguination', 'necromancy', NULL, 'evil', 2, 'both', 'bloodrager 2, cleric 3, occultist 2, sorcerer/wizard 3, witch 3', '10 minutes', '0 ft.; see text', NULL, NULL, 'one symbol', '10 minutes/level', 'Fort negates', 'yes', 'This spell functions like symbol of death, except that each creature within the radius of symbol of exsanguination begins to bleed uncontrollably and violently from their eyes, ears, nose, and mouth, as well as any existing open wounds. Creatures that failed their saving throws immediately take 1d6 points of bleed damage and are sickened as long as they continue to take bleed damage from the symbol.', 'powdered garnet and bloodstone worth a total of 500 gp', NULL, false, true),
  ('symbol_of_fear', 'Symbol of Fear', 'necromancy', NULL, 'emotion, fear, mind-affecting', 6, 'both', 'cleric/oracle 6, sorcerer/wizard 6, witch 6', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', NULL, 'This spell functions like symbol of death, except that all creatures within 60 feet of the symbol of fear instead become panicked for 1 round per caster level.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 1,000 gp', NULL, false, true),
  ('symbol_of_healing', 'Symbol of Healing', 'conjuration', 'healing', NULL, 3, 'both', 'cleric/oracle 3, paladin 4, witch 4', NULL, NULL, NULL, NULL, NULL, NULL, 'Will half (harmless) (see text)', 'yes (harmless) (see text)', 'This spell functions as symbol of death, except all creatures within 60 feet of the symbol of healing instead are bathed in positive energy and heal 2d8 points + 1 point of damage per caster level (maximum +15). Undead and other creatures harmed by positive energy instead take 2d8 points of damage + 1 point per caster level (maximum +15); a Will save reduces this damage by half. A creature can only be healed or harmed by the symbol once in any 24-hour period. Once triggered, the symbol remains active for 10 minutes per caster level.', 'mercury and phosphorous, plus powdered diamond and opal worth a total of 500 gp', NULL, false, true),
  ('symbol_of_insanity', 'Symbol of Insanity', 'enchantment', 'compulsion', 'mind-affecting', 8, 'both', 'cleric/oracle 8, sorcerer/wizard 8, witch 8', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', NULL, 'This spell functions like symbol of death, except that all creatures within the radius of the symbol of insanity instead become permanently insane (as the insanity spell).', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 5,000 gp', NULL, false, true),
  ('symbol_of_laughter', 'Symbol of Laughter', 'enchantment', 'charm', 'mind-affecting', 1, 'arcane', 'sorcerer/wizard 4, witch 4 Components V, S, M (mercury and phosphorus, plus powdered diamond and opal worth a total of 1,000 gp) Saving Throw Will negates; Spell Resistance yes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as symbol of death, except that all creatures within 60 feet are affected with uncontrollable laughter (as hideous laughter) for 1 round per caster level.', NULL, NULL, false, false),
  ('symbol_of_mirroring', 'Symbol of Mirroring', 'illusion', 'figment', NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', NULL, NULL, NULL, NULL, NULL, 'see text', 'Will partial (harmless)', 'yes', 'This spell functions as symbol of death, except it instead creates one illusory duplicate of each creature within 60 feet of the symbol. These duplicates function as mirror image, moving with the original creatures and mimicking their movements, sounds, and actions exactly. If an illusory double is destroyed, a new one appears on the creature’s turn. The images last for as long as a creature remains within 60 feet of the symbol, and for 1 round/level thereafter. Once triggered, the symbol remains active for 10 minutes per caster level.', 'mercury and phosphorous, plus powdered diamond and opal worth a total of 100 gp', NULL, false, true),
  ('symbol_of_pain', 'Symbol of Pain', 'necromancy', NULL, 'evil, pain', 5, 'both', 'cleric/oracle 5, sorcerer/wizard 5, witch 5; Subdomain kyton (evil, law) 5, torture 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like symbol of death, except that each creature within the radius of a symbol of pain instead suffers wracking pains that impose a -4 penalty on attack rolls, skill checks, and ability checks. These effects last for 1 hour after the creature moves farther than 60 feet from the symbol.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 1,000 gp', NULL, false, true),
  ('symbol_of_persuasion', 'Symbol of Persuasion', 'enchantment', 'charm', 'mind-affecting', 6, 'both', 'cleric/oracle 6, sorcerer/wizard 6, witch 6; Subdomain revolution 6, tyranny 6; Mystery intrigue 6', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', NULL, 'This spell functions like symbol of death, except that all creatures within the radius of a symbol of persuasion instead become charmed by the caster (as the charm monster spell) for 1 hour per caster level.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 5,000 gp', NULL, false, true),
  ('symbol_of_revelation', 'Symbol of Revelation', 'divination', NULL, NULL, 4, 'both', 'cleric/oracle 4, sorcerer/wizard 4, witch 4', NULL, NULL, NULL, NULL, NULL, NULL, 'none', NULL, 'This spell functions as symbol of death, except it is only activated by invisible creatures, creatures affected by an illusion (glamer) effect, creatures with the shapechanger subtype, or creatures that have magically changed their shape. These creatures are outlined by a pale light that functions like faerie fire, except it lasts for 10 minutes per caster level; the symbol does not otherwise reveal their true form. Once triggered, a symbol of revelation remains active for 10 minutes per caster level.', 'mercury and phosphorous, plus powdered diamond and opal worth a total of 1,000 gp', NULL, false, true),
  ('symbol_of_scrying', 'Symbol of Scrying', 'divination', 'scrying', NULL, 5, 'both', 'cleric/oracle 5, sorcerer/wizard 5, witch 5', NULL, NULL, NULL, NULL, NULL, NULL, 'none', 'no', 'This spell functions as symbol of death, except that, when triggered, it creates a scrying sensor linked to you and centered on the symbol, even if you are on a different plane than the symbol. You are immediately aware that the symbol has been triggered if you are conscious, and are awakened from normal sleep if sleeping. The symbol does not otherwise disturb your concentration. You may observe the area through the symbol as if using a scrying spell with the sensor as the target creature. Once triggered, the symbol remains active for 10 minutes per caster level.', 'mercury and phosphorous, plus powdered diamond and opal worth a total of 1,000 gp', NULL, false, true),
  ('symbol_of_sealing', 'Symbol of Sealing', 'abjuration', NULL, 'force', 6, 'both', 'cleric/oracle 6, sorcerer/wizard 6, witch 6', '10 minutes', '0 ft.; see text', NULL, NULL, 'one symbol', 'permanent', 'none', 'no', 'This spell allows you to scribe a potent rune of power upon or above a door or other opening measuring no more than 20 square feet/level in size. When the casting is completed, the symbol immediately triggers, glowing visibly and sealing the door or opening with an invisible barrier of force equivalent to a wall of force. Destroying the symbol ends the effect, though destroying it once the symbol has been activated requires destroying the wall of force first. Once triggered, the wall remains for 10 minutes per caster level.', 'mercury and phosphorous, plus powdered diamond and opal worth a total of 5,000 gp', NULL, false, true),
  ('symbol_of_sleep', 'Symbol of Sleep', 'enchantment', 'compulsion', 'mind-affecting', 5, 'both', 'cleric/oracle 5, sorcerer/wizard 5, witch 5', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', NULL, 'This spell functions like symbol of death, except that all creatures of 10 HD or less within 60 feet of the symbol of sleep instead fall into a catatonic slumber for 3d6x10 minutes. Unlike with the sleep spell, sleeping creatures cannot be awakened by non-magical means before this time expires.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 1,000 gp', NULL, false, true),
  ('symbol_of_slowing', 'Symbol of Slowing', 'transmutation', NULL, NULL, 4, 'both', 'cleric/oracle 4, sorcerer/wizard 4, witch 4', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', 'yes', 'This spell functions as symbol of death, except all creatures within 60 feet of a symbol of slowing are slowed (as the slow spell) for 1 round per caster level.', 'mercury and phosphorous, plus powdered diamond and opal worth a total of 1,000 gp', NULL, false, true),
  ('symbol_of_storms', 'Symbol of Storms', 'evocation', NULL, 'air, electricity', 3, 'both', 'arcanist 6, cleric 6, druid 6, hunter 3, oracle 6, ranger 3, sorcerer 6, warpriest 6, witch 6, wizard 6', '10 minutes', '0 ft.; see text', NULL, NULL, NULL, 'see text', 'Reflex half; see text', 'yes', 'This spell functions as symbol of death, except that when triggered, a 30-foot-radius centered on the symbol fills with hurricane-force winds (75 mph). Each round, a bolt of lightning that deals 10d6 points of electricity damage strikes a random creature within the area. A successful Reflex save halves this damage. Unlike symbol of death, symbol of storms has no hit point limit. Regardless of the trigger method or methods chosen, a creature more than 30 feet from a symbol of storms can’t trigger it (even if it meets one or more of the triggering conditions, such as reading the rune). Once triggered, a symbol of storms remains active for 1 minute per caster level.', 'powdered copper and pumice worth a total of 1,500 gp', NULL, false, true),
  ('symbol_of_strife', 'Symbol of Strife', 'enchantment', 'compulsion', 'mind-affecting', 9, 'both', 'cleric/oracle 9, sorcerer/wizard 9, witch 9', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', 'yes', 'This spell functions as symbol of death, except all creatures within the radius of a symbol of strife are compelled to attack the nearest conscious creature for 1 round per caster level (similar to the “attack nearest creature” result of the confusion spell), even after leaving the symbol’s area of effect. If no other creatures are visible, an affected creature can act normally. Once triggered, the symbol remains active for 10 minutes per caster level.', 'mercury and phosphorous, plus powdered diamond opal worth a total of 15,000 gp', NULL, false, true),
  ('symbol_of_striking', 'Symbol of Striking', 'illusion', 'shadow', NULL, 5, 'both', 'cleric 5, magus 5, sorcerer/wizard 5, witch 5', '10 minutes', '0 ft.; see text', NULL, NULL, 'one symbol', 'see text', 'Will half, see text', 'yes, see text', 'This spell functions like symbol of death, except that using the material component, you scribe a symbol of striking so it fills a 5-foot square. Once triggered, the symbol of striking glows and lasts for 10 minutes per caster level or until it has made a number of attacks of opportunity equal to your level, whichever comes first. When triggered, the symbol threatens its area and the area around it as if it were a Medium creature wielding a magic version of the weapon you used as the material component. Using your caster level + 1 + your Intelligence modifier (magus, witch, wizard) or Wisdom modifier (cleric) or Charisma modifier (oracle, sorcerer) as its attack bonus, the symbol can make a number of attacks of opportunity each round equal to 1 + the same ability score modifier you used to determine its attack bonus. It gains a bonus on damage rolls equal to the same ability score modifier you used to determine its attack bonus. A shadowy version of you wielding the material component appears to make these attacks. The symbol attacks any non-attuned creature that provokes an attack of opportunity from the symbol. However, when the symbol first attacks a creature, the symbol must overcome that creature’s spell resistance or be rendered unable to harm it. The symbol never again attacks such creatures. Further, when the symbol first attacks a creature, a successful Will saving throw allows the creature to see the shadow nature of the attacks and take half damage when such attacks hit.', 'a masterwork melee weapon costing at least 300 gp', NULL, false, true),
  ('symbol_of_stunning', 'Symbol of Stunning', 'enchantment', 'compulsion', 'mind-affecting', 7, 'both', 'cleric/oracle 7, sorcerer/wizard 7, witch 7', NULL, NULL, NULL, NULL, NULL, NULL, 'Will negates', NULL, 'This spell functions like symbol of death, except that all creatures within 60 feet of a symbol of stunning instead become stunned for 1d6 rounds.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 5,000 gp', NULL, false, true),
  ('symbol_of_vulnerability', 'Symbol of Vulnerability', 'abjuration', NULL, NULL, 9, 'both', 'cleric/oracle 9, sorcerer/wizard 9, witch 9', NULL, NULL, NULL, NULL, NULL, NULL, 'none', 'no', 'This spell functions as symbol of death, except it saps the defenses of all creatures within 60 feet. Affected creatures receive a –4 penalty to spell resistance and a –4 penalty on saving throws, and energy resistances and damage reduction (if any) are reduced by 10 each (to a minimum of 0). Once triggered, the symbol remains active for 10 minutes per level. The effects last as long as the creature is within 60 feet of the symbol, and for 1 round per caster level afterward.', 'mercury and phosphorous, plus powdered diamond opal worth a total of 15,000 gp', NULL, false, true),
  ('symbol_of_weakness', 'Symbol of Weakness', 'necromancy', NULL, NULL, 7, 'both', 'cleric/oracle 7, sorcerer/wizard 7, witch 7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like symbol of death, except that every creature within 60 feet of a symbol of weakness instead suffers crippling weakness that deals 3d6 points of Strength damage.', 'mercury and phosphorus, plus powdered diamond and opal worth a total of 5,000 gp', NULL, false, true),
  ('sympathetic_aura', 'Sympathetic Aura', 'illusion', 'glamer', NULL, 2, 'arcane', 'bard 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one touched object weighing up to 5 lbs./level', NULL, NULL, '1 day/level (D)', 'none (see text)', 'no', 'This spell functions like magic aura, except it extends its altered aura to similar items in a 5-foot radius. For this purpose, similar items must be alike in approximate shape, composition, and function, so a potion of cure light wounds targeted by this spell to appear non-magical would also obscure the auras of nearby potions, elixirs, and oils, as well as flasks. Items other than the targeted item retain their altered aura for 1 round per caster level after being removed from the spell’s area.', NULL, 'a small square of silk that must be passed over the object that receives the aura', false, false),
  ('sympathetic_vibration', 'Sympathetic Vibration', 'evocation', NULL, 'sonic', 6, 'arcane', 'bard 6', '10 minutes', 'touch', 'one freestanding structure', NULL, NULL, 'up to 1 round/level', 'none; see text', 'yes', 'By attuning yourself to a freestanding structure, you can create a damaging vibration within it. Once it begins, the vibration deals 2d10 points of damage per round to the target structure, bypassing hardness. You can choose at the time of casting to limit the duration of the spell; otherwise it lasts for 1 round per level. If the spell is cast upon a target that is not freestanding, the surrounding stone dissipates the effect and no damage occurs.', NULL, 'a tuning fork', false, false),
  ('sympathetic_wounds', 'Sympathetic Wounds', 'abjuration', NULL, 'evil', 2, 'divine', 'cleric/oracle 2, druid 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, NULL, 'Will negates', 'yes', 'This spell functions like shield other, except some of your wounds transfer to the targeted creature rather than some of their wounds transferring to you. For example, you could link yourself to a nearby chained slave so that when you are wounded, some of the damage is transferred to the slave. You must have at least as many hit dice as the target, otherwise the spell fails. A creature can only be under the effects of one instance of this spell at a time.', '250 gp of powdered amber', NULL, false, true),
  ('sympathy', 'Sympathy', 'enchantment', 'compulsion', 'emotion, mind-affecting', 6, 'both', 'druid 9, sorcerer/wizard 8, summoner 6, witch 8', '1 hour', 'close (25 ft. + 5 ft./2 levels)', 'one location (up to a 10-ft. cube/level) or one object', NULL, NULL, '2 hours/level (D)', 'Will negates; see text', 'yes', 'You cause an object or location to emanate magical vibrations that attract either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you. The particular kind of creature to be affected must be named specifically. A creature subtype is not specific enough. Likewise, the specific alignment must be named.', 'a drop of honey and crushed pearls worth 1,500 gp', NULL, false, true),
  ('synapse_overload', 'Synapse Overload', 'divination', NULL, 'mind-affecting', 4, 'arcane', 'mesmerist 4, psychic 5', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fortitude partial (see text)', 'yes', 'You cause the target’s mind to unleash a vast overflowing torrent of information throughout the target’s body, causing the target’s synapses to violently trigger. The target takes 1d6 points of electrical damage per caster level (maximum 15d6) and is staggered for 1 minute. A successful Fortitude saving throw doesn’t reduce the damage, but it negates the staggered effect.', NULL, NULL, false, false),
  ('synaptic_pulse', 'Synaptic Pulse', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'mesmerist 3, psychic 3', '1 standard action', '30 ft.', NULL, '30-ft.-radius spread centered on you', NULL, '1 round', 'Will negates', 'yes', 'You emit a pulsating mental blast that stuns all creatures in range of your psychic shriek for 1 round.', NULL, NULL, false, false),
  ('synaptic_scramble', 'Synaptic Scramble', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'mesmerist 3, psychic 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You scramble the synaptic connections of your target, causing it to lose the ability to coherently communicate and to take unintended actions when it meant to perform others. The target cannot effectively communicate while under the spell’s influence, and thus cannot engage in acts like speaking, attempting Bluff checks to pass secret messages, writing, or using telepathy, although the spell doesn’t prevent verbalizations made for purposes other than communication, such as command words or the verbal component of spellcasting.', NULL, NULL, false, false),
  ('synesthesia', 'Synesthesia', 'illusion )', 'phantasm', 'mind-affecting', 3, 'arcane', 'mesmerist 3, psychic 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You overstimulate the senses of the affected creature, causing its senses to interfere with another. While a creature is under the effects of this spell, sensory input is processed by the wrong senses, such that noise triggers bursts of colors, smells create sounds, and so on. The affected creature moves at half speed, has a 20% miss chance on attacks, and takes a –4 penalty to AC and on skill checks and Reflex saves. Successful spellcasting while affected requires a concentration check with a DC equal to this spell’s save DC plus the level of spell being cast.', NULL, NULL, false, false),
  ('tactical_acumen', 'Tactical Acumen', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'bard 2, inquisitor 2, magus 2, medium 2, occultist 2, paladin 1, psychic 2, sorcerer/wizard 2', '1 standard action', '30 ft.', NULL, 'The caster and all allies within a 30-ft.-radius burst, centered on the caster', NULL, '1 round/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'Tactical acumen grants you and your allies a mastery of battlefield tactics. Whenever you would gain a bonus on attack rolls or to AC due to battlefield position, such as flanking, higher ground, or cover, you gain an additional +1 insight bonus. This bonus increases by +1 for every five caster levels above 5th you possess (maximum +4).', 'a small piece of a map', NULL, true, false),
  ('tactical_adaptation', 'Tactical Adaptation', 'transmutation', NULL, NULL, 3, 'arcane', 'magus 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell was developed by an Academy student after several weeks of observing (and occasionally joining) barroom brawls. You draw on your mind’s hidden reserves, instantaneously mastering advanced combat techniques.', NULL, 'a gold and sapphire ring worth 500 gp, which the caster must wear for the spell’s duration', false, true),
  ('tactical_formation', 'Tactical Formation', 'abjuration', NULL, NULL, 3, 'divine', 'cleric/oracle 3, paladin 3, ranger 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'up to one creature/level, no two of which may be more than 30 ft. apart', NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'This spell increases the effectiveness of a group’s formation in battle. When cast, all creatures under the effect of the spell must be adjacent to one another, forming an unbroken chain of squares (which may include creatures sharing the same square). This chain does not need to be a straight line. Each target in the chain receives a +2 defection bonus to AC as long as the targets stay adjacent to at least one other creature affected by the spell; moving more than 5 feet from another target ends the spell with respect to that creature only. For example, a cleric could cast it on himself and four dwarves blocking a 20-foot-wide corridor; the cleric can move freely from the left side of the formation to the right side (whether in front of or behind the other targets) and not break the spell as long as he stays within 5 feet of at least one of them.', NULL, NULL, false, false),
  ('tactical_insight', 'Tactical Insight', 'divination', NULL, NULL, 6, 'both', 'bard 6, inquisitor 6', '1 standard action', '1 hex', NULL, NULL, NULL, '1 battle', 'none', 'no', 'Choose a single army tactic. You grant mastery of this tactic to the target army for the spell’s duration. This tactic may bring an army’s total known tactics to a number greater than normally allowed.', NULL, NULL, false, false),
  ('tactical_miscalculation', 'Tactical Miscalculation', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'both', 'bard 2, inquisitor 2, ranger 2', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The target becomes fixated on avoiding damage and fails to spot even the most opportune moments to attack. Whenever a creature the target threatens would provoke an attack of opportunity from the target, the target must succeed at a Will save or be unable to make the attack of opportunity against that creature.', NULL, NULL, false, false),
  ('tail_current', 'Tail Current', 'transmutation', NULL, 'water', 3, 'both', 'bloodrager 4, cleric 4, druid 3, magus 4, occultist 3, ranger 3, shaman 3, sorcerer/wizard 4, spiritualist 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as tailwind except it creates a helpful current in water instead of in the air. It grants free movement while swimming rather than while flying and functions only underwater.', NULL, NULL, false, false),
  ('tail_strike', 'Tail Strike', 'transmutation', NULL, 'draconic', 3, 'both', 'alchemist 4, antipaladin 3, bloodrager 3, medium 3, paladin 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (see text)', NULL, NULL, 'You grow a draconic tail (clothing and armor adjust as necessary), or if you already have a tail, it takes on a draconic appearance. If you have a draconic bloodline, the tail matches the appearance of that dragon type; otherwise, it matches the appearance of a dragon type whose alignment matches your own. You gain a tail slam attack that deals 1d6 points of damage (1d4 if Small, 1d8 if Large) + your Strength modifier. If you already have a tail attack, you instead extend the reach of your tail attack by 5 feet.', 'a dragon scale', NULL, false, false),
  ('tailwind', 'Tailwind', 'transmutation', NULL, 'air', 3, 'both', 'bloodrager 4, cleric 4, druid 3, magus 4, occultist 3, ranger 3, shaman 3, sorcerer/wizard 4, spiritualist 3', '1 standard action', '120 ft.', NULL, NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'You compel the wind to push the targets in a direction of your choice. The subjects can hustle during local and overland movement without risk of fatigue. If the subjects are flying, the first 20 feet of movement each round in the chosen direction does not count against their movement for the round. Each creature remains affected only while within 120 feet of every other subject. You can change the tailwind’s direction once per hour by concentrating as a standard action. This spell has no effect underwater.', NULL, NULL, false, false),
  ('talisman_of_reprieve', 'Talisman of Reprieve', 'abjuration', NULL, NULL, 3, 'divine', 'cleric 5, inquisitor 4, paladin 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '20-ft.-radius emanation centered on an item', NULL, NULL, '10 minutes/level', NULL, NULL, 'You imbue an item with an aura of divine amnesty, allowing all allies within the aura’s area to ignore penalties to Intelligence-, Wisdom-, and Charisma-based checks resulting from a plane’s mildly or strongly aligned traits, regardless of the allies’ alignments. In addition, the item grants a +4 circumstance bonus on checks with one Intelligence-, Wisdom-, or Charisma-based skill determined by you at the time of casting.', NULL, NULL, true, false),
  ('talismanic_implement', 'Talismanic Implement', 'evocation', NULL, NULL, 3, 'arcane', 'occultist 3', '10 minutes', 'personal', 'you', NULL, NULL, '1 hour/level (D) or until discharged', NULL, NULL, 'This spell functions as contingency, but you invest a spell whose level doesn’t exceed one-quarter of your level (rounded down, maximum spell level 3rd) into one of your implements that holds 2 or more points of mental focus. The spell’s school must match that of the implement, and the spell must be one that affects only your person.', NULL, NULL, false, false),
  ('tamer_s_lash', 'Tamer’s Lash', 'evocation', NULL, 'sonic', 1, 'both', 'bard 1, bloodrager 1, magus 1, ranger 1', '1 standard action', '0 ft.', NULL, NULL, 'a whip of magical sound', '1 round/level (D)', 'Will partial (see text)', 'yes', 'A 15-foot-long whip of sonic energy springs from your hand, delivering a loud crack when you strike with it. The tamer’s lash acts as a whip that deals 1d4 points of sonic damage on a hit, but it has no physical substance and you cannot use it to perform combat maneuvers, nor can it be sundered or disarmed. If you strike an animal with the tamer’s lash, the animal must succeed at a Will saving throw or be unable to attack you for 1d3 rounds. Furthermore, if the whipped animal starts its turn unable to attack you as a result of this spell and it is within 30 feet of you, it must spend its first action moving away from you, if it is able. Combat-trained animals, animal companions, and animals with Hit Dice in excess of your caster level + 4 gain a +4 circumstance bonus on their saves to avoid being intimidated in this way. This intimidation effect is a mind-affecting fear effect.', NULL, NULL, false, false),
  ('tap_inner_beauty', 'Tap Inner Beauty', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell allows you to tap into the natural beauty of your soul and let it shine from your eyes and your speech. While the spell is active, you gain a +2 insight bonus on all Charisma ability checks and Charisma-based skill checks.', 'a tiny mirror', NULL, false, false),
  ('tar_ball', 'Tar Ball', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ranged attack', 'instantaneous', 'none', 'no', 'You create a sticky ball of burning tar that you can hurl at your enemies as a ranged attack. If the tar ball strikes, it deals 1d4 points of fire damage + your Strength modifier, and splashes the target with hot, sticky tar. The tar deals 1d4 points of fire damage each round on the creature’s turn for the next 1d4 rounds and gives the target a –2 penalty to Dexterity for that duration. If desired, the target can use a full-round action to attempt to extinguish or cool the tar before taking this additional damage. Extinguishing or cooling the tar requires a DC 15 Reflex save or at least 1 gallon of nonflammable liquid. Rolling on the ground provides the target a +2 bonus on the save. Leaping into a lake or magically cooling the target automatically ends the effect.', 'a tiny ball of bitumen', NULL, false, false),
  ('tar_pool', 'Tar Pool', 'transmutation', NULL, 'earth, fire', 5, 'both', 'druid 6, sorcerer/wizard 6, summoner 5, unchained summoner 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius burst', NULL, '1 round/level', 'Reflex partial, see text', 'no', 'You convert a layer of the ground to hot tar. Creatures in the area when the tar appears take 1d6 points of fire damage per two caster levels (maximum of 10d6) and must succeed at a Reflex save or become entangled. An entangled creature receives a saving throw each round to free itself from the tar, and can also attempt to free itself by spending a move action to attempt a Strength check or Escape Artist check (DC = spell saving throw DC). It costs 2 squares of movement to enter a square in the area of effect, and the DC of Acrobatics checks within the area of effect increases by 5. The area is difficult terrain. A creature that moves into or starts its turn in the area takes 2d6 points of fire damage and must reattempt this Reflex save or become entangled. A creature that falls prone in the area takes a –4 penalty on its Reflex save against the tar and on Strength and Escape Artist checks to escape the tar.', 'a ball of hardened tar', NULL, true, false),
  ('targeted_bomb_admixture', 'Targeted Bomb Admixture', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon drinking an extract created with this formula, you make a significant change to your magical reserve that modifies the nature of all bombs you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can only have one admixture effect (formula with the word “bomb admixture” in its title) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and the new one becomes active.', NULL, NULL, false, false),
  ('tattoo_potion', 'Tattoo Potion', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, sorcerer/ wizard 2, witch 2', '1 minute', 'one potion', NULL, NULL, 'one spell tattoo', 'instantaneous', 'none', 'no', 'When you cast this spell, you mix special tattoo inks into a potion of your choice. Once you finish casting tattoo potion , the potion begins bubbling and fizzing—if no one drinks the potion within 1 minute of the spell being cast, the potion bubbles away into vapor and is destroyed.', 'a potion to be tattooed, special inks worth 500 gp', NULL, false, true),
  ('tears_to_wine', 'Tears to Wine', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, cleric 2, druid 1, medium 1, occultist 1, shaman 1, sorcerer/wizard 2, witch 2', '1 standard action', '10 ft.', '1 cu. ft./2 levels of liquid (see text)', NULL, NULL, '10 minutes/level', 'Will negates (object)', 'yes (object)', 'This spell turns nonmagic liquids—including spoiled, rotten, diseased, poisonous, or otherwise contaminated drinks, tears, seawater, and similar fluids—into mead or wine of average quality. This spell does not prevent subsequent natural decay or spoilage.', 'a single grape', NULL, false, false),
  ('technomancy', 'Technomancy', 'divination', NULL, NULL, 1, 'arcane', 'bard 1, sorcerer/wizard 1', '1 standard action', '60 ft.', 'cone-shaped emanation', NULL, NULL, '3 rounds/level', 'none', 'no', 'This spell functions as detect magic, except it detects the presence of technological objects instead of magical objects. The spell grants you the Technologist feat for the purposes of attempting Knowledge (engineering) checks to identify the properties of technological items in your possession. If you already possess this feat, you gain a +10 bonus on Knowledge (engineering) checks to identify item properties.', 'oil stirred with a coil of wires', NULL, false, false),
  ('tectonic_communion', 'Tectonic Communion', 'divination', NULL, NULL, 7, 'divine', 'druid 7', '1 hour', 'personal', 'you', NULL, NULL, 'Instantaneous', NULL, NULL, 'Tectonic communion functions as commune with nature with an even greater range. In outdoor or natural underground settings, the spell operates on a radius of 100 miles per caster level, extending even underground without penalty.', NULL, NULL, true, false),
  ('telekinesis', 'Telekinesis', 'transmutation', NULL, NULL, 5, 'arcane', 'magus 5, sorcerer/wizard 5; Mystery ancestor 5', '1 standard action', 'long (400 ft. + 40 ft./level)', 'or Targets see text', NULL, NULL, 'concentration (up to 1 round/level) or instantaneous; see text', 'Will negates (object) or none; see text', 'yes (object); see text', 'You move objects or creatures by concentrating on them. Depending on the version selected, the spell can provide a gentle, sustained force, perform a variety of combat maneuvers, or exert a single short, violent thrust.', NULL, NULL, false, false),
  ('telekinetic_assembly', 'Telekinetic Assembly', 'transmutation', NULL, NULL, 2, 'arcane', 'magus 2, occultist 2, psychic 2, sorcerer/wizard 2', '1 minute', 'close (25 ft + 5 ft./2 levels)', 'one disassembled siege engine', NULL, NULL, 'instantaneous', 'none', 'no', 'You assemble a siege engine, using up to one fewer worker per two caster levels you possess. You can do without one additional worker if you have any ranks in Knowledge (engineering), plus one additional worker per 5 ranks you have in that skill. If your caster level combined with Knowledge (engineering) fails to eliminate the need for workers, this spell fails.', NULL, 'a miniature of the target siege engine, costing 10 gp', false, true),
  ('telekinetic_charge', 'Telekinetic Charge', 'evocation', NULL, 'force', 4, 'arcane', 'bloodrager 4, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one willing creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You telekinetically launch an ally across the battlefield to anywhere within this spell’s range. While moving, your ally is flying just above the ground unless you wish otherwise. Movement from this spell provokes attacks of opportunity as normal, although you can lift your ally over objects or out of enemy reach, as long as your ally remains within this spell’s range. If your ally lands adjacent to an opponent, he can spend an immediate action to make a melee attack against that opponent with a +2 bonus on the attack roll.', NULL, NULL, false, false),
  ('telekinetic_maneuver', 'Telekinetic Maneuver', 'transmutation', NULL, NULL, 3, 'arcane', 'magus 4, psychic 3, sorcerer/wizard 4, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'concentration (up to 1 round/level)', 'none', 'yes', 'This spell functions as telekinesis, but it can be used only to perform a bull rush, disarm, drag, grapple (including pin), reposition, steal, or trip combat maneuver.', NULL, NULL, false, false),
  ('telekinetic_projectile', 'Telekinetic Projectile', 'evocation', NULL, NULL, 0, 'arcane', 'occultist 0, psychic 0, spiritualist 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'no', 'no', 'You fling an object weighing up to 5 pounds at the target. You must succeed at a ranged attack (not a ranged touch attack) to hit your target; if you hit, you deal 1d6 points of bludgeoning damage to both the target and the object. The type of object thrown doesn’t change the damage type or any other properties of the attack, even if you throw a weapon or magic item in this way.', NULL, NULL, false, false),
  ('telekinetic_sphere', 'Telekinetic Sphere', 'evocation', NULL, 'force', 8, 'arcane', 'sorcerer/wizard 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1-ft.-diameter/level sphere, centered around creatures or objects', '1 min./level (D)', 'Reflex negates (object)', 'yes (object)', 'This spell functions like resilient sphere, but the creatures or objects caught inside the globe created by the spell are made nearly weightless. Anything contained within a telekinetic sphere weighs only one-sixteenth of its normal weight. You can telekinetically lift anything in the sphere that normally weighs 5,000 pounds or less. The telekinetic control extends from you out to medium range (100 feet + 10 feet per caster level) after the sphere has succeeded in encapsulating its contents.', 'a crystal sphere and a pair of small magnets', NULL, false, false),
  ('telekinetic_storm', 'Telekinetic Storm', 'evocation', NULL, 'force', 9, 'arcane', 'psychic 9', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You generate a storm of telekinetic energy that emanates from you, ripping through the spell’s area of effect with devastating force. Any creature caught in the spell’s radius takes 1d6 points of damage per caster level (maximum 20d6) and is dazed and stunned for 1 round. A successful Fortitude save reduces the damage by half and negates the dazed and stunned effects.', NULL, NULL, false, false),
  ('telekinetic_strikes', 'Telekinetic Strikes', 'evocation', NULL, 'force', 2, 'arcane', 'magus 2, psychic 2, sorcerer/ wizard 2', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'The touched creature’s limbs are charged with telekinetic force.', NULL, NULL, false, false),
  ('telekinetic_volley', 'Telekinetic Volley', 'transmutation', NULL, NULL, 2, 'arcane', 'magus 2, sorcerer/wizard 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level or until discharged (D)', 'none (object)', 'no (object)', 'The touched items levitate in your space. When you cast the spell and once per round thereafter, you can launch one item at a target of your choice as a standard action. The ranged attack is made as if you had thrown the item unless it’s ammunition for a weapon, in which case the attack is made as if fired from a heavy crossbow (if a bolt), a halfling sling staff (if a sling bullet), a blowgun (if a blowgun dart), a composite longbow with a +2 Strength rating (if an arrow), an atlatl (if an atlatl dart), or a pistol (if a firearm bullet). A firearm pellet launched by the spell functions as a shuriken.', NULL, NULL, false, false),
  ('telempathic_projection', 'Telempathic Projection', 'enchantment', 'compulsion', 'emotion, mind-affecting', 1, 'arcane', 'mesmerist 1, psychic 1, spiritualist 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (see text)', 'yes', 'You alter the target’s mood, adjusting its attitude toward you or another creature you designate by one step either positively or negatively (see the Diplomacy skill). You can instead use this spell to assist your own or an ally’s Bluff, Diplomacy, Intimidate, Perform, or Sense Motive check, granting that check a +5 insight bonus against the target of your telempathic projection with no save. In this case, the spell’s duration expires immediately when the skill check is complete.', NULL, NULL, false, false),
  ('telepathic_bond', 'Telepathic Bond', 'divination', NULL, NULL, 5, 'both', 'inquisitor 5, sorcerer/wizard 5, witch 5; Domain community 5; Subdomain aeon 5, friendship 5, language 5, thought 5; Elemental School void 5, wood 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 min./level (D)', 'none', 'no', 'You forge a telepathic bond among yourself and a number of willing creatures, each of which must have an Intelligence score of 3 or higher. Each creature included in the link is linked to all the others. The creatures can communicate telepathically through the bond regardless of language. No special power or influence is established as a result of the bond. Once the bond is formed, it works over any distance (although not from one plane to another).', 'two eggshells from two different creatures', NULL, false, false),
  ('telepathic_censure', 'Telepathic Censure', 'abjuration', NULL, NULL, 2, 'both', 'bard 2, inquisitor 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature (see text)', NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'This spell creates an invisible psychic interference that inhibits telepathic communication. When cast upon a creature that can communicate via telepathy, this spell prevents that ability’s use— either to receive or project thoughts. When cast upon a creature without telepathy, the spell merely prevents the target from receiving telepathic communication. Those affected by this spell or that attempt to telepathically communicate with creatures under its effects are not innately aware that their communication is being inhibited. This spell temporarily disrupts spells and effects like telepathic bond or telepathic messages sent by a helm of telepathy, but not attacks and effects unrelated to communication like detect thoughts or a neothelid’s psychic crush.', NULL, NULL, false, false),
  ('telepathic_silence', 'Telepathic Silence', 'illusion', 'glamer', NULL, 4, 'arcane', 'medium 4, mesmerist 4, occultist 4, psychic 4, spiritualist 4', '1 round', 'long (400 ft. + 40 ft./level)', NULL, '60-ft.-radius emanation centered on a point in space', NULL, '1 round/level (D)', 'none', 'no', 'Creatures within the area cannot send or receive telepathic messages, and anyone in the area casting a spell with a thought component must succeed at a concentration check (DC = 20 + twice the spell’s level; this includes the increased concentration DC for casting spells with a thought component) or lose the spell. Furthermore, the thoughts of creatures within the area cannot be detected, located, or read with thoughtsense, detect thoughts, or similar effects.', NULL, NULL, false, false),
  ('telepathy', 'Telepathy', 'divination', NULL, 'mind-affecting', 4, 'arcane', 'medium 4, mesmerist 4, psychic 5, sorcerer/wizard 6, spiritualist 6', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You can mentally communicate with any other creature within 100 feet that has a language. It is possible to address multiple creatures at once telepathically, although maintaining a telepathic conversation with more than one creature at a time is just as difficult as speaking and listening to multiple people simultaneously.', NULL, NULL, false, false),
  ('teleport', 'Teleport', 'conjuration', 'teleportation', NULL, 4, 'arcane', 'magus 5, occultist 5, psychic 5, sorcerer/wizard 5, spiritualist 5, summoner 4, unchained summoner 5, witch 5; Domain travel 5; Elemental School void 5', '1 standard action', 'personal and touch', 'you and touched objects or other touched willing creatures', NULL, NULL, 'instantaneous', 'none and Will negates (object)', 'no and yes (object)', 'This spell instantly transports you to a designated destination, which may be as distant as 100 miles per caster level. Interplanar travel is not possible. You can bring along objects as long as their weight doesn’t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as four Medium creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. As with all spells where the range is personal and the target is you, you need not make a saving throw, nor is Spell Resistance applicable to you. Only objects held or in use (attended) by another person receive saving throws and Spell Resistance.', NULL, NULL, false, false),
  ('teleport_object', 'Teleport Object', 'conjuration', 'teleportation', NULL, 7, 'arcane', 'sorcerer/wizard 7, witch 7', '1 Standard Action', 'touch', 'one touched object of up to 50 lbs./level and 3 cu. ft./level', NULL, NULL, NULL, 'Will negates (object)', 'yes (object)', 'This spell functions like teleport, except that it teleports an object, not you. Creatures and magical forces cannot be teleported.', NULL, NULL, false, false),
  ('teleport_structure', 'Teleport Structure', 'conjuration', 'teleportation', NULL, 6, 'arcane', 'sorcerer/wizard 6', '8 hours', 'touch', 'one building', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You instantly teleport a building in a settlement you control to another lot or series of lots in the same settlement district. The building to be teleported must be unoccupied, and the area to which you wish to move the building must be cleared and unoccupied during the casting of this spell. A building cannot be teleported to an area it would not normally be able to occupy, such as an area adjacent to a prohibited building type. If you don’t wholly own the structure, all of the structure’s owners must consent to the structure’s teleportation before the spell is cast; otherwise, it fails immediately.', 'gold dust worth 50 gp', NULL, false, true),
  ('teleport_trap', 'Teleport Trap', 'abjuration', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Subdomain trap 7', '10 minutes', 'medium (100 ft. + 10 ft./level)', NULL, 'one 40-ft. cube/level (S)', NULL, '1 day/level', 'Will negates', 'yes', 'Teleport trap wards an area, redirecting all teleportation into or out of the area to a specific point within the area determined by you at the time of casting. The destination must be an open space on a solid surface. The spell’s area overlaps walls and other solid and liquid objects (preventing intruders from bypassing the ward by teleporting into a wall or through similar means). A teleporting creature that is affected by a teleport trap can resist the effect with a Will save—if the save is successful, the creature simply doesn’t teleport at all (but the use of the teleport effect is still consumed)—either to the intended location or the teleport trap’s actual destination. A DC 27 Knowledge (arcana) allows such a creature to recognize the teleport trap’s presence, but does not reveal the trap’s linked destination.', 'powdered lodestones and silver worth 100 gp per 40-ft. cube', NULL, false, true),
  ('teleportation_circle', 'Teleportation Circle', 'conjuration', 'teleportation', NULL, 6, 'arcane', 'psychic 9, sorcerer/wizard 9, summoner 6, witch 9; Domain rune 9', '10 minutes', '0 ft.', NULL, NULL, '5-ft.-radius circle that teleports those who activate it', '10 min./level (D)', 'none', 'yes', 'You create a circle on the floor or other horizontal surface that teleports, as greater teleport, any creature who stands on it to a designated spot. Once you designate the destination for the circle, you can’t change it. The spell fails if you attempt to set the circle to teleport creatures into a solid object, to a place with which you are not familiar and have no clear description, or to another plane.', 'amber dust to cover circle worth 1,000 gp', NULL, false, true),
  ('temporal_divergence', 'Temporal Divergence', 'transmutation', NULL, NULL, 7, 'arcane', 'arcanist 7, psychic 7, sorcerer/wizard 7, witch 7', '1 swift action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'This spell allows you to witness two divergent decisions and choose which to pursue. Upon completing this spell, you must immediately choose two other different spells that you could cast at that moment and that each have a casting time of 1 standard action; these spells take effect simultaneously, and you must track all resulting effects, areas of effect, saving throws, and other outcomes separately as if each had been cast normally and the other spell had never happened. Once you’ve seen how each spell resolves, you must choose which version of reality occurred, expending the standard action, prepared spell, and material components as necessary. The other spell’s results are ignored and do not require an action or expend the prepared spell, spell slot, or material components. If the targets of the spell you did not choose expended any resources or effects to resist your spell, those resources or effects are also not expended. If you cast this spell and do not or cannot immediately follow the instructions described above, this spell has no effect.', 'mithral wishbone worth 100 gp', NULL, false, true),
  ('temporal_regression', 'Temporal Regression', 'conjuration', 'teleportation', NULL, 8, 'both', 'arcanist 8, druid 9, psychic 8, witch 8, wizard 8', '1 standard action', 'personal and close (25 ft. + 5 ft./2 levels; see below)', NULL, NULL, NULL, '1 round/level or until discharged', 'none', 'no', 'When you complete this spell, note your current location and condition, including your hit point total and any ongoing conditions affecting you as well as their durations (e.g. poison, sickened, ability damage, and spell effects). This spell creates a beacon in space-time that’s imperceptible to anyone but you. As a standard action while you are within range of the beacon before the spell’s duration expires, you can discharge the spell to transport yourself back to the marked location and restore yourself to the condition you were in when you cast the spell; this does not restore any expended items, charges, or spells you may have used during that time. This does not reverse effects for anyone else, and to bystanders it appears as though you teleported to the beacon location and regained conditions you had when the beacon was set. Temporal regression strains your body; when the spell is discharged, you gain 1 temporary negative level for every 2 rounds that passed since you cast the spell. These negative levels disappear after 24 hours.', NULL, 'hourglass filled with powdered horacalcum worth 1,500 gp', false, true),
  ('temporal_stasis', 'Temporal Stasis', 'transmutation', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8; Mystery time 8', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Fortitude negates', 'yes', 'You must succeed on a melee touch attack. You place the subject into a state of suspended animation. For the creature, time ceases to flow, and its condition becomes fixed. The creature does not grow older. Its body functions virtually cease, and no force or effect can harm it. This state persists until the magic is removed (such as by a successful dispel magic spell or a freedom spell).', 'powdered diamond, emerald, ruby, and sapphire dust worth 5,000 gp', NULL, false, true),
  ('temporary_graft', 'Temporary Graft', 'transmutation', NULL, NULL, 3, 'arcane', 'alchemist 3, bloodrager 3, magus 4, occultist 3, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You temporarily graft a dismembered body part onto yourself. You must have the body part in your possession or the spell has no effect. The graft must come from a creature the same size category as you. You can have only one graft active at a time. Grafting on a new body part immediately ends the effects of the older casting and causes that body part to fall off. The effect of the graft depends on the type of body part you choose to graft to yourself, as follows.', NULL, 'a dismembered body part', false, false),
  ('temporary_resurrection', 'Temporary Resurrection', 'necromancy', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7, witch 7', '10 minutes', 'touch', 'dead creature touched', NULL, NULL, '24 hours', NULL, NULL, 'You restore temporary life to a body that has been dead for less than 48 hours. The spell lasts for 24 hours, after which the target dies again. The target gains 1 permanent negative level while under the effect of this spell; this negative level goes away when the target dies or is permanently raised from the dead (such as with raise dead). The target still counts as a dead corpse (but not undead) for the purpose of spells that revive dead creatures, so a cleric can cast raise dead or a similar spell on the target even while this spell is active. Once a creature has been revived with temporary resurrection, this spell cannot be used on it again until it is permanently raised from the dead.', 'diamond dust worth 500 gp', NULL, false, true),
  ('terrain_bond', 'Terrain Bond', 'enchantment', 'compulsion', 'mind-affecting', 4, 'divine', 'ranger 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/2 levels (D)', NULL, NULL, 'You call upon the spirits of nature to help you adapt to your environment. You treat the terrain you are in as your most favored terrain until this spell ends.', 'a pinch of earth taken from your most favored terrain', NULL, false, false),
  ('terrible_remorse', 'Terrible Remorse', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'both', 'bard 3, cleric/oracle 4, inquisitor 3, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 living creature', NULL, NULL, '1 round/level', 'Will partial (see text at right)', 'yes', 'You fill a target with such profound remorse that it begins to harm itself. Each round, the target must save or deal 1d8 points of damage + its Strength modifier to itself using an item held in its hand or with unarmed attacks. If the creature saves, it is staggered for 1 round and takes a -2 penalty to Armor Class, after which the spell ends.', NULL, NULL, false, false),
  ('thanatotic_fury', 'Thanatotic Fury', 'transmutation', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4, witch 4', '1 standard action', 'personal', 'you (see text)', NULL, NULL, '1 minute/level', NULL, NULL, 'Note You may cast this spell only if you have the giant subtype.', 'shavings from a holy symbol', NULL, false, false),
  ('thaumaturgic_circle', 'Thaumaturgic Circle', 'abjuration', NULL, NULL, 3, 'both', 'cleric 4, inquisitor 4, medium 3, occultist 3, sorcerer/wizard 4, summoner 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as magic circle against chaos, evil, good, or law, but rather than stipulating an alignment descriptor, You can designate any one non-alignment subtype of outsider, including air, earth, fire, and water, as well as outsider races such as angels and devils.', NULL, NULL, false, false),
  ('theft_ward', 'Theft Ward', 'abjuration', NULL, NULL, 1, 'both', 'cleric 1, inquisitor 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one object', NULL, NULL, '1 day', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You ward a single object in your possession against theft. You gain a +10 bonus on Perception checks to notice someone trying to take the object from you.', NULL, NULL, false, false),
  ('they_know', 'They Know', 'enchantment', 'compulsion', 'emotion, fear', 3, 'both', 'bard 3, inquisitor 3, mesmerist 3, paladin 3, psychic 4, shaman 4, witch 4', '1 standard action', 'medium (100 ft. plus 10 ft./level)', 'one intelligent creature', NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You instill a target with the fear that the nearest other intelligent creature knows her darkest secret. If she is in the midst of another situation as vital as protecting her darkest secret, such as combat, this doesn’t cause her to cease participating, but otherwise, she becomes compelled to use her abilities and skills to determine exactly how much the other individual knows.', 'a drop of black ink', NULL, true, false),
  ('thirsting_entanglement', 'Thirsting Entanglement', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4, hunter 4, ranger 4, shaman 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'plants in a 40-ft.-radius spread', NULL, '1 min./level (D)', 'Reflex partial; see text', 'no', 'This spell functions as entangle, except the plants latch on to targets and drain away their vitality. Any creature that fails a save to avoid becoming entangled or fails a check to break free takes 1d2 points of Constitution damage.', NULL, NULL, true, false),
  ('thorn_body', 'Thorn Body', 'transmutation', NULL, NULL, 3, 'both', 'alchemist 3, druid 4, shaman 4; Mystery wood 4', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'This spell causes spines to grow from your exposed skin, damaging creatures that strike you. Any creature striking you with a melee weapon, an unarmed strike, or a natural weapon takes 1d6 points of piercing damage +1 point per caster level (maximum +15). Creatures using melee weapons with reach are unaffected by this spell. Creatures that successfully grapple you take 2d6 points of piercing damage +1 point per caster level (maximum +15). In addition, your natural attacks and unarmed strikes deal an additional 1d6 points of piercing damage.', NULL, NULL, true, false),
  ('thorn_javelin', 'Thorn Javelin', 'conjuration', 'creation', 'poison', 1, 'divine', 'druid 1, ranger 1, shaman 1', '1 standard action', '0 ft.', NULL, NULL, 'javelin-like thorn', '1 minute/level (D)', 'none', 'no', 'A wooden thorn the size of a javelin (appropriate for your size) appears in your open hand. You can wield this thorn as a javelin, and you are proficient in its use. Any creature struck by the javelin must succeed at a Fortitude save or be sickened for 1 round. If you throw the javelin, another one appears in your hand. Any javelin that leaves your grasp disappears at the end of your turn. Each javelin attack you make reduces the spell’s remaining duration by 1 minute. If an attack reduces the remaining duration to 0 minutes or less, the spell ends after that attack resolves.', NULL, NULL, false, false),
  ('thorny_entanglement', 'Thorny Entanglement', 'transmutation', NULL, NULL, 3, 'both', 'druid 3, ranger 3, shaman 3, witch 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as entangle, except the plants also grow thorns and can fling them up to 15 feet. Any creature that moves within 15 feet of the spell’s area is attacked once on its turn by the animated plants. The plants use your caster level as their base attack bonus and add your spellcasting ability score modifier (Intelligence for witches; Wisdom for druids, rangers, and shamans) to the attack roll. A volley of thorns counts as a thrown weapon and deals 2d6 points of piercing damage on a successful hit. A creature that enters the spell’s area or ends its turn there automatically takes 2d6 points of piercing damage.', NULL, NULL, true, false),
  ('thought_echo', 'Thought Echo', 'illusion', 'glamer', NULL, 1, 'arcane', 'mesmerist 1, psychic 1', '1 round', 'touch', 'living creature touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'When you cast this spell, you establish a mental echo of up to 25 words. Any attempt to read the surface thoughts of the target creature reads only this mental echo unless the caster succeeds at a caster level check (DC = 11 + your caster level). If you cast thought echo on yourself, the DC is instead equal to 15 + your caster level. In addition, when casting this spell upon yourself, you can change the echoed thoughts by taking a standard action and concentrating.', NULL, NULL, false, false),
  ('thought_shield', 'Thought Shield', 'abjuration', NULL, NULL, 2, 'arcane', 'psychic 2', '1 immediate action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'Sensing an intrusion, you throw up a defense to protect your mind from attack or analysis. This grants you a +4 circumstance bonus on Will saving throws against mind-affecting effects. As long as this spell lasts, spells and effects that allow a creature to read your thoughts receive no information from you.', NULL, NULL, false, false),
  ('thought_worm_i', 'Thought Worm I', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'psychic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You implant a minor suggestion within the target creature’s psyche that makes it less inclined to resist mental intrusion. The target creature takes a –2 penalty on Will saves against all mind-affecting spells and effects for the duration of the spell.', NULL, NULL, false, false),
  ('thoughtsense', 'Thoughtsense', 'divination', NULL, 'mind-affecting', 4, 'arcane', 'medium 4, mesmerist 4, psychic 4, sorcerer/wizard 5, spiritualist 4', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You automatically detect and locate conscious creatures within 60 feet, as if you possessed the blindsight ability.', 'a bit of dried brain tissue', NULL, false, false),
  ('threefold_aspect', 'Threefold Aspect', 'transmutation', NULL, NULL, 4, 'divine', 'druid 5, witch 4; Bloodline imperious 4; Mystery time 4', '1 standard action', 'personal', NULL, NULL, NULL, '24 hours (D)', NULL, NULL, 'Threefold aspect allows you to shift your appearance between your natural age and three idealized age categories: young adult (youth/maiden), adulthood (father/mother), or elderly (elder/crone). In each case, your appearance is your own at the appropriate age, rather than that of a new individual.', NULL, 'silver crescent worth 5 gp', false, true),
  ('threefold_face', 'Threefold Face', 'transmutation', NULL, NULL, 3, 'arcane', 'arcanist 3, medium 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '9 minutes', NULL, NULL, 'You grow two additional faces set equidistantly around your head, each embodying a different aspect of your personality that you choose (such as kindliness, joy, or wrath). You gain all-around vision and can’t be flanked. Effects that would blind you, deafen you, block your mouth, or otherwise affect your face, including beneficial effects that grant you exceptional vision, only affect a single face (for example, it would take three castings of blindness/deafness to blind you). You lose all-around vision if even a single face becomes blind. This spell doesn’t grant you additional magic item slots or additional heads. When threefold face ends, you gain all the conditions from all three faces, for good or ill.', 'a three-pointed knot', NULL, true, false),
  ('threefold_form', 'Threefold Form', 'divination', NULL, NULL, 9, 'both', 'druid 9, psychic 9, witch 9', '1 standard action', 'personal', 'you', NULL, NULL, '9 rounds', NULL, NULL, 'You pull forth idealized versions of yourself at various ages from your mind, splitting into three copies of yourself.', NULL, 'a green, three-pointed knot made of mithral worth 729 gp', false, true),
  ('threefold_sight', 'Threefold Sight', 'divination', NULL, NULL, 3, 'arcane', 'arcanist 3, bard 3, medium 3, occultist 3, psychic 3, skald 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '3 minutes', NULL, NULL, 'You view several possible futures at once, allowing you to thread a needle around disasters by taking a middle path.', 'a three-pointed knot', NULL, true, false),
  ('thunder_fire', 'Thunder Fire', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 loaded firearm', NULL, NULL, 'instantaneous', 'Will negates (object), see text', 'yes (object), see text', 'The firearm targeted creates a thunderous report, even if the firearm is not loaded. Every creature within 15 feet of the creature wielding or carrying the firearm must succeed at a Fortitude save or be deafened for 1 minute. The creature wielding or carrying the firearm takes a –4 penalty on this saving throw, and his misfire range increases by 1 for 1d4 rounds. If the firearm was loaded when it was targeted by this spell, that ammunition is wasted.', 'a piece of spent thunderstone', NULL, false, false),
  ('thundering_drums', 'Thundering Drums', 'evocation', NULL, 'sonic', 3, 'arcane', 'bard 3', '1 standard action', '15 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Fortitude partial', 'yes', 'You strike the ground in front of you, filling the area in front of you with the thunder of pounding drums. Any creature in the area takes 1d8 points of sonic damage per caster level (maximum 5d8) and is knocked prone. A successful Fortitude save halves the damage and negates being knocked prone.', NULL, NULL, false, false),
  ('thunderous_footfalls', 'Thunderous Footfalls', 'transmutation', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3, summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one Large or larger creature', NULL, NULL, '1 round/level', 'Fort negates (harmless)', 'no (harmless)', 'This spell makes the target creature’s footfalls shake the ground violently as he trundles, which may knock down smaller creatures as he passes by, though it also makes the target slower on land. The target’s land speed is reduced by half (round down to the nearest 5-foot increment), but each time he moves overland adjacent to a creature that is at least one size category smaller than he is, that creature must succeed at a Fortitude saving throw or be knocked prone.', NULL, NULL, false, false),
  ('thunderstomp', 'Thunderstomp', 'evocation', NULL, 'earth', 1, 'both', 'bloodrager 1, druid 1, magus 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'none', 'yes', 'You stomp your foot or strike your weapon against the ground or floor, creating a ripple of power that you can use to trip a creature. Attempt the combat maneuver check to trip the target, but instead of your base attack bonus you can use your caster level, and instead of your Strength modifier you can use your spellcasting ability score modifier (Intelligence for magi and wizards; Wisdom for druids and rangers; Charisma for bloodragers and sorcerers). This does not provoke an attack of opportunity. This spell has no effect if you cannot reach the ground or floor, or if your target is not in contact with the ground or floor.', NULL, NULL, false, false),
  ('tidal_surge', 'Tidal Surge', 'conjuration', 'creation', 'water', 5, 'divine', 'druid 5, shaman 5', '1 standard action', '30 ft. or 60 ft.; see text', NULL, 'cone-shaped burst or line; see text', NULL, 'instantaneous', 'Reflex half', 'no', 'If you cast tidal surge on land, you create an onrushing surge of water 10 feet high in a 30-foot cone that deals 1d6 points of bludgeoning damage for every 2 caster levels you have (maximum 10d6 at 20th level) and extinguishes all non-magical fires in the area. Magical fire effects in the area of a tidal surge are affected as if you had cast dispel magic. In addition to taking damage, creatures that fail their Reflex saves are pushed 1d4×5 feet away from you, and Medium or smaller creatures are also knocked prone.', NULL, NULL, false, false),
  ('time_shudder', 'Time Shudder', 'transmutation', NULL, NULL, 2, 'arcane', 'magus 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', '30 ft.', NULL, '30-ft.-radius emanation centered on you', NULL, '1 round', 'none', 'yes', 'You cause a ripple in time that affects all creatures in the area. At the start of each creature’s turn, there is a 50% chance the creature is hasted (as haste); otherwise it is slowed (as slow).', 'a tiny hourglass', NULL, false, false),
  ('time_stop', 'Time Stop', 'transmutation', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Domain trickery 9; Bloodline astral 9; Elemental School void 9; Mystery lore 9, time 9', '1 standard action', 'personal', 'you', NULL, NULL, '1d4+1 rounds (apparent time); see text', NULL, NULL, 'This spell seems to make time cease to flow for everyone but you. In fact, you speed up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. You are free to act for 1d4+1 rounds of apparent time. Normal and magical fire, cold, gas, and the like can still harm you. While the time stop is in effect, other creatures are invulnerable to your attacks and spells; you cannot target such creatures with any attack or spell. A spell that affects an area and has a duration longer than the remaining duration of the time stop have their normal effects on other creatures once the time stop ends. Most spellcasters use the additional time to improve their defenses, summon allies, or flee from combat.', NULL, NULL, false, false),
  ('timely_inspiration', 'Timely Inspiration', 'divination', NULL, NULL, 1, 'arcane', 'bard 1', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'A word of arcane-empowered inspiration can snatch victory from seeming defeat. Cast this spell when a creature fails an attack roll or skill check. The target gains a +1 competence bonus per five caster levels (maximum +3 bonus) on the attack roll or skill check retroactively. If the bonus is enough to make the failure a success, the roll succeeds.', NULL, NULL, false, false),
  ('tiny_hut', 'Tiny Hut', 'evocation', NULL, 'force', 3, 'arcane', 'bard 3, sorcerer/wizard 3', '1 standard action', '20 ft.', NULL, NULL, '20-ft.-radius sphere centered on your location', '2 hours/level (D)', 'none', 'no', 'You create an unmoving, opaque sphere of force of any color you desire around yourself. Half the sphere projects above the ground, and the lower hemisphere passes through the ground. As many as nine other Medium creatures can fit into the field with you; they can freely pass into and out of the hut without harming it. However, if you remove yourself from the hut, the spell ends.', 'a small crystal bead', NULL, false, false),
  ('tireless_pursuers', 'Tireless Pursuers', 'transmutation', NULL, NULL, 3, 'divine', 'inquisitor 4, ranger 3', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D)', 'Fortitude negates (harmless)', 'yes (harmless)', 'This spell functions as tireless pursuit, except as noted above.', 'a hard biscuit broken into pieces', NULL, false, false),
  ('tireless_pursuit', 'Tireless Pursuit', 'transmutation', NULL, NULL, 1, 'divine', 'inquisitor 1, ranger 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'You harden your body against the stresses of long travel. You halve the damage caused by hustling and forced marching. In addition, for the duration of the spell you ignore any fatigue caused by such travel. Once the spell ends, if you still have any nonlethal damage caused by the hustling or forced march, you become fatigued, or exhausted if already fatigued.', 'a hard biscuit', NULL, false, false),
  ('titanic_anchoring', 'Titanic Anchoring', 'transmutation', NULL, NULL, 3, 'both', 'antipaladin 3, bloodrager 3, cleric 3, magus 3, paladin 3, ranger 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You become grounded and nearly immovable. You are immune to the pull and push special abilities, and all bull rush, grapple, overrun, reposition, and trip combat maneuvers made by creatures your size or smaller always fail. You gain a +10 bonus to your CMD against those combat maneuver checks made by creatures larger than you.', 'a shaving of oak root', NULL, false, false),
  ('toilsome_chant', 'Toilsome Chant', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1', 'see text', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'see text', 'Will negates (harmless)', 'yes (harmless)', 'You can cast this spell as part of the action to begin an inspire competence bardic performance. The benefit of inspire competence persists for as long as is necessary to complete the target’s next skill check using the chosen skill (up to a maximum of 1 hour per caster level), even if you cease your bardic performance.', NULL, NULL, false, false),
  ('tomb_legion', 'Tomb Legion', 'necromancy', NULL, 'evil', 8, 'both', 'cleric 8, sorcerer/wizard 8', '1 standard action', 'medium (100 f. + 10 f./level)', NULL, NULL, '3 or more mummies, no 2 of which can be more than 30 ft. apart; see text', '7 days or 7 months (D); see text', 'none', 'no', 'This spell functions like shambler, except that it calls into existence 1d4+2 mummies rather than shambling mounds.', NULL, NULL, false, false),
  ('tongues', 'Tongues', 'divination', NULL, NULL, 2, 'both', 'alchemist 3, bard 2, cleric/oracle 4, inquisitor 2, medium 2, mesmerist 2, psychic 3, shaman 4, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3, witch 3; Subdomain agathion 3, language 3; Bloodline aberrant 3; Elemental School wood 3; Mystery dark tapestry 3, lore 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level', 'Will negates (harmless)', 'no', 'This spell grants the creature touched the ability to speak and understand the language of any intelligent creature, whether it is a racial tongue or a regional dialect. The subject can speak only one language at a time, although it may be able to understand several languages. Tongues does not enable the subject to speak with creatures who don’t speak. The subject can make itself understood as far as its voice carries. This spell does not predispose any creature addressed toward the subject in any way.', 'a clay model of a ziggurat', NULL, true, false),
  ('torpid_reanimation', 'Torpid Reanimation', 'necromancy', NULL, 'evil', 4, 'both', 'antipaladin 4, cleric 4, occultist 4, shaman 4, sorcerer/wizard 5, spiritualist 4', '1 standard action', 'touch', NULL, NULL, NULL, '1 day/caster level and instantaneous (see text)', 'none', 'no', 'This spell works like animate dead except you set a specific condition for when the animation occurs and you do not immediately have control of the creatures. The condition can be simple, such as being touched, a certain word spoken, or on hearing a specific sound. You can also set a condition based on time, but it must occur within a number of days equal to your caster level. At any time, you can cause the animation to occur as a standard action.', 'an onyx gem worth at least 25 gp per HD of the undead', NULL, false, true),
  ('torrent_of_elemental_rage', 'Torrent of Elemental Rage', 'evocation', NULL, 'air, earth, fire, water', 6, 'arcane', 'sorcerer/wizard 6', '1 standard action', NULL, NULL, NULL, 'persistent line of elements 30 ft. long', 'concentration, 1 round/3 levels (see below)', 'Reflex half', 'yes', 'A shimmering torrent of raw elemental power springs into existence, originating from your outstretched palms. The blast resembles a horizontal whirlwind of howling winds, searing fame, and tumbling shrapnel of ice and metal. Any creature in the area of effect must make a Reflex save or take 8d6 points of damage from a variety of effects—2d6 points of fire damage, 2d6 points of cold damage, 2d6 points of sonic damage, and 2d6 points of slashing damage that overcomes adamantine damage reduction.', NULL, NULL, true, false),
  ('touch_injection', 'Touch Injection', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, psychic 3, sorcerer/wizard 3; Domain [subdomain(s)] Artifice [alchemy]', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level', 'none', 'no', 'You must hold an elixir, infused extract, poison, or potion in hand as you cast this spell. The held substance drains from its container into a magical sac in your body. While the spell lasts, you can deliver the substance with a mere touch. To do so to an opponent, you must make a successful melee touch attack. If you hit, the substance takes effect immediately, despite any onset period, and that opponent receives the normal saving throw (if any) against the substance. In the case of a personal infused extract, the opponent receives both a Fortitude save and spell resistance. If you miss, the substance remains in the magical sac for you to use later.', NULL, NULL, false, false),
  ('touch_of_blindness', 'Touch of Blindness', 'necromancy', NULL, 'darkness, shadow', 1, 'both', 'antipaladin 1, bard 1, cleric 1, sorcerer/wizard 1, shaman 1, witch 1', '1 standard action', 'touch', 'creature or creatures touched (up to one/level)', NULL, NULL, '1 round/level (see text)', 'Fort negates', 'yes', 'A touch from your hand, which is engulfed in darkness, disrupts a creature’s vision by coating its eyes in supernatural darkness. Each touch causes the target to become blinded for 1 round unless it makes a successful Fortitude saving throw. You can use this melee touch attack up to one time per caster level. Any touch attack not used after 1 round per caster level is lost.', NULL, NULL, false, false),
  ('touch_of_bloodletting', 'Touch of Bloodletting', 'necromancy', NULL, NULL, 1, 'both', 'antipaladin 2, bloodrager 1, cleric 1, druid 1, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell causes any existing wounds that the target possesses to bleed profusely. If the creature’s current total hit points are less than its maximum, this spell causes the creature to take 1 point of bleed damage each round and become exhausted for the duration of the spell. A successful DC 15 Heal check or any spell that cures hit point damage negates the effects of this spell.', NULL, NULL, false, false),
  ('touch_of_combustion', 'Touch of Combustion', 'evocation', NULL, 'fire', 1, 'both', 'bloodrager 1, druid 1, inquisitor 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'creature or object touched', NULL, NULL, 'instantaneous', 'Reflex negates; see text', 'yes', 'Your successful melee touch attack causes the target to ignite in a violent burst of flame, dealing 1d6 points of fire damage. If it fails its saving throw, the target also catches on fire. If the target catches fire, on the first round thereafter, creatures adjacent to it (including you) must each succeed at a Reflex save or take 1d4 points of fire damage.', NULL, NULL, false, false),
  ('touch_of_fatigue', 'Touch of Fatigue', 'necromancy', NULL, NULL, 0, 'both', 'shaman 0, sorcerer/wizard 0, witch 0', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fortitude negates', 'yes', 'You channel negative energy through your touch, fatiguing the target. You must succeed on a touch attack to strike a target. The subject is immediately fatigued for the spell’s duration.', 'a drop of sweat', NULL, false, false),
  ('touch_of_gracelessness', 'Touch of Gracelessness', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, bloodrager 1, sorcerer/wizard 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Fortitude partial', 'yes', 'With a single touch, you reduce a creature to a fumbling clown.', NULL, NULL, false, false),
  ('touch_of_idiocy', 'Touch of Idiocy', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'bloodrager 2, medium 2, mesmerist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2; Domain madness 2; Subdomain lust 2; Bloodline accursed 2, daemon 2, div 2', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '10 min./level', 'no', 'yes', 'With a touch, you reduce the target’s mental faculties. Your successful melee touch attack applies a 1d6 penalty to the target’s Intelligence, Wisdom, and Charisma scores. This penalty can’t reduce any of these scores below 1.', NULL, NULL, false, false),
  ('touch_of_madness', 'Touch of Madness', 'enchantment', NULL, 'mind-affecting', 2, 'arcane', 'madness 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'The touched creature gains the dazed condition.', NULL, NULL, false, false),
  ('touch_of_mercy', 'Touch of Mercy', 'enchantment', 'compulsion', 'good, mind-affecting', 2, 'both', 'bard 2, cleric 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'The target creature deals only nonlethal damage with all of its weapon attacks. Damage taken by creatures or objects that are not subject to nonlethal damage is not converted to nonlethal and remains lethal damage. The weapon retains all of its other normal properties.', NULL, NULL, true, false),
  ('touch_of_slime', 'Touch of Slime', 'conjuration', 'creation', 'disease', 4, 'both', 'alchemist 4, bloodrager 4, druid 4, sorcerer/wizard 4, witch 4', '1 standard action', NULL, 'living creature touched', NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'You create a coating of slime on your hand. When you make a successful melee touch attack with the slime, it pulls free of you and sticks to the target, at which point it acts like green slime (Core Rulebook 416), dealing 1d3 points of Constitution damage per round. Anything that destroys green slime (scraping, freezing, burning, cutting, sunlight, or remove disease) destroys this slime. If the slime kills a creature, it consumes the body and then dies. It cannot transfer to a creature other than the original target, and dies if separated from the original target.', 'a drop of acid and a black glass sphere', NULL, false, false),
  ('touch_of_the_sea', 'Touch of the Sea', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bloodrager 1, druid 1, sorcerer/wizard 1; Elemental School water 1; Mystery waves 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'You cause webs to grow between the target’s fingers and its feet to transform into flippers, granting a swim speed of 30 feet along with the standard +8 bonus on Swim checks and the ability to take 10 even if distracted or endangered. You can also use the run action while swimming, provided you swim in a straight line. This transformation causes any boots or gloves the target is wearing to meld into its form (although magic items with a continuous effect continue to function). This spell does not grant the target any ability to breathe water.', 'a fish scale', NULL, false, false),
  ('touch_of_truthtelling', 'Touch of Truthtelling', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, NULL, NULL, NULL, 'This spell functions identically to the spell zone of truth, except as noted above. The target momentarily takes on the semblance of a being of perfect order, like an archon or inevitable, so that all who can see the target know it is affected by the spell. This divine guise flickers over the target for only an instant and does not allow it to pass as a member of a different race.', NULL, NULL, true, false),
  ('tough_crowd', 'Tough Crowd', 'abjuration', NULL, NULL, 3, 'both', 'bard 4, inquisitor 4, mesmerist 4, psychic 3, sorcerer/wizard 4, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', '1 creature/level', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'You fortify your allies against attempts to control or mislead them. Each ally in the spell’s range gains a +4 insight bonus on the saving throw to resist the next enchantment or illusion spell cast on it. In addition, the DC of any Bluff, Diplomacy, Disguise, or Intimidate check to influence an affected character increases by 4 for the duration of the spell.', NULL, NULL, false, false),
  ('tower_of_iron_will_i', 'Tower of Iron Will I', 'abjuration', NULL, NULL, 5, 'arcane', 'psychic 5', '1 immediate action', '10 ft.', NULL, '10-ft.-radius emanation centered on you', NULL, '1 round', 'none', 'yes (harmless)', 'You project a fortress of mental power that blocks out the psychic energy of others, granting mental strength and resiliency to all inside the area. All creatures inside the area gain spell resistance equal to 10 + double this spell’s level against psychic magic and any mind-affecting effects. Creatures inside the area don’t receive this protection against your spells or special abilities.', NULL, NULL, false, false),
  ('toxic_blood', 'Toxic Blood', 'transmutation', NULL, 'poison', 3, 'both', 'alchemist 3, bloodrager 3, cleric 3, druid 3, investigator 3, magus 3, ranger 3, sorcerer/wizard 3, summoner 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates; see text', 'no', 'The target creature’s blood becomes poisonous. Anytime the target takes piercing or slashing damage, a spray of acidic blood spurts from its body in the direction of the opponent who inflicted the wound. This blood travels in a 10-foot line, striking the first creature or object it touches. A creature struck by the blood is exposed to black adder venom and must save against the poison as normal, with a DC equal to the spell’s DC.', 'vial of black adder venom', NULL, false, false),
  ('toxic_gift', 'Toxic Gift', 'necromancy', NULL, 'poison', 2, 'both', 'antipaladin 2, sorcerer/wizard 3', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous; see text', 'Fortitude negates (see text)', 'yes', 'You can cast this spell only if you are currently poisoned. You draw upon the poison in your body and duplicate its effects in the target, which is affected by the same poison you are, except it uses this spell’s DC instead of the poison’s normal DC. If you are affected by more than one poison, you must choose one to afflict upon the target.', NULL, NULL, false, false),
  ('toxic_rupture', 'Toxic Rupture', 'necromancy', NULL, 'poison', 3, 'both', 'druid 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one poisonous creature', NULL, NULL, 'instantaneous', 'Fort negates; see text', 'yes', 'With a squeezing hand gesture, you cause internal bleeding in the target creature’s venom glands or similar organs. The target must attempt a saving throw against its own poison using the DC for this spell. If it fails, the creature is poisoned and suffers the full effect of its poison. Any subsequent saving throws that the target must attempt against the poison use the normal DC for the poison rather than this spell’s DC.', 'a viper’s fang', NULL, true, false),
  ('trace_teleport', 'Trace Teleport', 'divination', NULL, NULL, 4, 'arcane', 'psychic 4, sorcerer/wizard 5', '1 standard action', '40 feet', NULL, '40-ft.-radius emanation centered on you', NULL, '1 minute/level', 'none', 'no', 'You immediately become aware of any teleportation effects that begin or end within the spell’s area. The spell’s area radiates from you and moves as you move. You know the exact origin point of any teleportation effect that originates within the spell’s area, and the exact end point of any teleportation effect that terminates within the spell’s area. Further, you can detect the lingering traces of any teleportation effect that occurred up to 1 hour previously, in the same fashion.', NULL, 'a magnifying lens', false, false),
  ('track_ship', 'Track Ship', 'divination', 'scrying', 'travel', 2, 'both', 'bard 2, cleric 2, sorcerer/wizard 2', '1 standard action', 'see text', NULL, NULL, 'magical icon', '1 hour/level', 'Will negates (object)', 'yes (object)', 'In order to cast this spell, you must have a piece of the ship you wish to track. Merchants often preserve slivers from their trade ships specifically for this purpose. You also need a nautical chart.', NULL, 'piece of ship', false, false),
  ('tracking_mark', 'Tracking Mark', 'evocation', NULL, NULL, 1, 'both', 'bloodrager 1, cleric/oracle 1, druid 1, paladin 1, ranger 1', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '10 minutes/level (D)', 'Will negates', 'yes', 'You gain a supernatural ability to detect tracks and other clues left behind by the target. You treat the DCs of all Survival checks made to track the target as if they were 5 lower than normal, and you gain a +5 bonus on Perception checks made to notice the target if it is using Stealth or recognize it if it is using Disguise.', NULL, NULL, true, false),
  ('trade_items', 'Trade Items', 'conjuration', 'teleportation', NULL, 3, 'arcane', 'bard 3, mesmerist 3, sorcerer/wizard 4, summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one object weighing no more than 5 lbs./level', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You cause the target object and the object used as a focus for the spell to immediately swap places. The target object appears in your hand (or falls to the ground in your square if you are unable to hold it). The stronger the connection between the two objects, the more difficult the spell is to resist, as indicated on the table below. The modifiers are cumulative.', NULL, 'any held object weighing no more than 5 lbs./level', false, false),
  ('trail_of_the_rose', 'Trail of the Rose', 'illusion', 'phantasm', NULL, 2, 'both', 'bard 2, cleric/oracle 2', '1 standard action', 'touch', '1 rose touched', NULL, NULL, '1 hour/level (D)', 'no', 'no', 'This spell creates an illusory trail in the form of a misty and visible scent coming from the rose used as this spell’s material component. When you cast this spell, the scent of the rose leaves a faint pink-tinged illusion that ripples and flows in the area. Only you and up to six creatures you designate upon casting the spell can see the illusion. To designate a creature, you must know it well. It is not enough simply to have met that creature once or heard of the creature. When you move, this illusory scent leaves a trail, though there are no telltale signs of which direction you moved if creatures designated by this spell find a middle section of the trail. This is typically used to create backtracking method for the caster’s handpicked allies, useful for navigating in and out of mazes or labyrinthine cave complexes without leaving behind an obvious trail.', NULL, NULL, false, false),
  ('transfer_familiar', 'Transfer Familiar', 'evocation', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6, witch 6', '1 standard action', 'touch', 'your familiar and one willing creature', NULL, NULL, '1 day/level (D)', 'none', 'no', 'You temporarily grant control of your familiar to another willing creature. You, your familiar, and the target creature must all be touching each other when you cast this spell. The target gains all the benefits and abilities normally associated with having a familiar, including the ability to share spells, speak with the familiar, and so on. You lose all of these benefits for the duration of the spell. If the target already has a familiar, the spell fails.', NULL, NULL, false, false),
  ('transfer_regeneration', 'Transfer Regeneration', 'transmutation', NULL, NULL, 3, 'both', 'cleric 3, druid 3, psychic 3, shaman 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 willing living creature', NULL, NULL, '1 minute', 'none', 'no', 'You bestow your regenerative abilities on the target. Your regeneration stops functioning for the duration of the spell, and the target gains your regeneration. For example, if you have regeneration 5 (acid or fire), your target gains regeneration 5 (acid or fire). This regeneration overlaps (does not stack) with any regeneration the creature already has, including other castings of this spell. This spell has no effect if you don’t have the regeneration ability or your regeneration isn’t functioning when you cast the spell.---', NULL, NULL, false, false),
  ('transfer_tattoo', 'Transfer Tattoo', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one magic tattoo', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'With this spell, you can transfer one magic tattoo from one creature to another. A target that isn’t willing to have his tattoo removed or to receive the transferred tattoo can resist this spell with a Fortitude save—if successful, the transfer fails and the caster of this spell is staggered for 1 round by the backlash of magical energy. A tattoo can be transferred from a dead creature in this manner to a living host, provided the body has been dead no longer than one hour per caster level.', 'tattooing needle', NULL, false, false),
  ('transfiguring_touch', 'Transfiguring Touch', 'transmutation', NULL, NULL, 5, 'arcane', 'alchemist 5, occultist 6, sorcerer/wizard 6', '1 standard action', 'touch', 'object touched, up to 1 cubic foot per level', NULL, NULL, 'instantaneous', 'none', 'no', 'You create an alchemical residue on your hands that gradually converts a touched, unattended, non-magical object into iron, paper, or wood (your choice). The spell converts at most 1 cubic foot of material per caster level you have; if the object is larger than the maximum volume, the transfiguration stops once that amount of matter has been converted. If your caster level is at least 14th, you can opt to create lead. If your caster level is at least 19th, you can opt to create precious metals.', 'alchemical reagents worth 1 gp or the value of the created material, whichever is more', NULL, false, true),
  ('transformation', 'Transformation', 'transmutation', NULL, NULL, 6, 'arcane', 'alchemist 6, magus 6, sorcerer/wizard 6, witch 6; Bloodline abyssal 6, boreal 6', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You become a fighting machine – stronger, tougher, faster, and more skilled in combat. Your mindset changes so that you relish combat and you can’t cast spells, even from magic items.', 'a potion of bull’s strength, which you drink and whose effects are subsumed by the spell effects', NULL, false, false),
  ('transmogrify', 'Transmogrify', 'transmutation', NULL, NULL, 4, 'arcane', 'summoner/unchained summoner 4', '1 hour', 'touch', NULL, NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'no', 'Your eidolon’s form shifts and transforms. This spell allows you to change any of the eidolon’s evolutions by allocating its evolution pool on new evolutions. If you have the aspect or greater aspect ability, this spell also allows you to change the evolution points spent to modify you, including removing or adding points as allowed by those abilities.', 'a flask of quicksilver worth 1,000 gp', NULL, false, true),
  ('transmute_blood_to_acid', 'Transmute Blood to Acid', 'transmutation', NULL, 'acid, pain', 9, 'arcane', 'sorcerer/wizard 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'concentration (maximum 1 round/5 levels)', 'Fortitude half', 'yes', 'You transmute blood in the target’s body to acid, dealing 1d6 points of acid damage/2 levels (maximum 12d6) each round. The creature is staggered and sickened by the debilitating pain. A successful Fortitude save each round halves the damage and negates the staggered condition for 1 round. If this damage reduces the creature to 0 or fewer hit points, it dissolves, leaving only the barest trace of remains. A dissolved creature’s equipment is unaffected. Anyone who strikes the target with a non-reach melee weapon, natural weapon, or unarmed attack takes 3d6 points of acid damage as the acidic blood sprays on the attacker. If the attack is from a piercing or slashing manufactured weapon, the weapon also takes this damage.', 'a wax doll and a vial of acid worth 10 gp', NULL, false, true),
  ('transmute_golem', 'Transmute Golem', 'transmutation', 'polymorph', NULL, 6, 'arcane', 'alchemist 6, sorcerer/wizard 9', '8 hours', 'touch', 'golem touched', NULL, NULL, 'instantaneous', 'none', 'no', 'You turn one type of golem into another. The golem must be willing—it must be commanded to transform by its master or must be a creature able to make informed decisions that opts to submit to the spell. You must provide various powdered metals with a value equal to 150% of the difference in creation costs between the old and new type of golem, even if the new golem type is cheaper to create. Both types of golems must share the same subtypes, if any. You cannot transmute a golem into a new type of golem with a CR higher than your caster level.', 'powdered metals with a variable cost, see text', NULL, false, false),
  ('transmute_metal_to_wood', 'Transmute Metal to Wood', 'transmutation', NULL, NULL, 7, 'arcane', 'druid 7; Elemental School wood 8; Mystery wood 7', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'all metal objects within a 40-ft.-radius burst', NULL, 'instantaneous', 'none', 'yes (object; see text)', 'This spell enables you to change all metal objects within its area to wood. Weapons, armor, and other metal objects carried by creatures are affected as well. A magic object made of metal effectively has Spell Resistance equal to 20 + its caster level against this spell. Artifacts cannot be transmuted. Weapons converted from metal to wood take a -2 penalty on attack and damage rolls. The armor bonus of any armor converted from metal to wood is reduced by 2. Weapons changed by this spell splinter and break on any natural attack roll of 1 or 2, and armor changed by this spell loses an additional point of armor bonus every time it is struck with a natural attack roll of 19 or 20.', NULL, NULL, true, false),
  ('transmute_mud_to_rock', 'Transmute Mud to Rock', 'transmutation', NULL, 'earth', 5, 'both', 'druid 5, sorcerer/wizard 5; Elemental School earth 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'up to two 10-ft. cubes/level (S)', NULL, 'permanent', 'see text', 'no', 'This spell permanently transforms normal mud or quicksand of any depth into soft stone (sandstone or a similar mineral).', 'sand, lime, and water', NULL, true, false),
  ('transmute_potion_to_poison', 'Transmute Potion to Poison', 'transmutation', NULL, 'poison', 2, 'arcane', 'alchemist 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 round then 1 minute/level; see text', NULL, NULL, 'This extract causes you to take on a pale, sickly pallor for 1 round. During this time, if you consume a potion, it has no effect. Instead, your mouth fills with a vile poison that you can spit onto a weapon as a free action. If you do not spit out the poison in 1 round, it affects you instead. The effect of the poison depends on the level of spell contained in the potion consumed (see sidebar). If the poison is not used within 1 minute per caster level it becomes inert. You can only create one dose of poison in this way per casting of this spell.', NULL, NULL, false, false),
  ('transmute_rock_to_mud', 'Transmute Rock to Mud', 'transmutation', NULL, 'earth', 5, 'both', 'druid 5, sorcerer/wizard 5; Elemental School earth 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'up to two 10-ft. cubes/level (S)', NULL, 'permanent; see text', 'see text', 'no', 'This spell turns natural, uncut, or unworked rock of any sort into an equal volume of mud. Magical stone is not affected by the spell. The depth of the mud created cannot exceed 10 feet. A creature unable to levitate, fly, or otherwise free itself from the mud sinks until hip- or chest-deep, reducing its speed to 5 feet and causing a -2 penalty on attack rolls and AC. Brush or similar material thrown atop the mud can support creatures able to climb on top of it. Creatures large enough to walk on the bottom can wade through the area at a speed of 5 feet.', 'clay and water', NULL, true, false),
  ('transmute_wine_to_blood', 'Transmute Wine to Blood', 'transmutation', NULL, NULL, 2, 'both', 'cleric/oracle 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'bottle of wine worth at least 10 gp', NULL, NULL, 'instantaneous', 'Fortitude negates (object)', 'yes (object)', 'You transform one bottle of fine wine into 1 pint of animal blood, sufficient for a creature with the blood drain ability to feed upon as if it came from a Medium animal with 1 Hit Die. If you are using the optional hunger rules, this blood satiates an undead creature’s hunger, negating any withdrawal effects, but does not grant the creature a feeding bonus. The blood coagulates and spoils at the normal rate.', 'drop of animal blood', NULL, false, false),
  ('transplant_visage', 'Transplant Visage', 'transmutation', NULL, 'evil', 4, 'both', 'alchemist 5, antipaladin 4, cleric/oracle 4, inquisitor 4, magus 5, shaman 4, sorcerer/wizard 5, witch 5', '1 round', 'personal', 'you', NULL, NULL, 'permanent', NULL, NULL, 'This spell allows you to add a creature’s stolen face to or remove such a face that you’ve already applied from your own. Before casting this spell, you must remove the face and eyes of a creature that has been dead no longer than 1 minute per caster level and place it over your own. Once you cast transplant visage, the creature’s stolen skin magically melds with your own, making the expressions and eye color on your new face seem perfectly natural. Your new appearance grants you a +10 bonus on Disguise checks. Because the alteration made by transplant visage is permanent, there is no residual magical aura, and your new appearance is not recognized by detect spells. Transplant visage may be cast innumerable times, allowing a single caster to wear layers upon layers of stolen faces. However, only the topmost face is visible at any one time.', 'one corpse', NULL, false, false),
  ('transport_via_plants', 'Transport via Plants', 'conjuration', 'teleportation', NULL, 6, 'divine', 'druid 6, shaman 7', '1 standard action', 'unlimited', 'you and touched objects or other touched willing creatures', NULL, NULL, '1 round', 'none', 'no', 'You can enter any normal plant (equal to your size or larger) and pass any distance to a plant of the same kind in a single round, regardless of the distance separating the two. The plants must be alive. The destination plant need not be familiar to you. If you are uncertain of the location of a particular kind of destination plant, you need merely designate direction and distance and the transport via plants spell moves you as close as possible to the desired location. If a particular destination plant is desired but the plant is not living, the spell fails and you are ejected from the entry plant.', NULL, NULL, false, false),
  ('trap_the_soul', 'Trap the Soul', 'conjuration', 'summoning', NULL, 8, 'arcane', 'sorcerer/wizard 8, witch 8; Subdomain psychopomp (death, repose) 8, souls 9; Mystery juju(PAP39/PZO9039) 8', '1 standard action or see text', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent; see text', 'see text', 'yes; see text', 'Trap the soul forces a creature’s life force (and its material body) into a gem. The gem holds the trapped entity indefinitely or until the gem is broken and the life force is released, which allows the material body to reform. If the trapped creature is a powerful creature from another plane, it can be required to perform a service immediately upon being freed. Otherwise, the creature can go free once the gem imprisoning it is broken.', 'gem worth 1,000 gp per HD of the trapped creature', NULL, false, true),
  ('trap_ward', 'Trap Ward', 'abjuration', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level or until discharged', NULL, NULL, 'The protection provided by this spell comes into play whenever the caster is subjected to the effects of a magical trap.', 'masterwork thieves’ tools worth 100 gp', NULL, false, true),
  ('trapfinder_s_focus', 'Trapfinder’s Focus', 'divination', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'If you don’t have the trapfinding class ability, this spell grants you the trapfinding ability of a rogue of half your character level.', NULL, 'masterwork thieves’ tools worth 100 gp', false, true),
  ('traveling_dream', 'Traveling Dream', 'divination', 'scrying', NULL, 4, 'divine', 'cleric/oracle 4, druid 4', NULL, NULL, NULL, NULL, NULL, '1 hour/level (D)', NULL, NULL, 'This spell functions like arcane eye, except as noted above.', NULL, NULL, true, false),
  ('treacherous_teleport', 'Treacherous Teleport', 'conjuration', 'teleportation', 'ruse', 6, 'arcane', 'magus 6, occultist 6, psychic 6, sorcerer/wizard 6, spiritualist 6, summoner 6, witch 6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as teleport except that you can opt to intentionally cause any number of the creatures traveling with you to suffer a mishap or arrive in a specific different location you visualize simultaneously with the original destination, or both.', NULL, NULL, false, false),
  ('treasure_stitching', 'Treasure Stitching', 'transmutation', NULL, NULL, 4, 'both', 'bard 4, cleric/oracle 5, sorcerer/wizard 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 day/level (D)', 'Fortitude negates (object)', 'yes (object)', 'You can transform all objects placed on a cloth into an embroidered, two-dimensional representation, making it easy for you to store and transport the items. You can pile any amount or weight of objects on the cloth so long as the pile stays within the dimensions of the cloth (up to a 10-foot cube).', 'a piece of embroidered cloth no larger than 10-ft. square worth 100 gp', NULL, false, true),
  ('tree_shape', 'Tree Shape', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, ranger 3, shaman 2; Elemental School wood 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'This spell allows you to assume the form of a Large living tree or shrub or a Large dead tree trunk with a small number of limbs. The exact type of tree, as well as its appearance, is completely under your control. Even the closest inspection cannot reveal that the tree in question is actually a magically concealed creature. To all normal tests you are, in fact, a tree or shrub, although a detect magic spell reveals a faint transmutation on the tree. While in tree form, you can observe all that transpires around you just as if you were in your normal form, and your hit points and save bonuses remain unaffected. You gain a +10 natural armor bonus to AC but have an effective Dexterity score of 0 and a speed of 0 feet. You are immune to critical hits while in tree form. All clothing and gear carried or worn changes with you. You can dismiss tree shape as a free action (instead of as a standard action).', NULL, NULL, true, false),
  ('tree_stride', 'Tree Stride', 'conjuration', 'teleportation', NULL, 5, 'divine', 'druid 5, ranger 4; Bloodline fey 5; Elemental School wood 6; Mystery wood 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level or until expended; see text', NULL, NULL, 'When you cast this spell, you gain the ability to step into a tree, magically infusing yourself with the plant. Once within a tree, you can teleport from that particular tree to another tree. The trees you enter must be of the same kind, must be living, and must have girth at least equal to yours. By moving into an oak tree (for example), you instantly know the location of all other oak trees within transport range (see below) and may choose whether you want to pass into one or simply step back out of the tree you moved into. You may choose to pass to any tree of the appropriate kind within the transport range as shown on the following table.', NULL, NULL, true, false),
  ('tremor_blast', 'Tremor Blast', 'transmutation', NULL, NULL, 2, 'both', 'adept 2, bloodrager 2, cleric/oracle 2, inquisitor 2, sorcerer/wizard 2, witch 2', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'none', 'yes', 'You create a minor earthquake that can trip creatures. Attempt a single combat maneuver check and apply the result against the CMD of every creature in the area. If your roll equals or exceeds a creature’s CMD, that creature is knocked prone. This trip attack does not provoke an attack of opportunity (though you do provoke one for casting the spell), nor are you knocked prone if you fail the check by 10 or more. Unlike with a regular trip attack, you can trip any creature touching the ground, regardless of size. Improved Trip does not affect this spell in any way. Though the earthquake is small and focused on the ground, if the area is particularly unstable, the spell might cause items to topple, stones to shake loose from the walls or ceiling, and so on at the GM’s discretion.', NULL, NULL, false, false),
  ('trial_by_fire', 'Trial By Fire', 'evocation', NULL, 'fire', 3, 'divine', 'antipaladin 3, cleric 3, inquisitor 3, paladin 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'None', 'yes', 'You test a creature’s purity of convictions by exposing it to a sheet of divine fire. Unless the target’s alignment is within one step of your deity’s, the spell deals 1d6 points of damage per 2 caster levels (maximum 5d6 points of damage). Half the damage is fire damage, but the other half results directly from divine power and is therefore not subject to being reduced by resistance to fire-based attacks. Additionally, if the target has an element of its alignment that is in direct opposition to your (chaos opposes law and evil opposes good), you can also attempt an Intimidate check to demoralize the target as a free action.', NULL, NULL, true, false),
  ('trial_of_fire_and_acid', 'Trial of Fire and Acid', 'evocation', NULL, 'acid, fire', 3, 'both', 'bloodrager 3, cleric 3, magus 3, shaman 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fortitude half (see text)', 'no', 'The target creature is covered in burning acid that deals 1d6 points of acid damage and 1d6 points of fire damage each round.', NULL, NULL, false, false),
  ('triggered_hallucination', 'Triggered Hallucination', 'illusion', 'phantasm', 'mind-affecting', 6, 'arcane', 'bard 6, magus 6, mesmerist 6, occultist 6, psychic 6, sorcerer/wizard 6', NULL, NULL, 'one creature', NULL, NULL, 'permanent until triggered, then 1 minute/level', NULL, NULL, 'This spell functions as audiovisual hallucination, except that this spell’s phantasm has no apparent effect until a specific condition occurs. You must overcome the target’s spell resistance to plant the triggered hallucination, but the target doesn’t attempt a Will save to disbelieve the illusion until the condition occurs (at which point it receives an automatic Will save, as with audiovisual hallucination). The phantasm can include auditory, olfactory, visual, tactile, and thermal elements, including intelligible speech.', 'jade dust worth 25 gp', NULL, false, true),
  ('triggered_suggestion', 'Triggered Suggestion', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 4, witch 4 Duration 1 day/level or until completed', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as suggestion, except you can use it only to specify a condition that triggers a special activity, and the subject does not remember that you made the suggestion. For example, you could use triggered suggestion on a palace guard to make him attack the king the next time he and the king are alone, and the guard would not remember the suggestion to do so until the trigger occurred.', NULL, NULL, false, false),
  ('tripvine', 'Tripvine', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, druid 1, sorcerer/wizard 1', '1 standard action', 'touch', '10-foot-long rope or vine', NULL, NULL, '10 minutes/level', 'Reflex negates', 'no', 'You animate a rope, vine, or similar object so that it attempts to trip any creature that comes near. The rope attacks anything in a 10-foot-square area you designate. The rope does not provoke an attack of opportunity. Its CMB is equal to your caster level +2. A tripped target that was running, jumping, or charging takes 1d6 points of nonlethal damage. Creatures aware of the tripvine gain a +4 bonus to their CMD against it.', NULL, NULL, false, false),
  ('true_appraisal', 'True Appraisal', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, occultist 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '8 hours', 'none', 'no', 'You gain temporary insight into the value of objects. You gain a +5 competence bonus on Appraise checks, can attempt an Appraise check to determine an object’s value as a move action, and can take 10 on an Appraise check even if stress or distractions would normally prevent you from doing so. You know if you fail an Appraise check, and you never determine a wildly inaccurate price.', NULL, 'gold coin', false, false),
  ('true_creation', 'True Creation', 'conjuration', 'creation', NULL, 8, 'arcane', 'artifice 8', '10 minutes', '0 ft.', NULL, NULL, 'unattended, nonmagical object, up to 1 cu. ft/level', 'instantaneous', 'none', 'no', 'You create a completely real, nonmagical, unattended object of any sort of matter. The volume of the item created cannot exceed 1 cubic foot per caster level. Complex items require successful Craft checks. Objects created can be used as material components.', '5 x item value in misc. components', NULL, false, false),
  ('true_form', 'True Form', 'abjuration', NULL, NULL, 4, 'both', 'druid 4, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'True form removes any polymorph effect from a target creature, returning it to its true form, even against its will. Against creatures affected by polymorph spell effects (such as baleful polymorph or giant form), you must make a caster level check (1d20 + caster level, maximum +15) against a DC of 11 + caster level of the effect. Success means that the polymorph immediately ends.', NULL, NULL, false, false),
  ('true_prognostication', 'True Prognostication', 'divination', NULL, NULL, 8, 'both', 'cleric 8, psychic 8, shaman 8, witch 8', '1 week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'True prognostication functions as divination except that the spell can see up to 100 years into the future. Because of the extreme unpredictability of the far-distant future, true prognostication is incredibly cryptic when used to learn about events on such large a scale.', 'rare incense and tonics worth 1,000 gp', NULL, false, true),
  ('true_resurrection', 'True Resurrection', 'conjuration', 'healing', NULL, 9, 'divine', 'cleric/oracle 9; Subdomain resurrection 9; Mystery life 9', '10 minutes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like raise dead, except that you can resurrect a creature that has been dead for as long as 10 years per caster level. This spell can even bring back creatures whose bodies have been destroyed, provided that you unambiguously identify the deceased in some fashion (reciting the deceased’s time and place of birth or death is the most common method).', NULL, NULL, true, true),
  ('true_seeing', 'True Seeing', 'divination', NULL, NULL, 5, 'both', 'alchemist 6, cleric/oracle 5, druid 7, inquisitor 5, magus 6, shaman 5, sorcerer/wizard 6, summoner 5, unchained summoner 6, witch 6; Domain knowledge 5; Subdomain revelation 5; Bloodline arcane 6; Elemental School void 6; Mystery dragon 7, intrigue 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'You confer on the subject the ability to see all things as they actually are. The subject sees through normal and magical darkness, notices secret doors hidden by magic, sees the exact locations of creatures or objects under blur or displacement effects, sees invisible creatures or objects normally, sees through illusions, and sees the true form of polymorphed, changed, or transmuted things. Further, the subject can focus its vision to see into the Ethereal Plane (but not into extra-dimensional spaces). The range of true seeing conferred is 120 feet.', 'an eye ointment that costs 250 gp', NULL, false, true),
  ('true_skill', 'True Skill', 'divination', NULL, NULL, 1, 'arcane', 'alchemist 1, bard 1, magus 1, medium 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'When faced with an important situation, you grant yourself a magical edge to ensure your success. When casting this spell, select one skill for which you can attempt a skill check. The next time you attempt a skill check using the selected skill (before the spell’s duration ends), you gain an insight bonus on the check equal to 1/2 your caster level (minimum 1).', NULL, NULL, false, false),
  ('true_strike', 'True Strike', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, bloodrager 1, inquisitor 1, magus 1, psychic 1, sorcerer/wizard 1; Domain destruction 1, luck 1; Subdomain fist 1; Bloodline astral 1; Elemental School void 1', '1 standard action', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'You gain temporary, intuitive insight into the immediate future during your next attack. Your next single attack roll (if it is made before the end of the next round) gains a +20 insight bonus. Additionally, you are not affected by the miss chance that applies to attackers trying to strike a concealed target.', NULL, 'small wooden replica of an archery target', false, false),
  ('truespeak', 'Truespeak', 'divination', NULL, NULL, 4, 'both', 'bard 4, cleric 6, sorcerer/wizard 5, witch 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You can communicate with any creature that is not mindless. As long as you can be heard, your speech is understandable to all creatures, each of which hears you as though you were conversing in its language or other natural mode of communication, and you hear their responses as though in your own native language. You may ask questions and receive answers, though this spell does not make creatures more friendly or cooperative than normal, and non-sentient creatures may give limited responses. While using truespeak, your language-dependent effects can affect any creature that is not mindless.', NULL, NULL, false, false),
  ('tsunami', 'Tsunami', 'conjuration', 'creation', 'water', 9, 'both', 'druid 9, shaman 9, sorcerer/wizard 9; Subdomain oceans 9; Elemental School water 9; Mystery waves 9', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, '10-ft.-deep wave 10 ft. wide/level and 2 ft. tall/level', '5 rounds', 'see text', 'no', 'You create a massive wave of water that then moves in a straight line across water or land-you select the direction the wave travels (which must be perpendicular to its width), but once set in motion, the wave cannot change course. Over the surface of open water, the wave travels at a speed of 60 feet per round-on land or underwater, the wave travels at a speed of 30 feet per round.', NULL, NULL, false, false),
  ('twilight_haze', 'Twilight Haze', 'illusion', 'shadow', 'darkness, shadow', 2, 'arcane', 'mesmerist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'fog spreads in 20-ft. radius', '1 round/level', 'none', 'no', 'You create a gray haze that obscures sight (as fog cloud) and causes the illumination level within it to drop one step (as darkness). Since this spell produces an illusion rather than a true physical fog, it is unaffected by wind and can be cast underwater.', NULL, NULL, false, false),
  ('twilight_knife', 'Twilight Knife', 'evocation', NULL, 'force', 3, 'arcane', 'bloodrager 3,  occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, witch 3; Elemental School void 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'floating knife of force', '1 round/level (D)', 'none', 'yes', 'You create a darkly sinister floating knife that attacks the same creature as you each round. If you choose not to attack a creature, or you make an attack that affects multiple opponents, the knife makes no attack during that round.', NULL, 'a small knife', false, false),
  ('twin_form', 'Twin Form', 'transmutation', NULL, NULL, 6, 'arcane', 'alchemist 6', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level or until discharged (D)', NULL, NULL, 'This extract splits a perfect double of yourself from your body, dressed and equipped exactly as you are. You are able to shift your consciousness from one body to the other once each round as a free action. This shift takes place either immediately before your turn or immediately after it, but not during the round. You may act normally in the body you inhabit. Your other self is treated as though dazed, except it may take a single move action each round during your turn. Your twin cannot speak while you are in your other body, and cannot flank, make attacks of opportunity, or otherwise threaten enemies.', 'a blend of soil and the caster’s blood', NULL, false, false),
  ('twine_double', 'Twine Double', 'illusion', 'shadow', NULL, 3, 'arcane', 'sorcerer/wizard 3', '10 minutes', '0 ft.', NULL, NULL, 'one duplicate creature', '1 minute/level (D)', 'none', 'no', 'As simulacrum, except you can only duplicate yourself, and the duplicate is created from cloth and twine rather than ice and snow. The double looks exactly like you except its eyes are balls of twine (DC 10 Perception check to recognize double’s strange eyes). It wears clothing and gear that appear exactly like what you are wearing at the time of casting. Its copies of your magic items are nonfunctional but radiate magic and have the same auras as your items. Its aura is identical to yours. Attempts to scry you while the double exists have a 50% chance of targeting the double instead of you.', 'cloth and twine', NULL, false, false),
  ('twisted_futures', 'Twisted Futures', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 2, druid 1, shaman 1, sorcerer/wizard 2, witch 1', '1 standard action', 'close (25 ft. + 5ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'By rearranging the threads of fate, you disrupt fortunate outcomes for other creatures. A creature affected by this spell is unable to benefit from effects that grant the ability to roll multiple times and take the higher result (like the swashbuckler’s charmed life ability) or to choose the die result in lieu of rolling (like the wizard’s prescience school power or the cyclops’s flash of insight ability). This doesn’t affect abilities that force a creature to take the lower of two rolls, such as ill omen or a pugwampi’s unluck aura. A cyclops can’t use its flash of insight ability to save against this spell.', 'a small die with the faces scratched off', NULL, false, false),
  ('twisted_innards', 'Twisted Innards', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, magus 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'For the duration of this spell, your vital organs writhe, shift, and move about, making it difficult to strike you in a vulnerable area. While this spell is in effect, critical hits and sneak attacks against you have a 25% chance of failing to inflict any additional damage—though you still take the normal damage from the attack. At 7th level, the chance to ignore additional damage increases to 50%, while at 13th level the chance increases to 75%.', 'a cocoon tied with string', NULL, false, false),
  ('twisted_space', 'Twisted Space', 'transmutation', NULL, NULL, 2, 'arcane', 'magus 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'You distort the space around a creature, twisting the path of its melee attacks unpredictably, but always toward a nearby creature that the target threatens. Until the start of your next turn, melee attacks made by the target creature affect a random target instead of their intended target.', 'a length of wire bent into a circle', NULL, false, false),
  ('umbral_infusion', 'Umbral Infusion', 'necromancy', NULL, 'shadow', 4, 'both', 'alchemist 4, antipaladin 4, cleric 4, occultist 4, psychic 4, shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one mindless undead creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You infuse the target mindless undead creature with power drawn from the Shadow Plane, immediately granting it the advanced creature simple template. It gains a +2 bonus on all rolls, including damage rolls, a +2 bonus to special ability DCs, a +4 bonus to AC and CMD, and 2 additional hit points per Hit Die. The undead creature’s destructive instincts take hold for the duration of this spell, and any attempts to control or command the undead creature have a 50% chance of failing; if uncontrolled, the undead creature attacks any living creatures it sees.', NULL, NULL, false, false),
  ('umbral_strike', 'Umbral Strike', 'necromancy', 'shadow', 'darkness', 6, 'both', 'cleric 7, druid 7, inquisitor 6, magus 6, occultist 6, psychic 7, shaman 7, sorcerer/wizard 7, spiritualist 6, witch 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', '1 creature', NULL, NULL, '1 round/level', 'Fortitude partial', 'yes', 'You create a bolt of dark energy and use it to make a ranged touch attack that ignores concealment (but not total concealment).', 'a black crossbow bolt', NULL, false, false),
  ('umbral_weapon', 'Umbral Weapon', 'illusion', NULL, 'cold, shadow', 2, 'both', 'antipaladin 2, bard 2, magus 2, sorcerer/wizard 2, witch 2', NULL, 'touch', 'melee weapon touched', NULL, NULL, '1 round/level', 'none', 'yes', 'A shadowy afterimage trails behind the targeted weapon, potentially damaging foes even when the weapon misses.', 'a pair of miniature swords', NULL, false, false),
  ('unadulterated_loathing', 'Unadulterated Loathing', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'both', 'antipaladin 2, bard 2, mesmerist 2, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You fill the target with a terrible loathing aimed at a specific creature. At the time of the casting, you designate a single creature as the object of the target’s revulsion. Thereafter, the target does all it can to remain at least 60 feet away from the object of its loathing. As soon as the target moves within this range, it becomes nauseated until it can again get away from the object of its revulsion. If traveling beyond 60 feet of the object of its loathing would place the target in obvious physical danger, the target can attempt a second save to break the spell’s effect.', NULL, NULL, false, false),
  ('unbearable_brightness', 'Unbearable Brightness', 'evocation', NULL, 'light', 4, 'arcane', 'alchemist 4, sorcerer/wizard 4, witch 4', '1 standard action', 'personal and 30 ft. (see text)', NULL, '30-ft.-radius emanation centered on you', NULL, '1 round/level', 'none and Reflex partial (see text)', 'no and yes (see text)', 'Your body glows with a terrible light. Creatures within 30 feet of you that can see you are dazzled (no saving throw). Creatures with light sensitivity must succeed at a Reflex saving throw or be blinded. This light counts as daylight for the purpose of affecting darkness effects (and vice versa). If the emanation enters an area under the effect of magical darkness (or vice versa), both effects are temporarily negated so that the otherwise prevailing light conditions exist in the overlapping areas of effect. Dazzled and blinded conditions from your light end when the spell ends or when the creature is out of line of sight.', NULL, NULL, false, false),
  ('unbreakable_construct', 'Unbreakable Construct', 'abjuration', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5; Elemental School metal 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one construct', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'no', 'This spell increases the target’s DR/adamantine by 5 or its hardness by 5. If the target does not have DR/adamantine or hardness, this spell has no effect.', 'powdered adamantine worth 100 gp', NULL, false, true),
  ('unbreakable_heart', 'Unbreakable Heart', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'bard 1, cleric/oracle 1, paladin 1, ranger 1, shaman 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '1 creature', '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The target creature gains a +4 morale bonus on saving throws against mind-affecting effects that rely on negative emotions (such as crushing despair, rage, or fear effects) or that would force him to harm an ally (such as confusion). If the target is already under such an effect when receiving this spell, that effect is suppressed for the duration of this spell. It does not affect mind-affecting effects based on positive emotions (such as good hope or the inspire courage bard ability). A creature can still be charmed or otherwise magically controlled while under this spell’s effects, but if such a creature ever receives a new saving throw against that effect as a result of being ordered to attempt to harm or otherwise oppose a true ally, he can roll that saving throw twice and take the better result as his actual roll.', NULL, NULL, false, false),
  ('uncanny_reminder', 'Uncanny Reminder', 'conjuration', NULL, NULL, 6, 'arcane', 'mesmerist 6, psychic 8, spiritualist 6, summoner 6, wizard/sorcerer 8', '1 round', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell creates an animated replica of the target drawn from the target’s subconscious. This living memory is an animated form of the target’s negative thoughts and emotions and is intent on destroying the target entirely. The living memory appears to be an exact replica of the target creature, but upon inspection it is obviously a construct. It uses the statistics of a clockwork angel except that it has an Intelligence of 10 and does not have the clockwork trait, the enhance weapon ability, or vulnerability to electricity. If the living memory is destroyed, it vanishes entirely, including any replicas of equipment.', NULL, NULL, false, false),
  ('unconscious_agenda', 'Unconscious Agenda', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 6, 'both', 'bard 6, inquisitor 6, sorcerer/wizard 6, witch 6', '10 minutes', 'Close (25 ft. + 5 ft./2 levels)', 'One humanoid', NULL, NULL, 'One week/level or until discharged (D)', 'Will negates', 'yes', 'This spell plants a subconscious directive in the target’s mind that forces him to act as you dictate when specific circumstances arise. The target humanoid can be either conscious or unconscious, but must understand your language. Upon casting this spell, you must state a course of action you wish the target to take. This course of action must be described in 20 words or fewer. You must then state the condition under which you wish the target to take this action, also describing it in 20 or fewer words. Actions or conditions more elaborate than 20 words cause the spell to fail. Unconscious agenda cannot compel a target to kill himself, though it can compel him to perform exceedingly dangerous acts, face impossible odds, or undertake almost any other course of activity. You cannot issue new commands to the target after the spell is cast.', NULL, NULL, false, false),
  ('undead_anatomy', 'Undead Anatomy', 'transmutation', 'polymorph', NULL, 3, 'arcane', 'alchemist 3, bloodrager 3, magus 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'When you cast this spell, you can assume the form of any Small or Medium corporeal creature of the undead type, which must be vaguely humanoid-shaped (like a ghoul, skeleton, or zombie). You gain a bite attack (1d6 for Medium forms, 1d4 for Small forms), two claw or slam attacks (1d6 for Medium forms, 1d4 for Small forms), and darkvision 60 feet. If the form you assume has any of the following abilities, you gain the listed ability: climb 30 feet, fly 30 feet (average maneuverability), swim 30 feet, low-light vision, and scent.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('undead_beacon', 'Undead Beacon', 'necromancy', 'haunted', 'emotion, evil, fear, mind-affecting', 2, 'divine', 'antipaladin 2, cleric 2, inquisitor 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You shroud an area in unclean influence, rendering those who pass through it and fail their Will saving throws more enticing to ravenous undead. When an affected creature comes within 60 feet of an undead creature, the spell immediately draws the undead creature’s attention, granting it a +4 bonus on Perception checks to notice the affected creature and on saving throws to resist spells that hide or disguise the affected creature (such as hide from undead). Once the undead creature notices the affected creature, it feels compelled to kill and devour the affected creature, and gains a +1 profane bonus on attack rolls made against the affected creature and a +1 profane bonus on saving throws against the affected creature’s spells and special abilities. The undead also ignores any concealment less than total concealment that an affected creature has. Each time the spell draws an undead creature’s attention to an affected creature, the spell’s haunt-like manifestation occurs during that round.', NULL, NULL, true, false),
  ('undeath_inversion', 'Undeath Inversion', 'necromancy', NULL, NULL, 4, 'both', 'cleric/oracle 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one undead creature', NULL, NULL, '1 round/level (D); see text', 'Will negates; see text', 'yes', 'You alter an undead creature’s energy affinity so that it takes damage from negative energy and gains healing from positive energy, as if it were a living creature. If the target was able to channel negative energy or produce negative energy effects (such as inflict spells), these abilities produce positive energy instead, healing living targets and harming the undead. The target cannot impose negative levels on other creatures for the duration of the spell. The target’s creature type does not change, and it is still considered an undead creature. Each round on its turn, the subject may attempt a new saving throw to end the effect. This is a full-round action that does not provoke attacks of opportunity.', NULL, NULL, true, false),
  ('undeath_sense', 'Undeath Sense', 'divination', NULL, NULL, 2, 'both', 'alchemist 2, cleric 2, inquisitor 2, paladin 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level (D)', 'none', 'no', 'You grant the target the ability to pick up on the subtle scents and disturbances to the natural order that are specific to the living dead, granting the target the ability to sense the presence of undead creatures. The target is constantly aware of whether there are any undead auras within 60 feet of her in any direction. If at least one undead aura is present, the target can concentrate on the spell’s effects in order to gain more information on the auras present. This functions similarly to detect undead, except the number of rounds of concentration needed to learn about the undead auras is reduced by 1 (1 round to learn the number of auras, and 2 rounds to learn the strength and location of each aura).', 'ashes from an urn', NULL, true, false),
  ('undeath_to_death', 'Undeath to Death', 'necromancy', NULL, NULL, 6, 'both', 'cleric/oracle 6, inquisitor 6, sorcerer/wizard 6; Domain glory 6, repose 6; Mystery reaper 6', NULL, NULL, NULL, 'several undead creatures within a 40-ft.-radius burst', NULL, NULL, 'Will negates', NULL, 'This spell functions like circle of death, except that it destroys undead creatures as noted above.', NULL, NULL, false, false),
  ('undeath_ward', 'Undeath Ward', 'abjuration', NULL, NULL, 4, 'both', 'cleric 5, inquisitor 4, sorcerer/wizard 6, witch 6', '1 standard action', '10 ft.', NULL, '10-ft.-radius emanation, centered on you', NULL, '1 minute/level (D)', 'none or Will negates (see text)', 'yes', 'You create a pale silver barrier that repels undead.', 'powdered silver', NULL, true, false),
  ('underbrush_decoy', 'Underbrush Decoy', 'transmutation', NULL, NULL, 1, 'divine', 'druid 1, ranger 1, shaman 1', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one non-creature plant of size Tiny, Small, or Medium', NULL, NULL, '1 round', 'Will negates (object)', 'yes (object)', 'You cause a plant to rustle noisily, distracting nearby creatures.', NULL, NULL, false, false),
  ('undetectable_alignment', 'Undetectable Alignment', 'abjuration', NULL, NULL, 1, 'both', 'alchemist 2, antipaladin 2, bard 1, cleric/oracle 2, inquisitor 2, mesmerist 1, paladin 2, psychic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object', NULL, NULL, '24 hours', 'Will negates (object)', 'yes (object)', 'An undetectable alignment spell conceals the alignment of an object or a creature from all forms of divination.', NULL, NULL, false, false),
  ('undetectable_trap', 'Undetectable Trap', 'illusion', 'glamer', NULL, 2, 'divine', 'antipaladin 2, occultist 3, ranger 2', '10 minutes (see text)', 'touch', 'trap touched', NULL, NULL, '1 day/level (D)', 'none', 'no', 'You shroud a single trap with a powerful illusion to make it more difficult to locate. Spells like detect magic can’t locate any magic aura from either the target trap or from undetectable trap. Furthermore, a character under the effect of the find traps spell doesn’t receive an automatic chance to locate the target trap when she comes within 10 feet of it, and the bonus on Perception checks from find traps doesn’t apply to attempts to notice the target trap. Add 1/2 your caster level to the DC for any creature without the trapfinding class ability to notice the target trap with Perception checks.', 'a square of black silk worth 50 gp', NULL, false, true),
  ('undine_s_curse', 'Undine’s Curse', 'necromancy', NULL, 'curse, evil', 1, 'arcane', 'sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'The target loses its body’s natural ability to breathe automatically. As long as it remains conscious and is able to take physical actions, it keeps breathing and is able to function normally. If it is ever unconscious (including sleeping) or unable to take physical actions, it stops breathing, must hold its breath, and might begin to suffocate.. Creatures that do not have to breathe are immune to this spell.', NULL, NULL, false, false),
  ('unerring_tracker', 'Unerring Tracker', 'divination', NULL, NULL, 4, 'both', 'alchemist 5, druid 6, occultist 4, ranger 4', '10 minutes', 'personal', 'you', NULL, NULL, '10 minutes/level', 'none', 'no', 'During this spell’s duration, you can touch the sign of a creature’s passage that you have identified using the Survival skill to make the other steps in the creature’s path perfectly clear to you, no matter how minute. This trail can’t be more than 24 hours old. You can follow the trail at any speed, provided you have line of sight to the trail. You can distinguish the trail of the particular creature followed even if it joins and splits with other trails. Once you have selected a trail to follow using this spell, it can’t be changed.', NULL, NULL, true, false),
  ('unerring_weapon', 'Unerring Weapon', 'transmutation', NULL, NULL, 1, 'both', 'bloodrager 1, inquisitor 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'This spell causes a weapon to veer closer to vital areas, improving the result of a critical threat. This transmutation grants a +2 bonus on attack rolls to confirm critical hits plus 1 additional bonus point per four caster levels (maximum total bonus +7). If the spell is cast on projectiles, the effect ends on a specific projectile whenever that projectile is used to make an attack, regardless of whether the attack hits. For this spell, shuriken are considered projectiles.', NULL, NULL, false, false),
  ('unfetter', 'Unfetter', 'transmutation', NULL, NULL, 1, 'arcane', 'summoner/unchained summoner 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'no', 'This spell breaks the life link between you and your eidolon. This spell allows your eidolon to venture more than 100 feet away from you without penalty. It can travel any distance while this spell is in effect without penalty, but if the spell expires while the eidolon is farther than 100 feet away, it immediately loses hit points as normal for distance and is possibly sent back to its home plane. While this spell is in effect, you cannot sacrifice hit points to prevent damage to your eidolon. Damage that would be transferred due to the life bond ability is not transferred. If you attempt to use the transposition ability while this spell is in effect, you must roll on the teleport mishap table, using the “studied carefully” row.', 'a broken chain', NULL, false, false),
  ('unflappable_mien', 'Unflappable Mien', 'evocation', NULL, 'force', 3, 'arcane', 'bard 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level or until discharged; see text', NULL, NULL, 'When a creature attempts to touch you with an attack (such as a touch attack, an unarmed strike, an attack with a natural weapon, or a grapple), it feels a field of force blocking its way. It can choose to abandon the attempt, losing its action, or to push through the ward. If it pushes through, you can trigger a wave of force against that creature. This discharges the spell, deals 1d4 points of force damage per caster level (maximum 10d4), and pushes the creature back 5 feet. If the creature cannot be pushed back 5 feet (if a solid surface is directly behind it, for example), it takes 2d4 additional points of force damage. A successful Fortitude saving throw halves the total amount of force damage the creature takes.', NULL, 'a diamond clasp, brooch, or pin worth at least 100 gp', false, true),
  ('unhallow', 'Unhallow', 'evocation', NULL, 'evil', 5, 'divine', 'cleric/oracle 5, druid 5, inquisitor 5', '24 hours', 'touch', NULL, '40-ft. radius emanating from the touched point', NULL, 'instantaneous', 'see text', 'see text', 'Unhallow makes a particular site, building, or structure an unholy site. This has three major effects.', 'herbs, oils, and incense worth at least 1,000 gp, plus 1,000 gp per level of the spell to be tied to the unhallowed area', NULL, false, true),
  ('unhallowed_blows', 'Unhallowed Blows', 'transmutation', NULL, 'evil', 1, 'both', 'antipaladin 1, cleric 1, inquisitor 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one undead creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'This spell empowers the natural attacks or unarmed strikes of undead creatures, granting a +1 enhancement bonus on attack and damage rolls made by the target with its unarmed strikes or attacks with one natural attack. This spell can cause an undead creature’s unarmed strike to deal lethal damage, but in this case, the attack does not gain an enhancement bonus.', 'a pinch of dust from a destroyed undead creature', NULL, true, false),
  ('unholy_aura', 'Unholy Aura', 'abjuration', NULL, 'evil', 8, 'divine', 'cleric/oracle 8; Domain evil 8; Bloodline abyssal 8, ghoul 8', '1 standard action', '20 ft.', NULL, NULL, NULL, '1 round/level (D)', 'see text', 'yes (harmless)', 'A malevolent darkness surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by good creatures, and weakening good creatures when they strike the subjects. This abjuration has four effects:', NULL, 'a tiny reliquary worth 500 gp', false, true),
  ('unholy_blight', 'Unholy Blight', 'evocation', NULL, 'evil', 4, 'divine', 'cleric/oracle 4, inquisitor 4; Domain evil 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius spread', NULL, 'instantaneous (1d4 rounds); see text', 'Will partial', 'yes', 'You call up unholy power to smite your enemies. The power takes the form of a cold, cloying miasma of greasy darkness. Only good and neutral (not evil) creatures are harmed by the spell.', NULL, NULL, false, false),
  ('unholy_ice', 'Unholy Ice', 'transmutation', NULL, 'cold, evil, water', 5, 'divine', 'cleric/oracle 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as holy ice, except it is made of frozen unholy water rather than holy water.', 'a flask of unholy water or 5 pounds of powdered silver worth 25 gp', NULL, false, true),
  ('unholy_ice_weapon', 'Unholy Ice Weapon', 'transmutation', NULL, 'cold, evil, water', 2, 'divine', 'cleric 2, inquisitor 2 Components V, S, M (a flask of unholy water or 5 pounds of powdered silver worth 25 gp)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as holy ice weapon, except the weapon is made of frozen unholy water, and instead deals additional damage to creatures that are susceptible to unholy water.', NULL, NULL, false, false),
  ('unholy_sword', 'Unholy Sword', 'evocation', NULL, 'evil', 4, 'divine', 'antipaladin 4', '1 standard action', 'touch', 'melee weapon touched', NULL, NULL, '1 round/level', 'none', 'no', 'This spell allows you to channel the powers of evil into your sword, or any other melee weapon you choose. The weapon acts as a +5 unholy weapon (+5 enhancement bonus on attack and damage rolls, extra 2d6 damage against good opponents). It also emits a magic circle against good effect (as the spell). If the magic circle ends, the sword creates a new one on your turn as a free action. The spell is automatically canceled 1 round after the weapon leaves your hand. You cannot have more than one unholy sword at a time.', NULL, NULL, false, false),
  ('unholy_ward', 'Unholy Ward', 'abjuration', NULL, 'evil', 3, 'both', 'antipaladin 3, cleric 4, inquisitor 3, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', 'Fort negates (harmless)', 'yes (harmless)', 'This spell grants you resistance to the holy powers of good-aligned deities and their servants. You resist 10 points of damage from holy sources (divine power damage from flame strike, additional damage from smite evil, channeled positive energy, etc.), provided they originate from a good-aligned source or a servant of a good-aligned god. You ignore a maximum of 10 points of damage per caster level, at which point the spell ends.', NULL, NULL, true, false),
  ('universal_formula', 'Universal Formula', 'transmutation', NULL, NULL, 4, 'arcane', 'alchemist 4', '1 standard action', 'personal', NULL, NULL, NULL, 'instantaneous', NULL, NULL, 'As you ingest this extract, it transforms into the appropriate extract for any formula you know of 3rd level or lower and takes effect immediately. If the chosen formula has an expensive material component, it must be provided along with the component for this formula. You may not create an infused extract with this formula.', 'quicksilver and powdered platinum worth 100 gp', NULL, false, true),
  ('unlife_current', 'Unlife Current', 'conjuration', 'healing', 'water', 3, 'divine', 'antipaladin 3, cleric 3, druid 3, hunter 3, oracle 3, ranger 3, shaman 3, warpriest 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'current or portion of current up to 20 feet wide and 100 feet long', NULL, '1 round', 'Will half', 'yes', 'This functions as life current except you infuse the current with negative energy, so it heals undead and harms living creatures.', NULL, NULL, true, false)
